variants.yaml:
- type: custom-api
  title: AFL Fixture
  url: https://api.squiggle.com.au/?q=games;complete=!100
  cache: 1m
  template: |
    {{ $games := .JSON.Array "games" }}
    {{ if eq (len $games) 0 }}
      <div>No upcoming AFL games scheduled.</div>
    {{ else }}
      <div class="list list-gap-10 collapsible-container" data-collapse-after="3">
        {{ range $games }}
          <div>
            {{ if ne (.String "hteam") "" }}
              <p class="color-highlight">{{ .String "hteam" }} vs {{ .String "ateam" }}</p>
            {{ else }}
              <p>TBC</p>
            {{ end }}
            <p>{{ .String "roundname" }}, {{ .String "venue" }}</p>

            {{ if ne (.String "timestr") "" }}
              <p class="color-primary">{{ .String "timestr" }}</p>
              <p>{{ .Int "hgoals" }}.{{ .Int "hbehinds" }} ({{ .Int "hscore" }}) | {{ .Int "agoals" }}.{{ .Int "abehinds" }} ({{ .Int "ascore" }})</p>
            {{ else }}
              {{ $layout := "2006-01-02 15:04:05" }}
              {{ $dt := parseLocalTime $layout (.String "date") }}
              <p>{{ formatTime "Mon 2 Jan, 3:04 PM" $dt }}</p>
            {{ end }}
          </div>
        {{ end }}
      </div>
    {{ end }}

- type: custom-api
  title: AFL Ladder
  url: https://api.squiggle.com.au/?q=standings
  cache: 15m
  template: |
    {{ $standings := .JSON.Array "standings" }}
    {{ if eq (len $standings) 0 }}
      <div>No standings data available.</div>
    {{ else }}
      <ul class="list collapsible-container" data-collapse-after="8">
        {{ range $i, $team := $standings }}
          <li class="flex items-center {{ if eq $i 0 }}color-primary{{ else if lt $i 8 }}color-highlight{{ end }}">
            <span class="grow min-width-0 text-truncate">
              {{ add $i 1 }}. {{ $team.String "name" }}
            </span>
            <span class="shrink-0 text-right">
              {{$team.Int "pts"}} ({{ $team.Int "wins" }}.{{ $team.Int "losses" }}.{{ $team.Int "draws" }})
              {{ printf "%.1f" ($team.Float "percentage") }}%
            </span>
          </li>
        {{ end }}
      </ul>
    {{ end }}

- type: custom-api
  title: Media Releases
  title-url: ${RADARR_URL}
  cache: 30m
  options:
    service: radarr          # sonarr, radarr, or lidarr
    type: upcoming           # upcoming, recent, or missing
    size: medium             # small, medium, large, or huge
    collapse-after: 3
    show-grabbed: false
    interval: 20             # optional, days
    #sort-time: asc          # optional, asc or desc (default)
    #cover-proxy: "https://proxy.example.com/radarrcover" # optional
    api-base-url: ${RADARR_API_URL}
    key: ${RADARR_KEY}
    url: ${RADARR_URL}       # optional
  template: |
    {{ $collapseAfter := .Options.IntOr "collapse-after" 5 }}
    {{ $showGrabbed := .Options.BoolOr "show-grabbed" false }}
    {{ $sortTime := .Options.StringOr "sort-time" "desc" }}
    {{ $coverProxy := .Options.StringOr "cover-proxy" "" }}
    {{ $size := .Options.StringOr "size" "medium" }}
    {{ $service := .Options.StringOr "service" "" }}
    {{ $type := .Options.StringOr "type" "" }}
    {{ $intervalH := .Options.IntOr "interval" 0 | mul 24 }}

    {{ $now := now | formatTime "2006-01-02T15:04:05" }}
    {{ $posInterval := (offsetNow (printf "+%dh" $intervalH)) | formatTime "2006-01-02T15:04:05" }}
    {{ $negInterval := (offsetNow (printf "-%dh" $intervalH)) | formatTime "2006-01-02T15:04:05" }}

    {{ $apiBaseUrl := .Options.StringOr "api-base-url" "" }}
    {{ $key := .Options.StringOr "key" "" }}
    {{ $url := .Options.StringOr "url" $apiBaseUrl }}

    {{ if or (and (ne $service "sonarr") (ne $service "radarr") (ne $service "lidarr"))
             (and (ne $type "upcoming") (ne $type "recent") (ne $type "missing")) 
             (eq $apiBaseUrl "") (eq $key "") (eq $url "") }}
      <div class="widget-error-header">
          <div class="color-negative size-h3">ERROR</div>
          <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
          </svg>
        </div>
        <p class="break-all">
          Some options are not set or malformed
            <table style="border-spacing: 1rem;">
              <tr><td>service</td><td>{{ $service }}</td><td>must be sonarr, radarr, or lidarr</td></tr>
              <tr><td>type</td><td>{{ $type }}</td><td>must be upcoming, recent, or missing</td></tr>
              <tr><td>api-base-url</td><td>{{ $apiBaseUrl }}</td><td>should include http(s):// and port if needed</td></tr>
              <tr><td>key</td><td>{{ $key }}</td><td></td></tr>
            </table> 
        </p>
    {{ else }}
      {{ $requestUrl := "" }}

      {{ if eq $service "sonarr" }}
        {{ if eq $type "recent" }}
          {{ $requestUrl = printf "%s/api/v3/history/since?includeSeries=true&includeEpisode=true&eventType=grabbed&date=%s" $apiBaseUrl $negInterval }}
        {{ else if eq $type "missing" }}
          {{ $requestUrl = printf "%s/api/v3/wanted/missing?page=1&pageSize=50&includeSeries=true" $apiBaseUrl }}
        {{ else if eq $type "upcoming" }}
          {{ $requestUrl = printf "%s/api/v3/calendar?includeSeries=true&start=%s&end=%s" $apiBaseUrl $now $posInterval }}
        {{ end }}

      {{ else if eq $service "radarr" }}
        {{ if eq $type "recent" }}
          {{ $requestUrl = printf "%s/api/v3/history/since?includeMovie=true&eventType=grabbed&date=%s" $apiBaseUrl $negInterval }}
        {{ else if eq $type "missing" }}
          {{ $requestUrl = printf "%s/api/v3/wanted/missing?page=1&pageSize=50" $apiBaseUrl }}
        {{ else if eq $type "upcoming" }}
          {{ $requestUrl = printf "%s/api/v3/calendar?start=%s&end=%s" $apiBaseUrl $now $posInterval }}
        {{ end }}

      {{ else if eq $service "lidarr" }}
        {{ if eq $type "recent" }}
          {{ $requestUrl = printf "%s/api/v1/history/since?includeArtist=true&includeAlbum=true&eventType=grabbed&date=%s" $apiBaseUrl $negInterval }}
        {{ else if eq $type "missing" }}
          {{ $requestUrl = printf "%s/api/v1/wanted/missing?page=1&pageSize=50&includeArtist=true" $apiBaseUrl }}
        {{ else if eq $type "upcoming" }}
          {{ $requestUrl = printf "%s/api/v1/calendar?includeArtist=true&start=%s&end=%s" $apiBaseUrl $now $posInterval }}
        {{ end }}
      {{ end }}

      {{ $data := newRequest $requestUrl
        | withHeader "Accept" "application/json"
        | withHeader "X-Api-Key" $key
        | getResponse }}

      <ul class="list list-gap-14 collapsible-container single-line-titles" data-collapse-after="{{ $collapseAfter }}">
        {{ $array := "" }}
        {{ $sortByField := "" }}
        {{ $itemDisplayed := false }}
        {{ $itemDate := "" }}
        {{ $isAvailable := false }}

        {{ if eq $type "missing" }}
          {{ $array = "records" }}
          {{ if eq $service "sonarr" }}
            {{ $sortByField = "airDateUtc" }}
          {{ else }}
            {{ $sortByField = "releaseDate" }}
          {{ end }}
        {{ else if eq $type "recent" }}
          {{ $sortByField = "date" }}
        {{ else }}
          {{ if eq $service "sonarr" }}
            {{ $sortByField = "airDateUtc" }}
          {{ else }}
            {{ $sortByField = "releaseDate" }}
          {{ end }}
        {{ end }}

        {{ range $data.JSON.Array $array | sortByTime $sortByField "rfc3339" $sortTime }}

          {{ if eq $service "sonarr" }}
            {{ $itemDate = .String "airDateUtc" | parseTime "RFC3339" }}
            {{ $itemDate = $itemDate.In now.Location | formatTime "2006-01-02T15:04:05" }}
            {{ $isAvailable = true }}
          {{ else if eq $service "radarr"}}
            {{ $isAvailable = .Bool "isAvailable" }}
            {{ $itemDate = .String "releaseDate" }}
          {{ else if eq $service "lidarr"}}
            {{ $itemDate = .String "releaseDate" }}
            {{ $isAvailable = true }}
          {{ end }}

          {{ if or (eq $type "upcoming") (eq $type "recent") (and (or (and (gt $itemDate $negInterval) ((lt $itemDate $now ))) (eq $intervalH 0))  $isAvailable) }}
            {{ $itemDisplayed = true }}
            {{ $title := "" }}
            {{ $subtitle := "" }}
            {{ $coverUrl := "" }}
            {{ $status := "" }}
            {{ $coverBase := "" }}
            {{ $height := "" }}
            {{ $width := "" }}
            {{ $popoverTitle := "" }}
            {{ $popoverSubtitle := "" }}
            {{ $popoverSummary := "" }}
            {{ $summary := "" }}
            {{ $link := "" }}
            {{ $grabbed := false }}
            {{ $date := now }}
            {{ $datetype := "" }}
            {{ $seString := "" }}
            {{ $genres := "" }}
            {{ $buttonJustify := "left" }}


            {{ if eq $service "sonarr" }}
              {{ $series := "" }}
              {{ if eq $coverProxy "" }}
                {{ $coverBase = printf "%s/api/v3/mediacover" $apiBaseUrl }}
                {{ $coverUrl = printf "%s/%s/poster-500.jpg?apikey=%s" $coverBase (.String "seriesId") $key }}
              {{ else }}
                {{ $coverBase = $coverProxy }}
                {{ $coverUrl = printf "%s/%s/poster-500.jpg" $coverBase (.String "seriesId") }}
              {{ end }}
              {{ $title = .String "series.title" }}
              {{ $link = printf "%s/series/%s#" $url (.String "series.titleSlug") }}
              {{ $series = .Get "series" }}
              {{ $genres = $series.Get "genres" }}

              {{ if eq $type "recent" }}
                {{ $date = .String "date" | parseLocalTime "RFC3339" }}
                {{ $date = $date.In now.Location }}
                {{ $subtitle = .String "episode.title" }}
                {{ $summary = .String "episode.overview" }}
                {{ $seString = printf "S%02dE%02d" (.Int "episode.seasonNumber") (.Int "episode.episodeNumber") }}
                {{ $datetype = "Downloaded" }}

                {{ if $showGrabbed }}
                  {{ $popoverTitle = .String "episode.title" }}
                  {{ $popoverSubtitle = $seString }}
                  {{ $popoverSummary = .String "episode.overview" }}
                  {{ if .Bool "episode.hasFile" }}
                    {{ $grabbed = true }}
                  {{ end }}
                {{ else }}
                  {{ $popoverTitle = .String "series.title" }}
                  {{ $popoverSummary = .String "series.overview" }}
                {{ end }}

              {{ else if eq $type "missing" }}
                {{ $date = .String "airDateUtc" | parseLocalTime "RFC3339" }}
                {{ $date = $date.In now.Location }}
                {{ $subtitle = .String "title" }}
                {{ $summary = .String "overview" }}
                {{ $seString = printf "S%02dE%02d" (.Int "seasonNumber") (.Int "episodeNumber") }}
                {{ $datetype = "Aired" }}
                {{ if $showGrabbed }}
                  {{ $popoverTitle = .String "title" }}
                  {{ $popoverSubtitle = $seString }}
                  {{ $popoverSummary = .String "overview" }}
                  {{ if .Bool "episode.hasFile" }}
                    {{ $grabbed = true }}
                  {{ end }}
                {{ else }}
                  {{ $popoverTitle = .String "series.title" }}
                  {{ $popoverSummary = .String "series.overview" }}
                {{ end }}
              {{ else if eq $type "upcoming" }}
                {{ $date = .String "airDateUtc" | parseLocalTime "RFC3339" }}
                {{ $date = $date.In now.Location }}
                {{ $subtitle = .String "title" }}
                {{ $summary = .String "overview" }}
                {{ $seString = printf "S%02dE%02d" (.Int "seasonNumber") (.Int "episodeNumber") }}
                {{ $datetype = "Airs" }}
                {{ if $showGrabbed }}
                  {{ $popoverTitle = .String "title" }}
                  {{ $popoverSubtitle = $seString }}
                  {{ $popoverSummary = .String "overview" }}
                  {{ if .Bool "hasFile" }}
                    {{ $grabbed = true }}
                  {{ end }}
                {{ else }}
                  {{ $popoverTitle = .String "series.title" }}
                  {{ $popoverSummary = .String "series.overview" }}
                {{ end }}
              {{ end }}


            {{ else if eq $service "radarr" }}
              {{ $movie := "" }}
              {{ $status = .String "status" }}
              {{ if eq $coverProxy "" }}
                {{ $coverBase = printf "%s/api/v3/mediacover" $apiBaseUrl }}
              {{ else }}
                {{ $coverBase = $coverProxy }}
              {{ end }}
              {{ if eq $status "announced"}}
                {{ if ne (.String "inCinemas") "" }}
                  {{ $date = (.String "inCinemas" | parseTime "RFC3339") }}
                  {{ $datetype = "In Cinemas" }}
                {{ else }}
                  {{ $date = (.String "releaseDate" | parseTime "RFC3339") }}
                  {{ $datetype = "Releases" }}
                {{ end }}
              {{ else if eq $status "inCinemas"}}
                {{ $date = (.String "releaseDate" | parseTime "RFC3339") }}
                {{ $datetype = "Releases" }}
              {{ else if eq $status "released"}}
                {{ $date = (.String "releaseDate" | parseTime "RFC3339") }}
                {{ $datetype = "Released" }}
              {{ end }}

              {{ if eq $type "recent" }}
                {{ if eq $coverProxy "" }}
                  {{ $coverUrl = printf "%s/%s/poster-500.jpg?apikey=%s" $coverBase (.String "movie.id") $key }}
                {{ else }}
                  {{ $coverUrl = printf "%s/%s/poster-500.jpg" $coverBase (.String "movie.id") }}
                {{ end }}
                {{ $datetype = "Downloaded" }}
                {{ $date = (.String "date" | parseTime "RFC3339") }}
                {{ $title = .String "movie.title" }}
                {{ $subtitle = "" }}
                {{ $summary = .String "movie.overview" }}
                {{ $popoverTitle = .String "movie.title" }}
                {{ $popoverSubtitle = printf "%s %s" $datetype ($date | formatTime "1/2/2006") }}
                {{ $popoverSummary = .String "movie.overview" }}
                {{ $link = printf "%s/movie/%s#" $url (.String "movie.titleSlug") }}
                {{ $movie = .Get "movie" }}
                {{ $genres = $movie.Get "genres" }}
                {{ if and $showGrabbed (gt (.Int "movie.movieFileId") 0) }}
                  {{ $grabbed = true }}
                {{ end }}
              {{ else }}
                {{ if eq $coverProxy "" }}
                  {{ $coverUrl = printf "%s/%s/poster-500.jpg?apikey=%s" $coverBase (.String "id") $key }}
                {{ else }}
                  {{ $coverUrl = printf "%s/%s/poster-500.jpg" $coverBase (.String "id") }}
                {{ end }}
                {{ $title = .String "title" }}
                {{ $subtitle = "" }}
                {{ $summary = .String "overview" }}
                {{ $link = printf "%s/movie/%s#" $url (.String "titleSlug") }}
                {{ $popoverTitle = .String "title" }}
                {{ $popoverSubtitle = printf "%s %s" $datetype ($date | formatTime "1/2/2006") }}
                {{ $popoverSummary = .String "overview" }}
                {{ $genres = .Get "genres" }}
                {{ if eq $type "missing" }}
                  {{ if and $showGrabbed (.Bool "movie.hasFile") }}
                    {{ $grabbed = true }}
                  {{ end }}
                {{ else }}
                  {{ if and $showGrabbed (.Bool "hasFile") }}
                    {{ $grabbed = true }}
                  {{ end }}
                {{ end }}
              {{ end }}


            {{ else if eq $service "lidarr" }}
              {{ $artist := "" }}
              {{ $album := "" }}
              {{ $albumId := "" }}
              {{ if eq $coverProxy "" }}
                {{ $coverBase = printf "%s/api/v1/mediacover" $apiBaseUrl }}
              {{ else }}
                {{ $coverBase = $coverProxy }}
              {{ end }}

              {{ if eq $type "recent" }}
                {{ $album = .Get "album" }}
                {{ $artist = $album.Get "artist" }}
                {{ if eq $coverProxy "" }}
                  {{ $coverUrl = printf "%s/album/%s/cover-500.jpg?apikey=%s" $coverBase (.String "albumId") $key }}
                {{ else }}
                  {{ $coverUrl = printf "%s/album/%s/cover-500.jpg" $coverBase (.String "albumId") }}
                {{ end }}
                {{ $grabbed = true }}
                {{ $title = $album.String "title" }}
                {{ $date = (.String "date" | parseTime "RFC3339") }}
                {{ $datetype = "Downloaded" }}
                {{ $subtitle = $artist.String "artistName" }}
                {{ $genres = $artist.Get "genres" }}
                {{ $link = printf "%s/artist/%s#" $url ($artist.String "foreignArtistId") }}
                {{ $summary = $album.String "overview" }}
                {{ $popoverTitle = $album.String "title" }}
                {{ $popoverSubtitle = printf "%s %s" $datetype ($date | formatTime "1/2/2006") }}
                {{ $popoverSummary = $artist.String "overview" }}

              {{ else }}
                {{ $artist = .Get "artist" }}
                {{ $album = .Get "album" }}
                {{ if eq $type "missing" }}
                  {{ $datetype = "Released" }}
                {{ else }}
                  {{ $datetype = "Releases" }}
                {{ end }}
                {{ range .Array "releases" }}
                  {{ $albumId = .String "albumId" }}
                  {{ break }}
                {{ end }}
                {{ if eq $coverProxy "" }}
                  {{ $coverUrl = printf "%s/album/%s/cover-500.jpg?apikey=%s" $coverBase $albumId $key }}
                {{ else }}
                  {{ $coverUrl = printf "%s/album/%s/cover-500.jpg" $coverBase $albumId }}
                {{ end }}
                {{ $date = (.String "releaseDate" | parseTime "RFC3339") }}
                {{ $title = .String "title" }}
                {{ $subtitle = $artist.String "artistName" }}
                {{ $summary = $album.String "overview" }}
                {{ $genres = $artist.Get "genres" }}
                {{ $link = printf "%s/artist/%s#" $url ($artist.String "foreignArtistId") }}
                {{ $popoverTitle = .String "title" }}
                {{ $popoverSubtitle = printf "%s %s" $datetype ($date | formatTime "1/2/2006") }}
                {{ $popoverSummary = .String "artist.overview" }}
              {{ end }}
            {{ end }}

            {{ if eq $size "small" }}
              {{ $buttonJustify = "right" }}
              {{ $height = "9rem" }}
              {{ if eq $service "lidarr" }}
                {{ $width = "9rem" }}
              {{ else }}
                {{ $width = "6rem" }}
              {{ end }}
            {{ else if eq $size "medium" }}
              {{ $height = "12rem" }}
              {{ if eq $service "lidarr" }}
                {{ $width = "12rem" }}
              {{ else }}
                {{ $width = "8rem" }}
              {{ end }}
            {{ else if eq $size "large" }} 
              {{ $height = "15rem" }}
              {{ if eq $service "lidarr" }}
                {{ $width = "15rem" }}
              {{ else }}
                {{ $width = "10rem" }}
              {{ end }}
            {{ else if eq $size "huge" }} 
              {{ $height = "18rem" }}
              {{ if eq $service "lidarr" }}
                {{ $width = "18rem" }}
              {{ else }}
                {{ $width = "12rem" }}
              {{ end }}
            {{ end }}

            <li style="position: relative;">
              <div class="flex gap-10 items-start thumbnail-container thumbnail-parent">
                <div>
                  <div data-popover-type="html" data-popover-position="above" data-popover-show-delay="500" style="width: {{ $width  }}; height: {{ $height }}; align-content: center;">
                    <div data-popover-html>
                      <div style="margin: 5px;">
                        <strong class="size-h4 color-primary" title="{{ $popoverTitle }}">{{ $popoverTitle }}</strong>
                        <div class="size-h4 text-truncate text-very-compact color-subdue" title="{{ $popoverSubtitle }}">{{ $popoverSubtitle }}</div>
                        <p class="margin-top-20" style="overflow-y: auto; text-align: justify; max-height: 20rem;">
                          {{ if ne $popoverSummary "" }}
                            {{ $popoverSummary }}
                          {{ else }}
                            TBA
                          {{ end }}
                        </p>
                       {{ if gt (len ($genres.Array "")) 0 }}
                        <ul class="attachments margin-top-20">
                          {{ range $genres.Array "" }}
                            <li>{{ .String "" }}</li>
                          {{ end }}
                        </ul>
                        {{ end }}
                      </div>
                    </div>
                    <img class="thumbnail" src="{{ $coverUrl }}" alt="Cover for {{ .String "title" }}" loading="lazy" style="width: 100%; height: 100%; box-shadow: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1); object-fit: cover; border-radius: 0.5rem;">
                  </div>
              </div>
                <div class="shrink min-width-0" style="height: 9rem; position: relative; padding-top: 5px; padding-right: 5px;">
                  <strong class="size-h4 block text-truncate color-primary" title="{{ $title }}">{{ $title }}</strong>
                  <div class="text-truncate text-very-compact" title="{{ $subtitle }}">{{ $subtitle }}</div>
                  <div class="text-very-compact text-truncate">
                    {{ if eq $service "sonarr" }}
                      <div>{{ $seString }} - {{ $datetype }} {{ $date.Format "1/2 03:04PM" }}</div>
                    {{ else }}
                      <span>{{ $datetype }} {{ $date.Format "1/2" }}</span>
                    {{ end }}
                  </div>

                  {{ if $showGrabbed }}
                    {{ if eq $buttonJustify "right" }}
                      </div>
                      <a href="{{ $link }}" class="bookmarks-link size-h4 color-primary" target="_blank" rel="noreferrer"
                        style="position: absolute; bottom: 1rem; right: 1rem;
                          {{ if $grabbed }} color: var(--color-positive); border: 1px solid var(--color-positive); {{ else }} color: var(--color-negative); border: 1px solid var(--color-negative); {{ end }}
                          font-weight: bold; padding: 2px 5px; border-radius: 3px; display: inline-block; margin-top: 5px; text-decoration: none;">
                      {{ if $grabbed }}Grabbed{{ else }}Missing{{ end }}
                      </a>
                    {{ else }}
                      <a href="{{ $link }}" class="bookmarks-link size-h4 color-primary" target="_blank" rel="noreferrer"
                        style="{{ if $grabbed }} color: var(--color-positive); border: 1px solid var(--color-positive); {{ else }} color: var(--color-negative); border: 1px solid var(--color-negative); {{ end }}
                          font-weight: bold; padding: 2px 5px; border-radius: 3px; display: inline-block; margin-top: 5px; text-decoration: none;">
                      {{ if $grabbed }}Grabbed{{ else }}Missing{{ end }}
                      </a>
                      </div>
                    {{ end }}
                  {{ else }}
                    <div class="{{ if eq $size "small" }}text-truncate{{ if eq $service "radarr" }} margin-top-5{{ end }}{{ else }}text-truncate-2-lines margin-top-5{{ end }}">
                      {{ $summary }}
                    </div>
                  {{ end }}
              </div>
            </li>
          {{ end }}
        {{ end }}
        {{ if not $itemDisplayed }}
          <li>No items found.</li>
        {{ end }}
      </ul>
    {{ end }}

- type: custom-api
  title: Listen Again
  frameless: true
  cache: 5m
  options:
    base-url: ${AUDIOBOOKSHELF_URL}
    api-key: ${AUDIOBOOKSHELF_KEY}
    library: "Podcasts"
    shelf: "continue-listening"
    small-column: false
    show-thumbnail: false
    thumbnail-aspect-ratio: "square"
  template: |
    {{/* Required config options */}}
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $library := .Options.StringOr "library" "" }}
    {{ $shelf := .Options.StringOr "shelf" "" }}

    {{/* Optional config options */}}
    {{ $isSmallColumn:= .Options.BoolOr "small-column" false }}
    {{ $thumbAspectRatio := .Options.StringOr "thumbnail-aspect-ratio" "" }}
    {{ $showThumbnail := .Options.BoolOr "show-thumbnail" false }}
    {{ $showProgressBar := .Options.BoolOr "progress-bar" true }}

    {{/* Error message template */}}
    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{/* Check required fields */}}
    {{ if or (eq $baseURL "") (eq $apiKey "") (eq $library "") (eq $shelf "") }}
      {{ template "errorMsg" "Some required options are not set." }}
    {{ else }}

      {{ $token := concat "Bearer " $apiKey }}

      {{ $librariesCall := newRequest (print $baseURL "/api/libraries")
          | withHeader "Authorization" $token
          | getResponse }}
      {{ $libraries := $librariesCall.JSON.Array "libraries" }}
      {{ $items := "" }}
      {{ range $libraries }}
        {{ $libraryName := .String "name" }}
        {{ if eq $libraryName $library }}
          {{ $libraryId := .String "id" }}

          {{ $personalizedViewCall := newRequest (print $baseURL "/api/libraries/" $libraryId "/personalized?include=rssfeed,numEpisodesIncomplete,share")
              | withHeader "Authorization" $token
              | getResponse }}
          {{ $shelfs := $personalizedViewCall.JSON.Array "" }}
          {{ range $shelfs }}
            {{ $shelfId := .String "id" }}
            {{ if eq $shelfId $shelf }}
              {{ $items = .Array "entities" }}
            {{ end }}
          {{ end }}
        {{ end }}
      {{ end }}

      {{ if eq (len $items) 0 }}
        <p>No items found, start streaming something!</p>
      {{ else }}
        {{/* Display the item carousel */}}
        <div class="carousel-container show-right-cutoff">
          <div class="cards-horizontal carousel-items-container">
            {{ range $n, $item := $items }}
              {{ $mediaType := $item.String "mediaType" }}

              {{ $itemID := $item.String "id" }}
              {{ $linkURL := print $baseURL "/audiobookshelf/item/" $itemID }}
              {{ $thumbURL := print $baseURL "/api/items/" $itemID "/cover?token=" $apiKey }}

              {{ $title := "" }}
              {{ $subtitle := "" }}
              {{ $newEpisodes := 0 }}

              {{ if eq $mediaType "book" }}
                {{ $title = $item.String "media.metadata.title" }}
                {{ $subtitle = $item.String "media.metadata.authorName" }}
              {{ else if eq $mediaType "podcast" }}
                {{ $title = $item.String "recentEpisode.title" }}
                {{ $subtitle = $item.String "media.metadata.title" }}
                {{ $newEpisodes = $item.Int "numEpisodesIncomplete" }}
              {{ end }}

              {{ $progressPercent := ""}}

              {{ if and $showThumbnail (or (eq $shelf "continue-listening" ) (eq $shelf "listen-again")) }}
                {{ if eq $mediaType "book" }}
                  {{ $getMediaProgressCall := newRequest (print $baseURL "/api/me/progress/" $itemID )
                      | withHeader "Authorization" $token
                      | getResponse }}
                  {{ $progress := $getMediaProgressCall.JSON.Float "progress" }}
                  {{ $progressPercent = printf "%f" (mul 100 $progress) }}
                {{ else if eq $mediaType "podcast" }}
                  {{ $libraryItemID := $item.String "recentEpisode.libraryItemId" }}
                  {{ $getMediaProgressCall := newRequest (print $baseURL "/api/me/progress/" $libraryItemID )
                      | withHeader "Authorization" $token
                      | getResponse }}
                  {{ $progress := $getMediaProgressCall.JSON.Float "progress" }}
                  {{ $progressPercent = printf "%f" (mul 100 $progress) }}
                {{ end }}
              {{ end }}

              <a class="card widget-content-frame" href="{{ $linkURL | safeURL }}">
                {{ if $showThumbnail }}
                  <div style="position: relative;">
                    <img src="{{ $thumbURL | safeURL }}"
                      alt="{{ $title }} thumbnail"
                      loading="lazy"
                      class="media-server-thumbnail shrink-0"
                      style="
                        object-fit: fill;
                        border-radius: var(--border-radius) var(--border-radius) 0 0;
                        width: 100%;
                        display: block;
                        {{ if eq $thumbAspectRatio "square" }}aspect-ratio: 1;
                        {{ else if eq $thumbAspectRatio "portrait" }}aspect-ratio: 2/3;
                        {{ else if eq $thumbAspectRatio "landscape" }}aspect-ratio: 16/9;
                        {{ else }}aspect-ratio: initial;
                        {{ end }}
                      "
                    />

                    {{ if and ($showProgressBar) (not (eq $progressPercent "")) }}
                      <div style="
                        position: absolute;
                        bottom: 8px;
                        left: 8px;
                        right: 8px;
                        height: 6px;
                        border-radius: var(--border-radius);
                        overflow: hidden;
                        background-color: rgba(255, 255, 255, 0.2);
                      ">
                        <div style="
                          width: {{ print $progressPercent "%" }};
                          height: 100%;
                          border-radius: var(--border-radius) 0 0 var(--border-radius);
                          background-color: var(--color-primary)
                        "></div>
                      </div>
                    {{ end }}
                  </div>
                {{ end }}

                <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                  <ul class="flex flex-column justify-evenly margin-bottom-3 {{ if $isSmallColumn }}size-h6{{ end }}" style="height: 100%;">
                    {{ if eq $newEpisodes 0 }}
                      <li class="color-primary text-truncate">{{ $title }}</li>
                      <li class="text-truncate">{{ $subtitle }}</li>
                    {{ else }}
                      <ul class="list-horizontal-text flex-nowrap">
                        <li class="color-primary shrink-0">{{ $newEpisodes }}</li>
                        <li class="text-truncate">{{ $subtitle }}</li>
                      </ul>
                    {{ end }}
                  </ul>
                </div>
              </a>
            {{ end }}
          </div>
        </div>
      {{ end }}
    {{ end }}

- type: custom-api
  title: Audiobookshelf
  title-url: ${AUDIOBOOKSHELF_URL}
  options:
    base-url: ${AUDIOBOOKSHELF_URL}
    api-key: ${AUDIOBOOKSHELF_KEY}
  cache: 5m
  template: |
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}

    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{ $bearer := printf "Bearer %s" $apiKey }}
    {{ $librariesRequestURL := concat $baseURL "/api/libraries" }}
    {{ $librariesResponse := newRequest $librariesRequestURL
      | withHeader "Content-Type" "application/json"
      | withHeader "Authorization" $bearer
      | getResponse }}

    {{ if $librariesResponse.JSON.Exists "libraries" }}
      {{ $all_libraries := $librariesResponse.JSON.Array "libraries" }}

      {{ $books_count := 0 }}
      {{ $books_duration := 0 }}
      {{ $podcasts_count := 0 }}
      {{ $podcasts_duration := 0 }}

      {{ range $library := $all_libraries }}
        {{ $lib_id := $library.String "id" }}
        {{ $lib_request_url := concat $baseURL "/api/libraries/" $lib_id "/stats"}}
        {{ $lib_stats := newRequest $lib_request_url
          | withHeader "Content-Type" "application/json"
          | withHeader "Authorization" $bearer
          | getResponse }}
        {{ $lib_type := $library.String "mediaType" }}
        {{ $lib_item_count := $lib_stats.JSON.Int "totalItems" }}
        {{ $lib_total_duration := $lib_stats.JSON.Int "totalDuration" }}
        {{ if eq $lib_type "book" }}
          {{ $books_count = add $books_count $lib_item_count }}
          {{ $books_duration = add $books_duration $lib_total_duration }}
        {{ else if eq $lib_type "podcast" }}
          {{ $podcasts_count = add $podcasts_count $lib_item_count }}
          {{ $podcasts_duration = add $podcasts_duration $lib_total_duration }}
        {{ end }}
      {{ end }}

      {{ $books_duration = duration (concat (printf "%d" $books_duration) "s") }}
      {{ $podcasts_duration = duration (concat (printf "%d" $podcasts_duration) "s") }}

      <div class="flex flex-column gap-5">
        <div class="flex justify-between text-center">
          <div>
            <div class="color-highlight size-h3">{{ $books_count }}</div>
            <div class="size-h5 uppercase">Books</div>
          </div>
          <div>
            <div class="color-highlight size-h3">{{ $books_duration }}</div>
            <div class="size-h5 uppercase">Duration</div>
          </div>
          <div>
            <div class="color-highlight size-h3">{{ $podcasts_count }}</div>
            <div class="size-h5 uppercase">Podcasts</div>
          </div>
          <div>
            <div class="color-highlight size-h3">{{ $podcasts_duration }}</div>
            <div class="size-h5 uppercase">Duration</div>
          </div>
        </div>
      </div>
    {{ else }}
      {{ template "errorMsg" "Could not fetch data from API!" }}
    {{ end }}

- type: custom-api
  title: Config Backups
  cache: 1m
  subrequests:
    plan:
      url: ${BACKREST_URL}/v1.Backrest/GetOperations
      method: POST
      headers:
        Content-Type: application/json
      body-type: json
      body:
        selector:
          planId: ${BACKREST_PLAN_LOCAL}
  options:
    LIMIT: 5
    PRECISION: 1
    UNIT: GB
    BACKREST_PLAN_TITLE: Local USB
  template: |
    {{ $limit := .Options.IntOr "LIMIT" 5 }}
    {{ $precision := .Options.IntOr "PRECISION" 1 }}
    {{ $unit := .Options.StringOr "UNIT" "GB" }}

    <div class="size-h6 color-highlight margin-bottom-8" style="font-weight: 700; margin-top: 6px;">
      {{ .Options.StringOr "BACKREST_PLAN_TITLE" "Backups" }}
    </div>
    <ul class="dynamic-columns list-gap-8 margin-bottom-20">
      {{ $count := 0 }}
      {{ range $op := (sortByInt "id" "desc" ((.Subrequest "plan").JSON.Array "operations")) }}
        {{ if lt $count $limit }}
          {{ $status := $op.String "status" }}
          {{ $snap := $op.String "snapshotId" }}
          {{ $bytes := $op.Float "operationIndexSnapshot.snapshot.summary.totalBytesProcessed" }}
          {{ $isBackup := $op.Exists "operationBackup" }}
          {{ $isHook := $op.Exists "operationRunHook" }}
          {{ $ms := $op.Int "unixTimeEndMs" }}
          {{ $sec := div $ms 1000 }}
          {{ $secStr := printf "%d" $sec }}
          {{ $ended := (parseTime "unix" $secStr) | formatTime "Jan 02" }}
          {{ $msg := $op.String "displayMessage" }}

          {{ if or (and (eq $status "STATUS_SUCCESS") (gt $bytes 0.0)) (and (eq $status "STATUS_ERROR") $isBackup (not $isHook)) }}
            <div class="flex items-center gap-12">
              <div class="size-h5" style="min-width: 70px;">
                {{ $ended }}
              </div>
              <div class="size-h5 text-truncate block grow">
                {{ if $snap }}{{ replaceMatches "^(.{8}).*" "$1" $snap }}{{ else }}—{{ end }}
              </div>
              <div class="size-h5" style="min-width: 90px; text-align: center;">
                {{ if and (eq $status "STATUS_SUCCESS") (gt $bytes 0.0) }}
                  {{ printf "%.*f %s" $precision (div $bytes 1073741824) $unit }}
                {{ end }}
              </div>
              <div class="monitor-site-status-icon-compact"
                   data-popover-type="html" data-popover-position="above" data-popover-show-delay="300">
                {{ if eq $status "STATUS_SUCCESS" }}
                  <svg fill="var(--color-positive)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                    <path fill-rule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5Z" clip-rule="evenodd"/>
                  </svg>
                  <div data-popover-html>
                    <div class="size-h5">Completed successfully</div>
                  </div>
                {{ else if eq $status "STATUS_ERROR" }}
                  <svg fill="var(--color-negative)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                    <path fill-rule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16ZM7.646 7.646a.5.5 0 0 1 .708 0L10 9.293l1.646-1.647a.5.5 0 0 1 .708.708L10.707 10l1.647 1.646a.5.5 0 0 1-.708.708L10 10.707l-1.646 1.647a.5.5 0 0 1-.708-.708L9.293 10 7.646 8.354a.5.5 0 0 1 0-.708Z" clip-rule="evenodd"/>
                  </svg>
                  <div data-popover-html>
                    <div class="flex items-center gap-8">
                      <svg style="width: 1.5rem; height: 1.5rem;" fill="var(--color-negative)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                        <path fill-rule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16ZM7.646 7.646a.5.5 0 0 1 .708 0L10 9.293l1.646-1.647a.5.5 0 0 1 .708.708L10.707 10l1.647 1.646a.5.5 0 0 1-.708.708L10 10.707l-1.646 1.647a.5.5 0 0 1-.708-.708L9.293 10 7.646 8.354a.5.5 0 0 1 0-.708Z" clip-rule="evenodd"/>
                      </svg>
                      <div class="size-h5"> Error message</div>
                    </div>
                    <div class="text-compact" style="max-width: 28rem; max-height: 14rem; overflow-y: auto; white-space: pre-wrap; margin: 0;">
    {{ if $msg }}{{ $msg }}{{ else }}No message{{ end }}
                    </div>
                  </div>
                {{ end }}
              </div>
            </div>
            {{ $count = add $count 1 }}
          {{ end }}
        {{ end }}
      {{ end }}
    </ul>

- type: custom-api
  title: Beszel Metrics
  url: http://${BESZEL_URL}/api/collections/systems/records
  method: GET
  options:
    redirect-url: "" # You must use "" and http:// or https://
  headers:
    Authorization: Bearer ${BESZEL_TOKEN}
    Accept: application/json
  template: |
    {{ $redirect := .Options.StringOr "redirect-url" "" }}
    {{ $newTab := .Options.BoolOr "in-new-tab" false }}
    {{ $hideKernel := .Options.BoolOr "hide-kernel" false }}
    {{ $hideUptime := .Options.BoolOr "hide-uptime" false }}
    {{ $hideCPUInfo := .Options.BoolOr "hide-cpu-info" false }}
    {{ $hideIP := .Options.BoolOr "hide-ip" false }}
    {{ $collapsible := .Options.BoolOr "collapsible" false }}
    {{ $items := .JSON.Array "items" }}
    {{ range $items }}
      {{ $info := .Get "info" }}
      {{ $name := .String "name" }}
      {{ $link := "" }}
      {{ if ne $redirect "" }}
        {{ $link = printf "%s/system/%s" $redirect $name }}
      {{ end }}
      <div style="font-size: 1.15em;">
        {{ if eq (.String "status") "up" }}
          <span class="status-dot color-positive">●</span>
        {{ else }}
          <span class="status-dot color-negative">●</span>
        {{ end }}
        {{ if ne $redirect "" }}
          <a class="color-highlight text-truncate" href="{{ printf "%s/system/%s" $redirect $name | safeURL }}" {{ if $newTab }}target="_blank" rel="noopener"{{ end }}>
            {{ $name }}{{ if not $hideIP }} ({{ .String "host" }}){{ end }}
          </a>
        {{ else }}
          <span class="color-highlight text-truncate">
            {{ $name }}{{ if not $hideIP }} ({{ .String "host" }}){{ end }}
          </span>
        {{ end }}
      </div>
      {{ if $collapsible }}
        <details class="margin-top-5">
          <summary class="size-h5 color-subtle" style="cursor: pointer;">Metrics</summary>
          <div class="margin-top-5">
            {{ if not $hideKernel }}
              <p style="font-size: 1em;">Kernel: {{ $info.String "k" }}</p>
            {{ end }}
            {{ if not $hideUptime }}
              {{ $uptimeSec := $info.Float "u" }}
              {{ if ge $uptimeSec 86400.0 }}
                <p style="font-size: 1em;">Uptime: {{ printf "%.2f" (mul $uptimeSec 0.000011574) }}d</p>
              {{ else }}
                <p style="font-size: 1em;">Uptime: {{ printf "%.2f" (mul $uptimeSec 0.000277778) }}h</p>
              {{ end }}
            {{ end }}
            {{ if not $hideCPUInfo }}
              <p style="font-size: 1em;">CPU: {{ replaceAll "CPU " "" ($info.String "m") }}</p>
            {{ end }}
            <p style="font-size: 1em; margin-top: 0.5em;">📊 Cpu: {{ $info.Float "cpu" }}%</p>
            <p style="font-size: 1em;">🧠 Memory: {{ $info.Float "mp" }}%</p>
            <p style="font-size: 1em;">💾 Disk: {{ $info.Float "dp" }}%</p>
          </div>
        </details>
      {{ else }}
        <div class="margin-top-5">
          {{ if not $hideKernel }}
            <p style="font-size: 1em;">Kernel: {{ $info.String "k" }}</p>
          {{ end }}
          {{ if not $hideUptime }}
            {{ $uptimeSec := $info.Float "u" }}
            {{ if ge $uptimeSec 86400.0 }}
              <p style="font-size: 1em;">Uptime: {{ printf "%.2f" (mul $uptimeSec 0.000011574) }}d</p>
            {{ else }}
              <p style="font-size: 1em;">Uptime: {{ printf "%.2f" (mul $uptimeSec 0.000277778) }}h</p>
            {{ end }}
          {{ end }}
          {{ if not $hideCPUInfo }}
            <p style="font-size: 1em;">CPU: {{ replaceAll "CPU " "" ($info.String "m") }}</p>
          {{ end }}
          <p style="font-size: 1em; margin-top: 0.5em;">📊 Cpu: {{ $info.Float "cpu" }}%</p>
          <p style="font-size: 1em;">🧠 Memory: {{ $info.Float "mp" }}%</p>
          <p style="font-size: 1em;">💾 Disk: {{ $info.Float "dp" }}%</p>
        </div>
      {{ end }}
    {{ end }}

- type: custom-api
  title: Server Stats
  cache: 5m
  options:
    base-url: ${BESZEL_URL}
    # required for API token authentication
    api-key: ${BESZEL_TOKEN}
    # required for e-mail + password authentication
    # email: ${BESZEL_EMAIL}
    # password: ${BESZEL_PASSWORD}
  template: |
    {{/* Required config options */}}
    {{ $baseURL := .Options.StringOr "base-url" "" }}

    {{/* Required config options for API token authentication */}}
    {{ $apiKey := .Options.StringOr "api-key" "" }}

    {{/* Required config options for email + password authentication */}}
    {{ $email := .Options.StringOr "email" "" }}
    {{ $password := .Options.StringOr "password" "" }}

    {{/* Error message template */}}
    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{ define "formatGigabytes" }}
      {{ $value := . }}
      {{ $label := "GB" }}
      {{- if lt $value 1.0 }}
        {{ $value = mul $value 1000.0 }}
        {{ $label = "MB" }}
      {{- else if lt $value 1000.0 }}
      {{ else }}
        {{ $value = div $value 1000.0 }}
        {{ $label = "TB" }}
      {{ end }}
      {{ printf "%.1f" $value }} <span class="color-base size-h5">{{ $label }}</span>
    {{ end }}

    {{/* Check required fields */}}
    {{ if or (eq $baseURL "") (and (eq $apiKey "") (or (eq $email "") (eq $password ""))) }}
      {{ template "errorMsg" "Some required options are not set." }}
    {{ else }}

      {{ $token := .}}
      {{ if not (eq $apiKey "") }}
        {{ $token = concat "Bearer " $apiKey }}
      {{ else }}
        {{ $authResponse := newRequest (print $baseURL "/api/collections/users/auth-with-password")
            | withParameter "fields" "token"
            | withHeader "Content-Type" "application/json"
            | withStringBody (printf `{"identity": "%s", "password": "%s"}` $email $password)
            | getResponse }}
        {{ $jwtToken := $authResponse.JSON.String "token" }}
        {{ $token = concat "Bearer " $jwtToken }}
      {{ end }}

      {{ $systemsResponse := newRequest (print $baseURL "/api/collections/systems/records")
          | withHeader "Authorization" $token
          | getResponse }}
      {{ $systems := $systemsResponse.JSON.Array "items" }}


      {{ range $n, $system := $systems }}
        {{ $status := $system.String "status" }}

        {{ $systemStatsRequest := newRequest (print $baseURL "/api/collections/system_stats/records")
            | withHeader "Authorization" $token
            | withParameter "sort" "-created"
            | withParameter "page" "1"
            | withParameter "perPage" "1"
            | withParameter "filter" (print "type='1m'&&system='" ($system.String "id") "'")
            | getResponse }}

        {{ $systemStatItems := $systemStatsRequest.JSON.Array "items" }}

        {{ $hostname := $system.String "name" }}
        {{ $uptimeSec := $system.Float "info.u" }}

        {{ $systemTemp := $system.Float "info.dt"}}

        {{ $cpuLoad := $system.Float "info.cpu" }}
        {{ $cpuLoad1m := $system.Float "info.l1" }}
        {{ $cpuLoad15m := $system.Float "info.l15" }}

        {{ $memoryUsedPercent := $system.Float "info.mp" }}

        {{ $rootUsedPercent := $system.Float "info.dp" }}

        {{ $hasStats := false }}
        {{ $systemStats := "" }}

        {{ $memoryTotalGb := 0.0 }}
        {{ $memoryUsedGb := 0.0 }}
        {{ $swapTotalGb := 0.0 }}
        {{ $swapUsedGb := 0.0 }}
        {{ $swapUsedPercent := 0.0 }}
        {{ $rootTotalGb := 0.0 }}
        {{ $rootUsedGb := 0.0 }}

        {{ if gt (len $systemStatItems) 0 }}
          {{ $hasStats = true }}
          {{ $systemStats = index $systemStatItems 0 }}

          {{ $memoryTotalGb = $systemStats.Float "stats.m" }}
          {{ $memoryUsedGb = $systemStats.Float "stats.mu" }}

          {{ $swapTotalGb = $systemStats.Float "stats.s" }}
          {{ $swapUsedGb = $systemStats.Float "stats.su" }}
          {{ $swapUsedPercent = mul (div $swapUsedGb $swapTotalGb) 100.0 }}

          {{ $rootTotalGb = $systemStats.Float "stats.d" }}
          {{ $rootUsedGb = $systemStats.Float "stats.du" }}
        {{ end }}

        <div class="server">
          <div class="server-info">
            <div class="server-details">
              <div class="server-name color-highlight size-h3">{{ $hostname }}</div>
              <div>
                {{ if eq $status "up" }}
                  <span>{{ printf "%.1f" (mul $uptimeSec 0.000011574) }}d</span> uptime
                {{ else }}
                  unreachable
                {{ end }}
              </div>
            </div>
            <div class="shrink-0"{{ if eq $status "up" }} data-popover-type="html" data-popover-margin="0.2rem" data-popover-max-width="400px"{{ end }}>
              {{- if eq $status "up" }}
              <div data-popover-html>
                <div class="flex">
                  <div class="size-h5 text-compact">Kernel</div>
                  <div class="value-separator"></div>
                  <div class="color-highlight">{{ $system.String "info.k" }}</div>
                </div>
                <div class="flex">
                  <div class="size-h5 text-compact">CPU</div>
                  <div class="value-separator"></div>
                  <div class="color-highlight">{{ $system.String "info.m" }}</div>
                </div>
              </div>
              {{- end }}
              <svg class="server-icon" stroke="var(--color-{{ if eq $status "up" }}positive{{ else }}negative{{ end }})" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
                <path stroke-linecap="round" stroke-linejoin="round" d="M21.75 17.25v-.228a4.5 4.5 0 0 0-.12-1.03l-2.268-9.64a3.375 3.375 0 0 0-3.285-2.602H7.923a3.375 3.375 0 0 0-3.285 2.602l-2.268 9.64a4.5 4.5 0 0 0-.12 1.03v.228m19.5 0a3 3 0 0 1-3 3H5.25a3 3 0 0 1-3-3m19.5 0a3 3 0 0 0-3-3H5.25a3 3 0 0 0-3 3m16.5 0h.008v.008h-.008v-.008Zm-3 0h.008v.008h-.008v-.008Z" />
              </svg>
            </div>
          </div>

          <div class="server-stats">
            <div class="flex-1">
              <div class="flex items-end size-h5">
                <div>CPU</div>
                {{- if ge $systemTemp 80.0 }}
                <svg class="server-spicy-cpu-icon" fill="var(--color-negative)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16" >
                  <path fill-rule="evenodd" d="M8.074.945A4.993 4.993 0 0 0 6 5v.032c.004.6.114 1.176.311 1.709.16.428-.204.91-.61.7a5.023 5.023 0 0 1-1.868-1.677c-.202-.304-.648-.363-.848-.058a6 6 0 1 0 8.017-1.901l-.004-.007a4.98 4.98 0 0 1-2.18-2.574c-.116-.31-.477-.472-.744-.28Zm.78 6.178a3.001 3.001 0 1 1-3.473 4.341c-.205-.365.215-.694.62-.59a4.008 4.008 0 0 0 1.873.03c.288-.065.413-.386.321-.666A3.997 3.997 0 0 1 8 8.999c0-.585.126-1.14.351-1.641a.42.42 0 0 1 .503-.235Z" clip-rule="evenodd" />
                </svg>
                {{- end }}
                <div class="color-highlight margin-left-auto text-very-compact">{{ $cpuLoad }} <span class="color-base">%</span></div>
              </div>
              <div data-popover-type="html">
                <div data-popover-html>
                  <div class="flex">
                    <div class="size-h5">1M AVG</div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">{{ printf "%.1f" $cpuLoad1m }} <span class="color-base size-h5">%</span></div>
                  </div>
                  <div class="flex margin-top-3">
                    <div class="size-h5">15M AVG</div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">{{ printf "%.1f" $cpuLoad15m }} <span class="color-base size-h5">%</span></div>
                  </div>
                  <div class="flex margin-top-3">
                    <div class="size-h5">TEMP C</div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">{{ printf "%.1f" $systemTemp }} <span class="color-base size-h5">°</span></div>
                  </div>
                </div>

                <div class="progress-bar progress-bar-combined">
                  <div class="progress-value{{ if ge $cpuLoad1m 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $cpuLoad1m }}"></div>
                  <div class="progress-value{{ if ge $cpuLoad15m 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $cpuLoad15m }}"></div>
                </div>
              </div>
            </div>

            <div class="flex-1">
              <div class="flex justify-between items-end size-h5">
                <div>RAM</div>
                <div class="color-highlight text-very-compact">{{ $memoryUsedPercent }} <span class="color-base">%</span></div>
              </div>
              <div data-popover-type="html">
                {{- if $hasStats }}
                <div data-popover-html>
                  <div class="flex">
                    <div class="size-h5">RAM</div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">
                      {{ template "formatGigabytes" $memoryUsedGb }} <span class="color-base size-h5">/</span> {{ template "formatGigabytes" $memoryTotalGb }}
                    </div>
                  </div>
                  {{- if gt $swapTotalGb 0.0 }}
                  <div class="flex margin-top-3">
                    <div class="size-h5">SWAP</div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">
                      {{ template "formatGigabytes" $swapUsedGb }} <span class="color-base size-h5">/</span> {{ template "formatGigabytes" $swapTotalGb }}
                    </div>
                  </div>
                  {{- end }}
                </div>
                {{- end }}
                <div class="progress-bar progress-bar-combined">
                  <div class="progress-value{{ if ge $memoryUsedPercent 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $memoryUsedPercent }}"></div>
                  {{- if gt $swapTotalGb 0.0 }}
                  <div class="progress-value{{ if ge $swapUsedPercent 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $swapUsedPercent }}"></div>
                  {{- end }}
                </div>
              </div>
            </div>

            <div class="flex-1">
              <div class="flex justify-between items-end size-h5">
                <div>DISK</div>
                <div class="color-highlight text-very-compact">{{ $rootUsedPercent }} <span class="color-base">%</span></div>
              </div>
              <div data-popover-type="html">
                {{- if $hasStats }}
                <div data-popover-html>
                  <ul class="list list-gap-2">
                    <li class="flex">
                      <div class="size-h5">/</div>
                      <div class="value-separator"></div>
                      <div class="color-highlight text-very-compact">
                        {{ template "formatGigabytes" $rootUsedGb }} <span class="color-base size-h5">/</span> {{ template "formatGigabytes" $rootTotalGb }}
                      </div>
                    </li>
                      {{ range $key, $efs := ($systemStats.Get "stats.efs").Map }}
                        <li class="flex">
                          <div class="size-h5">{{ $key }}</div>
                          <div class="value-separator"></div>
                          <div class="color-highlight text-very-compact">
                            {{ template "formatGigabytes" (($efs.Get "du").Float) }} <span class="color-base size-h5">/</span> {{ template "formatGigabytes" (($efs.Get "d").Float) }}
                          </div>
                        </li>
                      {{ end }}
                  </ul>
                </div>
                {{- end }}
                <div class="progress-bar progress-bar-combined">
                  <div class="progress-value{{ if ge $rootUsedPercent 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $rootUsedPercent }}"></div>
                  {{ range $key, $efs := ($system.Get "info.efs").Map }}
                    {{ $percent := $efs.Float }}
                    <div class="progress-value{{ if ge $percent 85.0 }} progress-value-notice{{ end }}" style="--percent: {{ $percent }}"></div>
                  {{ end }}
                </div>
              </div>
            </div>

          </div>
        </div>
      {{ end }}
    {{ end }}

