      <!-- Overall Status -->
      <div class="flex items-center gap-15 margin-bottom-20">
        <svg class="monitor-site-icon flat-icon" alt="GitHub Logo" role="img" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path fill="currentColor" d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v 3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"/></svg>
        <div class="grow min-width-0">
          <a class="size-h3 color-highlight text-truncate block" href="https://www.githubstatus.com/" target="_blank" rel="noreferrer" title="GitHub Status">GitHub</a>
          <ul class="list-horizontal-text">
            {{ $indicator := .JSON.String "status.indicator" }}
            {{ if eq $indicator "none" }}
              <li class="color-positive">All Systems Operational</li>
            {{ else if eq $indicator "minor" }}
              <li class="color-highlight">Minor Issues</li>
            {{ else if eq $indicator "major" }}
              <li class="color-negative">Major Outage</li>
            {{ else if eq $indicator "critical" }}
              <li class="color-negative">Critical Issues</li>
            {{ else }}
              <li>{{ .JSON.String "status.description" }}</li>
            {{ end }}
          </ul>
        </div>
      </div>

      <!-- Component Statuses -->
      <ul class="list list-gap-8">
        {{ range .JSON.Array "components" }}
          {{ if ne (.String "description") "" }}
            <li class="flex items-center gap-10" style="margin: 0.5rem 0;">
              <div style="width: 0.5rem; height: 0.5rem; border-radius: 50%; margin-right: 0.5rem; {{ if eq (.String "status") "operational" }}background-color: var(--color-positive){{ else if eq (.String "status") "degraded_performance" }}background-color: var(--color-highlight){{ else if eq (.String "status") "partial_outage" }}background-color: var(--color-negative){{ else if eq (.String "status") "major_outage" }}background-color: var(--color-negative); opacity: 0.7;{{ end }}"></div>
              <span class="size-h6">{{ .String "name" }}</span>
              <span class="size-text-13 color-subdue" style="margin-left: auto;">
                {{ if eq (.String "status") "operational" }}
                  OK
                {{ else if eq (.String "status") "degraded_performance" }}
                  Degraded
                {{ else if eq (.String "status") "partial_outage" }}
                  Partial Outage
                {{ else if eq (.String "status") "major_outage" }}
                  Major Outage
                {{ end }}
              </span>
            </li>
          {{ end }}
        {{ end }}
      </ul>
    </div>

- type: custom-api
  title: System Monitor
  cache: 15m
  url: ${GLANCES_URL}/api/4/system
  options:
  base_url:    ${GLANCES_URL}
  net_iface:   "<you network>"
  disk_mounts: "^(/youdisk1|/youdisk2)$"  
  template: |
  {{ $base     := .Options.StringOr "base_url"  "http://localhost:61208" }}
  {{ $netIface := .Options.StringOr "net_iface" "enp5s0" }}

  {{ $cpu    := newRequest (printf "%s/api/4/cpu"     $base) | getResponse }}
  {{ $mem    := newRequest (printf "%s/api/4/mem"     $base) | getResponse }}
  {{ $swap   := newRequest (printf "%s/api/4/memswap" $base) | getResponse }}
  {{ $load   := newRequest (printf "%s/api/4/load"    $base) | getResponse }}
  {{ $fs     := newRequest (printf "%s/api/4/fs"      $base) | getResponse }}
  {{ $net    := newRequest (printf "%s/api/4/network" $base) | getResponse }}
  {{ $diskio := newRequest (printf "%s/api/4/diskio"  $base) | getResponse }}
  {{ $uptime := newRequest (printf "%s/api/4/uptime"  $base) | getResponse }}

  {{/* CPU Calculations */}}
  {{ $cpuPct    := $cpu.JSON.Float "total" }}
  {{ $cores     := $load.JSON.Int  "cpucore" }}
  {{ $load1     := $load.JSON.Float "min1" }}
  {{ $load15    := $load.JSON.Float "min15" }}

  {{ $load1pct  := 0 }}
  {{ $load15pct := 0 }}
  {{ if gt $cores 0 }}
      {{ $load1pct = div (mul $load1 100) $cores }}
      {{ $load15pct = div (mul $load15 100) $cores }}
  {{ end }}

  {{ $memPct    := $mem.JSON.Float  "percent" }}
  {{ $memUsedGB := div ($mem.JSON.Int  "used")  1073741824 }}
  {{ $memTotGB  := div ($mem.JSON.Int  "total") 1073741824 }}

  {{ $swapPct   := $swap.JSON.Float "percent" }}
  {{ $swapUsedMB := div ($swap.JSON.Int "used")  1048576 }}
  {{ $swapTotGB  := div ($swap.JSON.Int "total") 1073741824 }}

  {{/* Network Calculations */}}
  {{ $netRx := 0 }}
  {{ $netTx := 0 }}
  {{ range $net.JSON.Array "" }}
      {{ if eq (.String "interface_name") $netIface }}
      {{ $netRx = .Int "bytes_recv_rate_per_sec" }}
      {{ $netTx = .Int "bytes_sent_rate_per_sec" }}
      {{ end }}
  {{ end }}

  {{ $rxKB := div $netRx 1024 }}
  {{ $txKB := div $netTx 1024 }}
  {{ $rxMB := div $rxKB 1024 }}
  {{ $txMB := div $txKB 1024 }}

      <style>
      /* Вертикальные бары */
      .v-bars-row {
      display: flex;
      justify-content: space-around;
      align-items: flex-end;
      height: 50px;
      gap: 4px;
      }
      .v-bar-col {
      display: flex;
      flex-direction: column;
      align-items: center;
      width: 12%;
      height: 100%;
      justify-content: flex-end;
      }
      .v-bar-track {
      width: 2rem;
      height: 100%;
      background-color: var(--color-bg-alt);
      border-radius: 3px;
      position: relative;
      overflow: hidden;
      }
      .v-bar-fill {
      position: absolute;
      bottom: 0;
      left: 0;
      width: 100%;
      background-color: var(--color-progress-value);
      border-radius: 0 var(--half-border-radius) var(--half-border-radius) 0;
      }
      .v-bar-label {
      font-size: 9px;
      margin-top: 4px;
      color: var(--color-text-dim);
      text-align: center;
      }


      .stat-item {
      display: flex;
      flex-direction: row;
      align-items: flex-end;
      gap: 5px;
      }
      .stat-label {
      display: flex;
      flex-direction: column;
      height: 100%;
      justify-content: space-between;
      }

      .v-bar-track{
      border: 1px solid var(--color-progress-border);
      }
      </style>

      {{/* Stats Row 1: CPU, RAM, NET */}}

      <div class="server-stats" style="display: flex; flex-wrap: wrap; gap: 8px; justify-content: flex-start; align-items: flex-start; ">

          {{/* CPU */}}
          <div style="display:flex; align-items: flex-start; flex-direction: row;">
          <div class="size-h5" style="writing-mode: vertical-lr; cursor:default;">CPU</div>
          <div style="display:flex; align-items: flex-end; gap:3px; flex-direction: column;">
              <div class="v-bars-row">
              <div class="v-bar-col">
                  <div class="v-bar-track">
                  <div class="v-bar-fill" style="height:{{ printf "%.0f" $cpuPct }}%"></div>
                  </div>
              </div>
              </div>
              <div class="size-h5 color-highlight" style="flex-shrink:0; text-align:center;">{{ printf "%.0f" $cpuPct }}%</div>
          </div>
          </div>

          {{/* RAM */}}
          <div style="display:flex; align-items: flex-start; flex-direction: row;">
          <div class="size-h5" style="writing-mode: vertical-lr; cursor:default;">RAM</div>
          <div style="display:flex; align-items: flex-end; gap:3px; flex-direction: column;">
              <div class="v-bars-row">
              <div class="v-bar-col">
                  <div class="v-bar-track">
                  <div class="v-bar-fill" style="height:{{ printf "%.0f" $memPct }}%"></div>
                  </div>
              </div>
              </div>
              <div class="size-h5 color-highlight" style="flex-shrink:0; text-align:center;">{{ printf "%.0f" $memPct }}%</div>
          </div>
          </div>

          {{/* NETWORK */}}
          {{ $rxPct := div $netRx 1048576 }}{{ if gt $rxPct 100 }}{{ $rxPct = 100 }}{{ end }}
          {{ $txPct := div $netTx 1048576 }}{{ if gt $txPct 100 }}{{ $txPct = 100 }}{{ end }}
          <div style="display:flex; align-items: flex-start; flex-direction: row;">
          <div class="size-h5" style="writing-mode: vertical-lr; cursor:default;">NETWORK</div>
          <div style="display:flex; align-items:flex-end; gap:3px; flex-direction:column;">
          <div style="display:flex; gap:4px;">

              {{/* ↓ RX */}}
              <div style="display:flex; flex-direction:column; align-items:center;">
              <div class="v-bar-track" style="width:100%; height:50px;">
                  <div class="v-bar-fill" style="height:{{ $rxPct }}%"></div>
              </div>
              <div class="size-h5 color-highlight" style="white-space:nowrap;">
                  ↓{{ if gt $rxMB 0 }}{{ $rxMB }}MB{{ else if gt $rxKB 0 }}{{ $rxKB }}KB{{ else }}{{ $netRx }}B{{ end }}
              </div>
              </div>

              {{/* ↑ TX */}}
              <div style="display:flex; flex-direction:column; align-items:center;">
              <div class="v-bar-track" style="width:100%; height:50px;">
                  <div class="v-bar-fill" style="height:{{ $txPct }}%"></div>
              </div>
              <div class="size-h5 color-highlight" style="white-space:nowrap;">
                  ↑{{ if gt $txMB 0 }}{{ $txMB }}MB{{ else if gt $txKB 0 }}{{ $txKB }}KB{{ else }}{{ $netTx }}B{{ end }}
              </div>
              </div>
          </div>
          </div>
      </div>


      {{/* ───── Диски ───── */}}
      {{ $diskPattern := .Options.StringOr "disk_mounts" "^/rootfs$" }}

      {{ range $fs.JSON.Array "" }}
      {{ $mnt := .String "mnt_point" }}
      {{ if findMatch $diskPattern $mnt }}

      {{ $pct     := .Float "percent" }}
      {{ $usedGB  := div (.Int "used")  1073741824 }}
      {{ $sizeGB  := div (.Int "size")  1073741824 }}
      {{ $devName := .String "device_name" }}

      {{ $readBytes  := 0 }}
      {{ $writeBytes := 0 }}
      {{ range $diskio.JSON.Array "" }}
      {{ $dname := .String "disk_name" }}
      {{ if findMatch (printf "/dev/%s" $dname) $devName }}
          {{ $readBytes  = .Int "read_bytes_rate_per_sec" }}
          {{ $writeBytes = .Int "write_bytes_rate_per_sec" }}
      {{ end }}
      {{ end }}

      {{ $readMB  := div $readBytes  1048576 }}
      {{ $writeMB := div $writeBytes 1048576 }}
      {{ $readKB  := div $readBytes  1024 }}
      {{ $writeKB := div $writeBytes 1024 }}

      <div data-popover-type="html" data-popover-max-width="180px" style="display:flex; align-items: flex-start; flex-direction: row;">

      {{/* Название */}}
      <div class="size-h5" style="writing-mode: vertical-lr; cursor:default;">{{ $mnt }}</div>

      <div style="display:flex; align-items: flex-end; gap:3px; flex-direction: column;">
          <div data-popover-html="">
          <div class="size-h5 color-highlight">{{ $mnt }}</div>
          <div class="flex margin-top-3">
              <div class="size-h5">Used</div>
              <div class="value-separator"></div>
              <div class="color-highlight">{{ $usedGB }} / {{ $sizeGB }} GB</div>
          </div>
          <div class="flex margin-top-3">
              <div class="size-h5">Read</div>
              <div class="value-separator"></div>
              <div class="color-highlight">{{ if gt $readMB 0 }}{{ $readMB }}MB/s{{ else if gt $readKB 0 }}{{ $readKB }}KB/s{{ else }}—{{ end }}</div>
          </div>
          <div class="flex margin-top-3">
              <div class="size-h5">Write</div>
              <div class="value-separator"></div>
              <div class="color-highlight">{{ if gt $writeMB 0 }}{{ $writeMB }}MB/s{{ else if gt $writeKB 0 }}{{ $writeKB }}KB/s{{ else }}—{{ end }}</div>
          </div>
          </div>


          <div class="v-bars-row">
          <div class="v-bar-col">
              <div class="v-bar-track">
              <div class="v-bar-fill" style="height:{{ printf "%.0f" $pct }}%"></div>
              </div>
          </div>
          </div>


          {{/* Процент */}}
          <div class="size-h5 color-highlight" style="flex-shrink:0; text-align: center;">{{ printf "%.0f" $pct }}%</div>
      </div>
      </div>

  {{ end }}
  {{ end }}

  </div>

- type: custom-api
  cache: 30s
  title: SERVER STATS
  options:
    glances-url: "http://${GLANCES_URL}:61208"
    server-name: "Server Name Here"
    show-temperature: "true"
    show-disk-bar: "true"
    show-network: "false"
    network-interface: "eth0"
  template: |
    {{ $glancesUrl := .Options.StringOr "glances-url" "http://127.0.0.1:61208" }}
    {{ $baseUrl := concat $glancesUrl "/api/4" }}
    {{ $serverName := .Options.StringOr "server-name" "Server" }}
    {{ $showTemp := eq (.Options.StringOr "show-temperature" "true") "true" }}
    {{ $showDiskBar := eq (.Options.StringOr "show-disk-bar" "true") "true" }}
    {{ $showNetwork := eq (.Options.StringOr "show-network" "false") "true" }}
    {{ $ifName := .Options.StringOr "network-interface" "eth0" }}

    {{ $cpu := newRequest (concat $baseUrl "/cpu") | getResponse }}
    {{ $mem := newRequest (concat $baseUrl "/mem") | getResponse }}
    {{ $fs := newRequest (concat $baseUrl "/fs") | getResponse }}
    {{ $uptime := newRequest (concat $baseUrl "/uptime") | getResponse }}
    {{ $swap := newRequest (concat $baseUrl "/memswap") | getResponse }}
    {{ $net := newRequest (concat $baseUrl "/network") | getResponse }}
    {{ $sensors := newRequest (concat $baseUrl "/sensors") | getResponse }}

    {{ $isOnline := and (eq $cpu.Response.StatusCode 200) (eq $mem.Response.StatusCode 200) }}

    {{ if $isOnline }}
      {{ $cpuPercent := $cpu.JSON.Float "total" | toInt }}
      {{ $memPercent := $mem.JSON.Float "percent" | toInt }}
      {{ $memUsedGB := div ($mem.JSON.Float "used") 1073741824 }}
      {{ $memTotalGB := div ($mem.JSON.Float "total") 1073741824 }}

      {{ $swapUsedMB := 0 }}
      {{ $swapTotalMB := 0 }}
      {{ if eq $swap.Response.StatusCode 200 }}
        {{ $swapUsedMB = div ($swap.JSON.Float "used") 1048576 | toInt }}
        {{ $swapTotalMB = div ($swap.JSON.Float "total") 1048576 | toInt }}
      {{ end }}

      {{ $uptimeStr := "" }}
      {{ if eq $uptime.Response.StatusCode 200 }}
        {{ $uptimeStr = $uptime.JSON.String "" }}
      {{ end }}

      {{ $temperature := 0 }}
      {{ if and $showTemp (eq $sensors.Response.StatusCode 200) }}
        {{ range $sensors.JSON.Array "" }}
          {{ $type := .String "type" }}
          {{ $unit := .String "unit" }}
          {{ $valueInt := .Float "value" | toInt }}
          {{ if and (eq $type "temperature_core") (eq $unit "C") (gt $valueInt 0) }}
            {{ if gt $valueInt 200 }}
              {{ $temperature = div $valueInt 1000 }}
            {{ else }}
              {{ $temperature = $valueInt }}
            {{ end }}
          {{ end }}
        {{ end }}
      {{ end }}

      {{ $netDownMBs := 0.0 }}
      {{ $netUpMBs := 0.0 }}
      {{ if and $showNetwork (eq $net.Response.StatusCode 200) }}
        {{ range $net.JSON.Array "" }}
          {{ if eq (.String "interface_name") $ifName }}
            {{ $netDownMBs = div (.Float "bytes_recv_rate_per_sec") 1048576 }}
            {{ $netUpMBs = div (.Float "bytes_sent_rate_per_sec") 1048576 }}
          {{ end }}
        {{ end }}
      {{ end }}

      <style>
        .server-container { padding: 0.5rem; }
        .server-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 1rem;
          padding-bottom: 0.75rem;
          border-bottom: 1px solid var(--color-separator);
        }
        .server-name-link {
          color: var(--color-text-subdue);
          text-decoration: none;
          transition: color 0.2s;
        }
        .server-name-link:hover { color: var(--color-primary); }
        .services-section {
          margin-bottom: 1rem;
          display: flex;
          align-items: center;
          gap: 0.5rem;
        }
        .status-indicator {
          display: flex;
          align-items: center;
          justify-content: center;
          width: 1.5rem;
          height: 1.5rem;
          border-radius: 50%;
          background: #22c55e;
          flex-shrink: 0;
        }
        .status-indicator.offline { background: #ef4444; }
        .status-icon { width: 1rem; height: 1rem; color: white; }
        .services-info { flex: 1; }
        .uptime-temp-row {
          display: flex;
          align-items: center;
          gap: 0.5rem;
          justify-content: space-between;
        }
        .temp-display {
          padding: 0.25rem 0.6rem;
          border-radius: 4px;
          white-space: nowrap;
        }
        .temp-low { background: rgba(34, 197, 94, 0.15); color: #22c55e; }
        .temp-medium { background: rgba(234, 179, 8, 0.15); color: #eab308; }
        .temp-high { background: rgba(239, 68, 68, 0.15); color: #ef4444; }
        .metrics-grid {
          display: grid;
          grid-template-columns: repeat(3, 1fr);
          gap: 0.75rem;
          margin-bottom: 1rem;
        }
        .metric-card {
          background: var(--color-widget-background);
          border: 1px solid var(--color-separator);
          border-radius: var(--border-radius-primary);
          padding: 0.75rem;
          text-align: center;
        }
        .metric-bar {
          width: 100%;
          height: 4px;
          background: var(--color-separator);
          border-radius: 2px;
          overflow: hidden;
          margin-top: 0.5rem;
          position: relative;
        }
        .metric-bar-fill {
          height: 100%;
          position: absolute;
          left: 0;
          top: 0;
          transition: width 0.3s ease;
        }
        .bar-low { background: linear-gradient(90deg, #22c55e 0%, #16a34a 100%); }
        .bar-medium { background: linear-gradient(90deg, #eab308 0%, #ca8a04 100%); }
        .bar-high { background: linear-gradient(90deg, #ef4444 0%, #dc2626 100%); }
        .memory-section {
          background: var(--color-widget-background);
          border: 1px solid var(--color-separator);
          border-radius: var(--border-radius-primary);
          padding: 0.75rem;
          margin-bottom: 1rem;
        }
        .memory-row {
          display: flex;
          justify-content: space-between;
          align-items: center;
          padding: 0.4rem 0;
        }
        .disks-section {
          background: var(--color-widget-background);
          border: 1px solid var(--color-separator);
          border-radius: var(--border-radius-primary);
          padding: 0.75rem;
          margin-bottom: 1rem;
        }
        .disk-item { margin-bottom: 0.75rem; }
        .disk-item:last-child { margin-bottom: 0; }
        .disk-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 0.35rem;
        }
        .network-section {
          display: grid;
          grid-template-columns: 1fr 1fr;
          gap: 0.75rem;
        }
        .network-card {
          background: var(--color-widget-background);
          border: 1px solid var(--color-separator);
          border-radius: var(--border-radius-primary);
          padding: 0.75rem;
          text-align: center;
        }
        .icon-server { width: 1.5rem; height: 1.5rem; }
      </style>

      <div class="server-container">
        <div class="server-header">
          {{ if ne $glancesUrl "" }}
          <a href="{{ $glancesUrl }}" target="_blank" class="server-name-link">
            <span class="size-h6 color-text-subdue" style="font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">{{ $serverName }}</span>
          </a>
          {{ else }}
          <span class="size-h6 color-text-subdue" style="font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">{{ $serverName }}</span>
          {{ end }}
          <svg class="icon-server" viewBox="0 0 24 24" fill="currentColor">
            <path d="M4,1H20A1,1 0 0,1 21,2V6A1,1 0 0,1 20,7H4A1,1 0 0,1 3,6V2A1,1 0 0,1 4,1M4,9H20A1,1 0 0,1 21,10V14A1,1 0 0,1 20,15H4A1,1 0 0,1 3,14V10A1,1 0 0,1 4,9M4,17H20A1,1 0 0,1 21,18V22A1,1 0 0,1 20,23H4A1,1 0 0,1 3,22V18A1,1 0 0,1 4,17M5,4V5H7V4H5M5,12V13H7V12H5M5,20V21H7V20H5M9,4V5H11V4H9M9,12V13H11V12H9M9,20V21H11V20H9Z"/>
          </svg>
        </div>

        <div class="services-section">
          <div class="status-indicator">
            <svg class="status-icon" viewBox="0 0 24 24" fill="currentColor">
              <path d="M21,7L9,19L3.5,13.5L4.91,12.09L9,16.17L19.59,5.59L21,7Z"/>
            </svg>
          </div>
          <div class="services-info">
            <div class="size-h5" style="margin-bottom: 0.15rem;">Services</div>
            <div class="uptime-temp-row">
              {{ if ne $uptimeStr "" }}
              <span class="size-h6 color-text-subdue">{{ $uptimeStr }} uptime</span>
              {{ end }}
              {{ if and $showTemp (gt $temperature 0) }}
              <span class="size-h6 temp-display {{ if lt $temperature 65 }}temp-low{{ else if lt $temperature 80 }}temp-medium{{ else }}temp-high{{ end }}">{{ $temperature }}°C</span>
              {{ end }}
            </div>
          </div>
        </div>

        <div class="metrics-grid">
          <div class="metric-card">
            <div class="size-h6 color-text-subdue" style="text-transform: uppercase; margin-bottom: 0.5rem;">CPU</div>
            <div class="size-h2" style="font-weight: 700; margin-bottom: 0.25rem;">{{ $cpuPercent }}%</div>
            <div class="metric-bar">
              <div class="metric-bar-fill {{ if lt $cpuPercent 60 }}bar-low{{ else if lt $cpuPercent 80 }}bar-medium{{ else }}bar-high{{ end }}" style="width: {{ $cpuPercent }}%"></div>
            </div>
          </div>

          <div class="metric-card">
            <div class="size-h6 color-text-subdue" style="text-transform: uppercase; margin-bottom: 0.5rem;">RAM</div>
            <div class="size-h2" style="font-weight: 700; margin-bottom: 0.25rem;">{{ $memPercent }}%</div>
            <div class="metric-bar">
              <div class="metric-bar-fill {{ if lt $memPercent 60 }}bar-low{{ else if lt $memPercent 80 }}bar-medium{{ else }}bar-high{{ end }}" style="width: {{ $memPercent }}%"></div>
            </div>
          </div>

          <div class="metric-card">
            <div class="size-h6 color-text-subdue" style="text-transform: uppercase; margin-bottom: 0.5rem;">DISK</div>
            <div class="size-h2" style="font-weight: 700; margin-bottom: 0.25rem;">
              {{ $totalDiskPercent := 0 }}
              {{ $diskCount := 0 }}
              {{ range $fs.JSON.Array "" }}
                {{ $totalDiskPercent = add $totalDiskPercent (.Float "percent" | toInt) }}
                {{ $diskCount = add $diskCount 1 }}
              {{ end }}
              {{ if gt $diskCount 0 }}{{ div $totalDiskPercent $diskCount }}%{{ else }}0%{{ end }}
            </div>
            {{ if $showDiskBar }}
            <div class="metric-bar">
              {{ $avgPercent := 0 }}
              {{ $diskCount := 0 }}
              {{ range $fs.JSON.Array "" }}
                {{ $avgPercent = add $avgPercent (.Float "percent" | toInt) }}
                {{ $diskCount = add $diskCount 1 }}
              {{ end }}
              {{ if gt $diskCount 0 }}{{ $avgPercent = div $avgPercent $diskCount }}{{ end }}
              <div class="metric-bar-fill {{ if lt $avgPercent 60 }}bar-low{{ else if lt $avgPercent 80 }}bar-medium{{ else }}bar-high{{ end }}" style="width: {{ $avgPercent }}%"></div>
            </div>
            {{ end }}
          </div>
        </div>

        <div class="memory-section">
          <div class="memory-row">
            <span class="size-h6 color-text-subdue" style="text-transform: uppercase;">RAM</span>
            <span class="size-h6" style="font-weight: 500;">{{ $memUsedGB | printf "%.1f" }} GB / {{ $memTotalGB | printf "%.1f" }} GB</span>
          </div>
          {{ if gt $swapTotalMB 0 }}
          <div class="memory-row">
            <span class="size-h6 color-text-subdue" style="text-transform: uppercase;">SWAP</span>
            <span class="size-h6" style="font-weight: 500;">{{ $swapUsedMB }} MB / {{ $swapTotalMB }} MB</span>
          </div>
          {{ end }}
        </div>

        {{ if eq $fs.Response.StatusCode 200 }}
        <div class="disks-section">
          {{ $device1 := "" }}
          {{ $device2 := "" }}
          {{ $device3 := "" }}
          {{ $device4 := "" }}
          {{ $device5 := "" }}
          {{ range $fs.JSON.Array "" }}
            {{ $deviceName := .String "device_name" }}
            {{ $isNewDevice := true }}
            {{ if or (eq $deviceName $device1) (eq $deviceName $device2) (eq $deviceName $device3) (eq $deviceName $device4) (eq $deviceName $device5) }}
              {{ $isNewDevice = false }}
            {{ end }}
            {{ if and $isNewDevice (ne $deviceName "") }}
              {{ if eq $device1 "" }}
                {{ $device1 = $deviceName }}
              {{ else if eq $device2 "" }}
                {{ $device2 = $deviceName }}
              {{ else if eq $device3 "" }}
                {{ $device3 = $deviceName }}
              {{ else if eq $device4 "" }}
                {{ $device4 = $deviceName }}
              {{ else if eq $device5 "" }}
                {{ $device5 = $deviceName }}
              {{ end }}
              {{ $diskPercent := .Float "percent" | toInt }}
              {{ $diskUsedGB := div (.Float "used") 1073741824 }}
              {{ $diskTotalGB := div (.Float "size") 1073741824 }}
              {{ $diskTotalGBInt := $diskTotalGB | toInt }}
              <div class="disk-item">
                <div class="disk-header">
                  <span class="size-h6 color-text-subdue" style="text-transform: uppercase;">{{ $deviceName }}</span>
                  {{ if gt $diskTotalGBInt 1000 }}
                  <span class="size-h6" style="font-weight: 500;">{{ div $diskUsedGB 1024 | printf "%.1f" }} TB / {{ div $diskTotalGB 1024 | printf "%.1f" }} TB</span>
                  {{ else }}
                  <span class="size-h6" style="font-weight: 500;">{{ $diskUsedGB | printf "%.1f" }} GB / {{ $diskTotalGB | printf "%.1f" }} GB</span>
                  {{ end }}
                </div>
                {{ if $showDiskBar }}
                <div class="metric-bar">
                  <div class="metric-bar-fill {{ if lt $diskPercent 60 }}bar-low{{ else if lt $diskPercent 80 }}bar-medium{{ else }}bar-high{{ end }}" style="width: {{ $diskPercent }}%"></div>
                </div>
                {{ end }}
              </div>
            {{ end }}
          {{ end }}
        </div>
        {{ end }}

        {{ if $showNetwork }}
        <div class="network-section">
          <div class="network-card">
            <div class="size-h6 color-text-subdue" style="text-transform: uppercase; margin-bottom: 0.5rem;">↓ Download</div>
            <div class="size-h4 color-highlight" style="font-weight: 700;">{{ $netDownMBs | printf "%.2f" }} MB/s</div>
          </div>
          <div class="network-card">
            <div class="size-h6 color-text-subdue" style="text-transform: uppercase; margin-bottom: 0.5rem;">↑ Upload</div>
            <div class="size-h4 color-highlight" style="font-weight: 700;">{{ $netUpMBs | printf "%.2f" }} MB/s</div>
          </div>
        </div>
        {{ end }}
      </div>
    {{ else }}
      <div class="server-container">
        <div class="server-header">
          <span class="size-h6 color-text-subdue" style="font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">{{ $serverName }}</span>
          <svg class="icon-server" viewBox="0 0 24 24" fill="currentColor">
            <path d="M4,1H20A1,1 0 0,1 21,2V6A1,1 0 0,1 20,7H4A1,1 0 0,1 3,6V2A1,1 0 0,1 4,1M4,9H20A1,1 0 0,1 21,10V14A1,1 0 0,1 20,15H4A1,1 0 0,1 3,14V10A1,1 0 0,1 4,9M4,17H20A1,1 0 0,1 21,18V22A1,1 0 0,1 20,23H4A1,1 0 0,1 3,22V18A1,1 0 0,1 4,17M5,4V5H7V4H5M5,12V13H7V12H5M5,20V21H7V20H5M9,4V5H11V4H9M9,12V13H11V12H9M9,20V21H11V20H9Z"/>
          </svg>
        </div>
        <div class="services-section">
          <div class="status-indicator offline">
            <svg class="status-icon" viewBox="0 0 24 24" fill="currentColor">
              <path d="M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z"/>
            </svg>
          </div>
          <div class="services-info">
            <div class="size-h5" style="margin-bottom: 0.15rem;">Services</div>
            <div class="size-h6 color-negative">Offline</div>
          </div>
        </div>
        <p class="color-negative" style="text-align: center; margin-top: 1rem;">Failed to fetch server data</p>
      </div>
    {{ end }}

- type: custom-api
  title: Gluetun status
  cache: 1m
  url: http://${GLUETUN_URL}/v1/publicip/ip
  headers:
    X-API-Key: ${GLUETUN_API_KEY}
  template: |
    {{ if eq .Response.StatusCode 200 }}
      {{ $ip := (.JSON.String "public_ip") }}
      {{ $city := (.JSON.String "city") }}
      {{ $country := (.JSON.String "country") }}
      {{ if eq $ip "" }}
        {{ $ip = "-" }}
        {{ $city = "-" }}
        {{ $country = "-" }}
      {{ end }}
      <div class="flex justify-between text-center">
        <div>
            <div class="color-highlight size-h4">{{ $ip }}</div>
            <div class="size-h6">PUBLIC IP</div>
        </div>
        <div>
            <div class="color-highlight size-h4">{{ $country }}</div>
            <div class="size-h6">COUNTRY</div>
        </div>
        <div>
            <div class="color-highlight size-h4">{{ $city }}</div>
            <div class="size-h6">CITY</div>
        </div>
      </div>
    {{ else }}
      <div style="text-align: center; color: var(--color-negative);">
        Error: {{ .Response.StatusCode }} - {{ .Response.Status }}
      </div>
    {{ end }}

- type: custom-api
  title: Upcoming Google Calendar Events
  cache: 15m
  template: |
    {{
      $token := newRequest "https://oauth2.googleapis.com/token"
        | withHeader "Content-Type" "application/x-www-form-urlencoded"
        | withStringBody "client_id=${GOOGLE_CLIENT_ID}&client_secret=${GOOGLE_CLIENT_SECRET}&refresh_token=${GOOGLE_REFRESH_TOKEN}&grant_type=refresh_token"
        | getResponse
    }}

    {{ if ne $token.Response.StatusCode 200 }}
      <p>Failed to get token: {{ $token.Response.Status }}</p>
    {{ else }}
      {{ $accessToken := $token.JSON.String "access_token" }}
      {{ $nowtime := now | formatTime "rfc3339" }}
      {{ $future := offsetNow "720h" | formatTime "rfc3339" }}
      {{
        $events := newRequest "https://www.googleapis.com/calendar/v3/calendars/primary/events"
          | withParameter "timeMin" $nowtime
          | withParameter "timeMax" $future
          | withParameter "singleEvents" "true"
          | withParameter "orderBy" "startTime"
          | withHeader "Authorization" (print "Bearer " $accessToken)
          | getResponse
      }}

      {{ if ne $events.Response.StatusCode 200 }}
        <p>Failed to fetch events: {{ $events.Response.Status }}</p>
      {{ else }}
        <div>
          {{ range $events.JSON.Array "items" }}
          {{ $start := .String "start.dateTime" }}
          {{ $end := .String "end.dateTime" }}
          {{ $isAllDay := eq $start "" }}
          {{ if $isAllDay }}
            {{ $start = print (.String "start.date") | parseLocalTime "DateOnly" }}
            {{ $end = print (.String "end.date") | parseLocalTime "DateOnly" }}
          {{ else }}
            {{ $start = $start | parseTime "rfc3339" }}
            {{ $end = $end | parseTime "rfc3339" }}            
          {{ end }}
          {{ $startDateOnly := $start | formatTime "DateOnly" }}
          {{ $endDateOnly := $end | formatTime "DateOnly" }}
          {{ $isStartAndEndDateSame := eq $startDateOnly $endDateOnly }}

          <div style="display: flex; flex-wrap: wrap; justify-content: space-between; align-items: flex-start;">
            <a href="https://calendar.google.com/calendar/u/0" target="_blank" class="size-h1" style="text-align: left; width: 215px;">
              {{ .String "summary" }}
            </a>
            <a href="https://calendar.google.com/calendar/u/0" target="_blank" class="size-h3" style="text-align: left;">
              {{ $start | formatTime "Mon, Jan 2 · 3:04 PM" }} 
              {{ if $isStartAndEndDateSame }}
                  - {{ $end | formatTime "3:04 PM" }}
                {{ else }}
                  - {{ $end | formatTime "Mon, Jan 2 · 3:04 PM" }}
              {{ end }}
            </a>
            <div class="color-primary size-h3" style="text-align: right; width: 75px;" {{ $start | toRelativeTime }}>
            </div>
          </div>
        {{ end }}
        </div>
      {{ end }}
    {{ end }}

- type: custom-api
  title: Notifications
  title-url: ${SERVER_ADDRESS}      # example - http://192.168.1.1:8070
  cache: 1m
  url: ${SERVER_ADDRESS}/message
  parameters:
    limit: 10
    collapse-after: 5
  headers:
    X-Gotify-Key: ${GOTIFY_CLIENT_TOKEN}
  template: |
    {{ $messages := .JSON.Array "messages" }}
    {{ if eq (len $messages) 0 }}
      <p style="color: var(--color-text-subdue);">No notifications.</p>
    {{ else }}
      <ul class="list list-gap-14 collapsible-container" data-collapse-after="5">
        {{ range $messages }}
          {{ $priority := .Int "priority" }}
          {{ $date := .String "date" | parseTime "rfc3339" }}
          {{ $title := .String "title" }}
          {{ $message := .String "message" }}
          <li data-popover-type="text" data-popover-text="{{ $title }}: {{ $message }}">
            <div class="flex items-center gap-10" style="margin-bottom: 3px;">
              {{ if ge $priority 8 }}
                <span class="color-negative">●</span>
              {{ else if ge $priority 4 }}
                <span class="color-primary">●</span>
              {{ else }}
                <span style="color: var(--color-text-subdue);">●</span>
              {{ end }}
              <span class="color-highlight size-h4 grow" style="overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;">{{ $title }}</span>
              <span class="size-h6" style="color: var(--color-text-subdue); white-space: nowrap;">{{ $date.Format "Jan 2 15:04" }}</span>
            </div>
            <p class="size-h5" style="padding-left: 18px; white-space: pre-line; overflow: hidden; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2;">{{ $message }}</p>
          </li>
        {{ end }}
      </ul>
    {{ end }}

- type: custom-api
  title: Hardcover
  cache: 3h
  url: https://api.hardcover.app/v1/graphql
  headers:
    content-type: application/json
    authorization: ${HARDCOVER_API_KEY}
  body:
    query: |
      query MyQuery {
        me {
          user_books(where: {status_id: {_eq: 2}}, order_by: {first_read_date: desc}) {
            id
            user_book_reads(
              limit: 1,
              order_by: {started_at: desc_nulls_last}
            ) {
              id
              started_at
              progress
              edition {
                image {
                  url
                }
                cached_contributors
              }
            }
            book {
              title
              slug
            }
          }
        }
      }
  template: |
    <ul class="list list-gap-10 collapsible-container" data-collapse-after="5">
      {{ range .JSON.Array "data.me.0.user_books" }}
        <li class="flex items-center gap-10">
          <div style="border-radius: 5px; max-height: 10rem; max-width: 6rem; overflow: hidden;">
            <img src="{{ .String "user_book_reads.0.edition.image.url" }}" class="card" style="width: 100%; height: 100%; object-fit: cover; object-position: center;">
          </div>
          <div class="flex-1">
            <a class="size-h4 color-highlight" href="https://hardcover.app/books/{{ .String "book.slug" }}">{{ .String "book.title" }}</a>
            <ul class="list-horizontal-text size-h5">
              {{ range .Array "user_book_reads.0.edition.cached_contributors" }}
                {{ if not (.String "contribution") }}
                  <li>{{ .String "author.name" }}</li>
                {{ end }}
              {{ end }}
            </ul>
            <ul class="list-horizontal-text" >
              <li>{{ .String "user_book_reads.0.started_at" }}</li>
              <li>{{ .Int "user_book_reads.0.progress" }}%</li>
            </ul>
          </div>
        </li>
      {{ end }}
    </ul>

- type: custom-api
  title: Homeassistant Stats
  cache: 10m
  url: ${HASS_URL}/api/states
  headers:
    Authorization: "Bearer ${HASS_API_KEY}"
    Content-Type: "application/json"
  template: |
    {{ if eq .Response.StatusCode 200 }}
      <div style="display: grid; grid-template-columns: repeat(2, 1fr); gap: 8px;">
        {{ range .JSON.Array "" }}
          {{ $id := .String "entity_id" }}
          {{ $state := .String "state" }}
          {{ if and (or 
                        (eq $id "sensor.example1") 
                        (eq $id "sensor.example2")
                    )
                    (ne $state "unavailable")
                    (ne $state "unknown")
          }}
            <div class="background-faint radius-8" style="padding: 6px 10px; text-align: center;">
              <div class="color-highlight size-h3" style="line-height: 1.2;">
                {{ $state }}{{ .String "attributes.unit_of_measurement" }}
              </div>
              <div class="size-h6 color-subdue" style="line-height: 1.2;">
                {{ .String "attributes.friendly_name" }}
              </div>
            </div>
          {{ end }}
        {{ end }}
      </div>
    {{ else }}
      <div style="text-align: center;" class="color-negative size-h4">
        Error: {{ .Response.StatusCode }} – {{ .Response.Status }}
      </div>
    {{ end }}

- type: custom-api
  title: Immich Stats
  hide-header: true
  cache: 10m
  url: ${IMMICH_URL}/api/server/statistics
  headers:
    x-api-key: ${IMMICH_KEY}
  subrequests:
    storage:
      url: ${IMMICH_URL}/api/server/storage
      headers:
        x-api-key: ${IMMICH_KEY} 
  options:
    show-cards: true
    show-storage-bar: true
  template: |
    {{ $photos := .JSON.Int "photos" }}
    {{ $videos := .JSON.Int "videos" }}
    {{ $usageBytes := .JSON.Int "usage" }}
    {{ $usageGiB := div (toFloat $usageBytes) 1073741824.0 }}
    {{ $storage := .Subrequest "storage" }}
    {{ $storage_ok := and (ge $storage.Response.StatusCode 200) (le $storage.Response.StatusCode 299) }}
    {{ $totalGiB := 0.0 }}
    {{ $percentage := 0.0 }}
    {{ $storageError := "" }}
    {{ if $storage_ok }}
      {{ $totalGiB = div (toFloat ($storage.JSON.Int "diskSizeRaw")) 1073741824.0 }}
      {{ $percentage = $storage.JSON.Float "diskUsagePercentage" }}
    {{ else }}
      {{ $storageError = printf "%d %s" $storage.Response.StatusCode $storage.Response.Status }}
    {{ end }}
    {{ $showCards := .Options.BoolOr "show-cards" true }}
    {{ $showStorageBar := .Options.BoolOr "show-storage-bar" true }}

    {{ if $showCards }}
    <div style="display: flex; gap: 16px; flex-wrap: wrap;{{ if $showStorageBar }} margin-bottom: 16px;{{ end }}">
      <!-- Photos Card -->
      <div style="display: flex; flex-direction: column; justify-content: space-between; background-color: var(--color-widget-background-highlight); border-radius: 12px; padding: 20px; flex: 1; min-width: 200px;">
        <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 16px;">
          <svg style="width: 40px; height: 40px; color: var(--color-primary); flex-shrink: 0;" viewBox="0 0 24 24" fill="currentColor">
            <path d="M13.73,15L9.83,21.76C10.53,21.91 11.25,22 12,22C14.4,22 16.6,21.15 18.32,19.75L14.66,13.4M2.46,15C3.38,17.92 5.61,20.26 8.45,21.34L12.12,15M8.54,12L4.64,5.25C3,7 2,9.39 2,12C2,12.68 2.07,13.35 2.2,14H9.69M21.8,10H14.31L14.6,10.5L19.36,18.75C21,16.97 22,14.6 22,12C22,11.31 21.93,10.64 21.8,10M21.54,9C20.62,6.07 18.39,3.74 15.55,2.66L11.88,9M9.4,10.5L14.17,2.24C13.47,2.09 12.75,2 12,2C9.6,2 7.4,2.84 5.68,4.25L9.34,10.6L9.4,10.5Z"/>
          </svg>
          <span style="font-weight: 600; font-size: 1.8rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--color-text-highlight);">Photos</span>
        </div>
        <div style="font-family: ui-monospace, monospace; font-size: 1.85rem; font-weight: 700; color: var(--color-text-highlight); word-break: break-all;">
          {{ if lt $photos 10 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">000000000</span>{{ else if lt $photos 100 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">00000000</span>{{ else if lt $photos 1000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">0000000</span>{{ else if lt $photos 10000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">000000</span>{{ else if lt $photos 100000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">00000</span>{{ else if lt $photos 1000000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">0000</span>{{ end }}{{ $photos }}
        </div>
      </div>

      <!-- Videos Card -->
      <div style="display: flex; flex-direction: column; justify-content: space-between; background-color: var(--color-widget-background-highlight); border-radius: 12px; padding: 20px; flex: 1; min-width: 200px;">
        <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 16px;">
          <svg style="width: 40px; height: 40px; color: var(--color-primary); flex-shrink: 0;" viewBox="0 0 24 24" fill="currentColor">
            <path d="M10,16.5V7.5L16,12M12,2A10,10 0 0,0 2,12A10,10 0 0,0 12,22A10,10 0 0,0 22,12A10,10 0 0,0 12,2Z"/>
          </svg>
          <span style="font-weight: 600; font-size: 1.8rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--color-text-highlight);">Videos</span>
        </div>
        <div style="font-family: ui-monospace, monospace; font-size: 1.85rem; font-weight: 700; color: var(--color-text-highlight); word-break: break-all;">
          {{ if lt $videos 10 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">000000000</span>{{ else if lt $videos 100 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">00000000</span>{{ else if lt $videos 1000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">0000000</span>{{ else if lt $videos 10000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">000000</span>{{ else if lt $videos 100000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">00000</span>{{ else if lt $videos 1000000 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">0000</span>{{ end }}{{ $videos }}
        </div>
      </div>

      <!-- Storage GiB Card -->
      <div style="display: flex; flex-direction: column; justify-content: space-between; background-color: var(--color-widget-background-highlight); border-radius: 12px; padding: 20px; flex: 1; min-width: 200px;">
        <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 16px;">
          <svg style="width: 40px; height: 40px; color: var(--color-primary); flex-shrink: 0;" viewBox="0 0 24 24" fill="currentColor">
            <path d="M11,2V22C5.9,21.5 2,17.2 2,12C2,6.8 5.9,2.5 11,2M13,2V11H22C21.5,6.2 17.8,2.5 13,2M13,13V22C17.7,21.5 21.5,17.8 22,13H13Z"/>
          </svg>
          <span style="font-weight: 600; font-size: 1.8rem; text-transform: uppercase; letter-spacing: 0.5px; color: var(--color-text-highlight);">Storage</span>
        </div>
      <div style="font-family: ui-monospace, monospace; font-size: 1.85rem; font-weight: 700; color: var(--color-text-highlight); word-break: break-all;">
        {{ $gib := printf "%.0f" $usageGiB }}
        {{ if lt $usageGiB 10.0 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">000000000</span>{{ else if lt $usageGiB 100.0 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">00000000</span>{{ else if lt $usageGiB 1000.0 }}<span style="color: var(--color-text-subdue); font-weight: 400; opacity: 0.6;">0000000</span>{{ end }}{{ $gib }}<span style="font-size: 1.5rem; font-weight: 500; color: var(--color-text-subdue); margin-left: 8px;">GiB</span>
      </div>
      </div>
    </div>
    {{ end }}

    {{ if $showStorageBar }}
    <!-- Progress Bar Section -->
    <div style="background-color: var(--color-widget-background-highlight); border-radius: 12px; padding: 20px;">
      <div style="font-weight: 600; color: var(--color-text-highlight); margin-bottom: 8px; font-size: 1.6rem;">Storage space</div>
      {{ if gt $totalGiB 0.0 }}
        <div style="color: var(--color-text-highlight); font-size: 1.4rem; margin-bottom: 12px; font-weight: 500;">{{ printf "%.1f" $usageGiB }} GiB of {{ printf "%.1f" $totalGiB }} GiB used</div>
        <div style="color: var(--color-text-subdue); font-size: 1.35rem; margin-bottom: 12px;">{{ printf "%.1f" $percentage }}% full</div>
      {{ else }}
        <div style="color: var(--color-text-highlight); font-size: 1.4rem; margin-bottom: 12px; font-weight: 500;">{{ printf "%.1f" $usageGiB }} GiB used</div>
        <div style="color: var(--color-text-negative); font-size: 1.35rem; margin-bottom: 12px;">Total storage unavailable ({{ $storageError }}). Ensure API key has permissions for /api/server/storage.</div>
      {{ end }}
      <div style="height: 12px; width: 100%; background-color: var(--color-text-subdue); border-radius: 6px; overflow: hidden; opacity: 0.2;">
        <div style="height: 100%; background-color: var(--color-primary); border-radius: 6px; transition: width 0.3s ease; width: {{ if gt $totalGiB 0.0 }}{{ printf "%.1f" $percentage }}%{{ else }}0%{{ end }};"></div>
      </div>
    </div>
    {{ end }}

- type: custom-api
  title: Latest Shows
  frameless: true
  cache: 5m
  options:
    base-url: ${JELLYFIN_URL}
    api-key: ${JELLYFIN_KEY}
    user-name: "yourUserName"
    library-name: "Shows"
    mode: "latest"
    item-count: "10"
    small-column: false
    show-thumbnail: false
    thumbnail-aspect-ratio: "default"
  template: |
    {{/* Required config options */}}
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $userName := .Options.StringOr "user-name" "" }}

    {{/* Required config options for "latest" mode */}}
    {{ $libraryName := .Options.StringOr "library-name" "" }}

    {{/* Optional config options */}}
    {{ $mode := .Options.StringOr "mode" "latest" }}
    {{ $itemCount := .Options.StringOr "item-count" "10" }}
    {{ $mediaTypes := .Options.StringOr "media-types" "Movie,Episode,MusicAlbum" }}
    {{ $thumbAspectRatio := .Options.StringOr "thumbnail-aspect-ratio" "" }}
    {{ $isSmallColumn:= .Options.BoolOr "small-column" false }}
    {{ $showThumbnail := .Options.BoolOr "show-thumbnail" false }}
    {{ $showProgressBar := .Options.BoolOr "progress-bar" true }}

    {{/* Error message template */}}
    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{/* Check required fields */}}
    {{ if or (eq $baseURL "") (eq $apiKey "") (eq $userName "") (eq $mode "") (and (eq $mode "latest") (eq $libraryName "")) }}
      {{ template "errorMsg" "Some required options are not set." }}
    {{ else }}

      {{/* Fetch user ID */}}
      {{ $userID := "" }}
      {{ $usersCall := newRequest (print $baseURL "/Users")
          | withParameter "api_key" $apiKey
          | withHeader "Accept" "application/json"
          | getResponse }}

      {{ range $i, $user := $usersCall.JSON.Array "" }}
        {{ if eq ($user.String "Name") $userName }}
          {{ $userID = $user.String "Id" }}
          {{ break }}
        {{ end }}
      {{ end }}
      {{ if eq $userID "" }}
        {{ template "errorMsg" (printf "User '%s' not found." $userName) }}
      {{ else }}

        {{ $items := "" }}

        {{ if eq $mode "latest" }}

          {{/* Fetch library ID */}}
          {{ $libraryID := "" }}
          {{ $userViewsCall := newRequest (print $baseURL "/UserViews")
              | withParameter "api_key" $apiKey
              | withParameter "userId" $userID
              | withHeader "Accept" "application/json"
              | getResponse }}

          {{ range $i, $item := $userViewsCall.JSON.Array "Items" }}
            {{ if eq ($item.String "Name") $libraryName }}
              {{ $libraryID = $item.String "Id" }}
              {{ break }}
            {{ end }}
          {{ end }}

          {{ if eq $libraryID "" }}
            {{ template "errorMsg" (printf "Library '%s' not found." $libraryName) }}
          {{ else }}
            {{/* Fetch latest items */}}
            {{ $latestCall := newRequest (print $baseURL "/Users/" $userID "/Items/Latest")
                | withParameter "api_key" $apiKey
                | withParameter "Limit" $itemCount
                | withParameter "ParentId" $libraryID
                | withParameter "IncludeItemTypes" $mediaTypes
                | withParameter "GroupItems" "true"
                | withHeader "Accept" "application/json"
                | getResponse }}
            {{ $items = $latestCall.JSON.Array "" }}
          {{ end }}

        {{ else if eq $mode "nextup" }}

          {{/* Fetch next up items */}}
          {{ $nextUpCall := newRequest (print $baseURL "/Shows/NextUp")
            | withParameter "api_key" $apiKey
            | withParameter "UserId" $userID
            | withParameter "Limit" $itemCount
            | withParameter "EnableResumable" "true"
            | withHeader "Accept" "application/json"
            | getResponse }}
          {{ $items = $nextUpCall.JSON.Array "Items" }}

        {{ else }}
          {{ template "errorMsg" "Unknown mode, expected 'latest' or 'nextup'" }}
        {{ end }}

        {{ if eq (len $items) 0 }}
          <p>No items found, start streaming something!</p>
        {{ else }}

          {{/* Display the item carousel */}}
          <div class="carousel-container show-right-cutoff">
            <div class="cards-horizontal carousel-items-container">
              {{ range $n, $item := $items }}
                {{/* Common item variables */}}
                {{ $mediaType := $item.String "Type" }}
                {{ $title := $item.String "Name" }}
                {{ $itemID := $item.String "Id" }}

                {{/* Media type specific variables */}}
                {{ $seriesTitle := "" }}
                {{ $artist := "" }}
                {{ $seriesID := "" }}
                {{ $season := "" }}
                {{ $episode := "" }}
                {{ $playPercentage := "" }}
                {{ $unwatchedEpisodeCount := "" }}

                {{ if eq $mediaType "Movie" }}
                {{ else if eq $mediaType "Series" }}
                  {{ $unwatchedEpisodeCount = $item.Int "UserData.UnplayedItemCount" }}
                {{ else if eq $mediaType "Episode" }}
                  {{ $unwatchedEpisodeCount = 1 }}
                  {{ $seriesTitle = $item.String "SeriesName" }}
                  {{ $seriesID = $item.String "SeriesId" }}
                  {{ $season = $item.Int "ParentIndexNumber" }}
                  {{ $episode = $item.Int "IndexNumber" }}

                  {{ if $item.Exists "UserData.PlayedPercentage" }}
                    {{ $playPercentage = $item.String "UserData.PlayedPercentage" }}
                  {{ end }}

                  {{/* For latest always refer to the series not individual episodes */}}
                  {{ if eq $mode "latest" }}
                    {{ $itemID = $seriesID }}
                    {{ $title = $seriesTitle }}
                  {{ end }}
                {{ else if eq $mediaType "MusicAlbum" }}
                  {{ $artist = $item.String "AlbumArtist" }}
                {{ end }}

                {{ $linkURL := print $baseURL "/web/#/details?id=" $itemID }}
                {{ $thumbURL := "" }}
                {{ if not (eq $playPercentage "") }}
                  {{/* $thumbURL = concat $baseURL "/Items/" $itemID "/Images/Primary?api_key=" $apiKey "&percentPlayed=" $playPercentage */}}
                  {{ $thumbURL = concat $baseURL "/Items/" $itemID "/Images/Primary?api_key=" $apiKey }}
                {{ else }}
                  {{ $thumbURL = concat $baseURL "/Items/" $itemID "/Images/Primary?api_key=" $apiKey }}
                {{ end }}

                <a class="card widget-content-frame" href="{{ $linkURL | safeURL }}">
                  {{ if $showThumbnail }}
                    <div style="position: relative;">
                      <img src="{{ $thumbURL | safeURL }}"
                        alt="{{ $title }} thumbnail"
                        loading="lazy"
                        class="media-server-thumbnail shrink-0"
                        style="
                          object-fit: fill;
                          border-radius: var(--border-radius) var(--border-radius) 0 0;
                          width: 100%;
                          display: block;
                          {{ if eq $thumbAspectRatio "square" }}aspect-ratio: 1;
                          {{ else if eq $thumbAspectRatio "portrait" }}aspect-ratio: 2/3;
                          {{ else if eq $thumbAspectRatio "landscape" }}aspect-ratio: 16/9;
                          {{ else }}aspect-ratio: initial;
                          {{ end }}
                        "
                      />

                      {{ if and ($showProgressBar) (not (eq $playPercentage "")) }}
                        <div style="
                          position: absolute;
                          bottom: 8px;
                          left: 8px;
                          right: 8px;
                          height: 6px;
                          border-radius: var(--border-radius);
                          overflow: hidden;
                          background-color: rgba(255, 255, 255, 0.2);
                        ">
                          <div style="
                            width: {{ print $playPercentage "%" }};
                            height: 100%;
                            border-radius: var(--border-radius) 0 0 var(--border-radius);
                            background-color: var(--color-primary)
                          "></div>
                        </div>
                      {{ end }}
                    </div>
                  {{ end }}

                  <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                    <ul class="flex flex-column justify-evenly margin-bottom-3 {{ if $isSmallColumn }}size-h6{{ end }}" style="height: 100%;">
                      {{ if eq $mode "latest" }}
                        {{ if or (eq $mediaType "Series") (eq $mediaType "Episode") }}
                          <ul class="list-horizontal-text flex-nowrap">
                            <li class="color-primary shrink-0">{{ $unwatchedEpisodeCount }}</li>
                            <li class="text-truncate">{{ $title }}</li>
                          </ul>
                        {{ else if eq $mediaType "MusicAlbum" }}
                          <ul class="list-horizontal-text flex-nowrap">
                            <li class="color-primary text-truncate">{{ $artist }}</li>
                            <li class="text-truncate">{{ $title }}</li>
                          </ul>
                        {{ else }}
                          <li class="text-truncate">{{ $title }}</li>
                        {{ end }}
                      {{ else if eq $mode "nextup" }}
                        <ul class="list-horizontal-text flex-nowrap">
                          <li class="color-primary shrink-0">S{{ $season }}E{{ $episode }}</li>
                          <li class="text-truncate">{{ $seriesTitle }}</li>
                        </ul>
                        <li class="text-truncate">{{ $title }}</li>
                      {{ end }}
                    </ul>
                  </div>
                </a>
              {{ end }}
            </div>
          </div>
        {{ end }}

      {{ end }}

    {{ end }}

- type: custom-api
  cache: 1m
  title: Now Playing
  url: ${JELLYFIN_URL}/Sessions
  headers:
    X-Emby-Token: ${API_TOKEN}
  template: |
    {{ $sessions := .JSON.Array "" }}
    {{ $found := false }}
    {{ $showArt := true }}

    {{ range $index, $s := $sessions }}

      {{ $type := $.JSON.String (printf "%d.NowPlayingItem.MediaType" $index) }}

      {{ if eq $type "Audio" }}
        {{ $found = true }}

        {{ $user := $.JSON.String (printf "%d.UserName" $index) }}
        {{ $device := $.JSON.String (printf "%d.DeviceName" $index) }}
        {{ $client := $.JSON.String (printf "%d.Client" $index) }}

        {{ if eq $device "" }}
          {{ $device = $client }}
        {{ end }}

        {{ $name := $.JSON.String (printf "%d.NowPlayingItem.Name" $index) }}
        {{ $artist := $.JSON.String (printf "%d.NowPlayingItem.Artists.0" $index) }}
        {{ $album := $.JSON.String (printf "%d.NowPlayingItem.Album" $index) }}
        {{ $albumId := $.JSON.String (printf "%d.NowPlayingItem.AlbumId" $index) }}

        {{ $position := $.JSON.Float (printf "%d.PlayState.PositionTicks" $index) }}
        {{ $runtime := $.JSON.Float (printf "%d.NowPlayingItem.RunTimeTicks" $index) }}

        {{ $progress := 0.0 }}
        {{ if gt $runtime 0.0 }}
          {{ $progress = mul (div $position $runtime) 100.0 }}
        {{ end }}

        <div style="
          display:flex;
          gap:12px;
          align-items:center;
          padding:12px;
          border-radius:12px;
          background:var(--color-subdue);
          margin-bottom:10px;
        ">

          {{ if and $showArt (ne $albumId "") }}
          <img
            src="${JELLYFIN_URL}/Items/{{ $albumId }}/Images/Primary?maxWidth=200&quality=80&api_key=${API_TOKEN}"
            style="width:60px;height:60px;border-radius:8px;object-fit:cover;"
          />
          {{ end }}

          <div style="flex:1; overflow:hidden;">

            <div style="font-size:12px;opacity:0.7;margin-bottom:2px;">
              {{ $device }} · {{ $user }}
            </div>

            <div style="font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
              {{ $name }}
            </div>

            <div style="font-size:12px;opacity:0.7;">
              {{ $artist }}
            </div>

            <div style="font-size:11px;opacity:0.5;">
              {{ $album }}
            </div>

            <div style="margin-top:8px;">
              <div style="
                background:var(--color-highlight);
                height:6px;
                border-radius:5px;
                overflow:hidden;
              ">
                <div style="
                  width:{{ printf "%.2f" $progress }}%;
                  background:var(--color-positive);
                  height:100%;
                  transition: width 0.5s ease;
                "></div>
              </div>
            </div>

          </div>
        </div>

      {{ end }}

    {{ end }}

    {{ if not $found }}
      <div style="opacity:0.6;">Nothing playing</div>
    {{ end }}

- type: custom-api
  title: "Jellyfin/Emby Stats"
  base-url: ${JELLYFIN_URL}
  options:
    url: ${JELLYFIN_URL}
    key: ${JELLYFIN_API_KEY}

  template: |
    {{ $url := .Options.StringOr "url" "" }}
    {{ $key := .Options.StringOr "key" "" }}

    {{- if or (eq $url "") (eq $key "") -}}

      <p>Error: The URL or API Key was not configured in the widget options.</p>

    {{- else -}}

      {{- $requestUrl := printf "%s/emby/Items/Counts?api_key=%s" $url $key -}}
      {{- $jellyfinData := newRequest $requestUrl | getResponse -}}

      {{- if eq $jellyfinData.Response.StatusCode 200 -}}
        <div class="flex flex-column gap-5">
          <div class="flex justify-between text-center">

            <div>
              <div class="color-highlight size-h3">{{ $jellyfinData.JSON.Int "MovieCount" | formatNumber }}</div>
              <div class="size-h5 uppercase">Movies</div>
            </div>

            <div>
              <div class="color-highlight size-h3">{{ $jellyfinData.JSON.Int "SeriesCount" | formatNumber }}</div>
              <div class="size-h5 uppercase">TV Shows</div>
