    {{- end -}}

- type: custom-api
  title: Karakeep Dashboard
  cache: 30m
  method: GET
  options:
    limit: 10            # Number of bookmarks to fetch and display
    collapse-after: 6    # Number of bookmarks after which list collapses
    in-new-tab: true     # Open bookmark links in a new tab if true
  headers:
    Authorization: Bearer ${KARAKEEP_API_KEY}
    Accept: application/json
  url: http://${KARAKEEP_URL}/api/v1/users/me/stats   # API endpoint for user stats
  template: |
    {{/* Display user stats fetched from the specified URL */}}
    <div class="flex justify-center gap-10 text-center" style="margin-bottom:1rem;">
      <div>
        <div class="color-highlight size-h3">{{ .JSON.Int "numBookmarks" | formatNumber }}</div>
        <div class="size-h6">BOOKMARKS</div>
      </div>
      {{/* Vertical separator between stats */}}
      <div style="width:1px; height:40px; background-color: rgba(255,255,255,0.2);"></div>
      <div>
        <div class="color-highlight size-h3">{{ .JSON.Int "numTags" | formatNumber }}</div>
        <div class="size-h6">TAGS</div>
      </div>
    </div>

    {{/* Fetch the latest bookmarks using newRequest inside the template */}}
    {{ $limit := .Options.IntOr "limit" 10 }}
    {{ $collapseAfter := .Options.IntOr "collapse-after" 6 }}
    {{ $newTab := .Options.BoolOr "in-new-tab" false }}
    {{ $urlBookmarks := printf "http://%s/api/v1/bookmarks?limit=%d" "${KARAKEEP_URL}" $limit }}

    {{ $respBookmarks := newRequest $urlBookmarks
      | withHeader "Authorization" (printf "Bearer %s" "${KARAKEEP_API_KEY}")
      | withHeader "Accept" "application/json"
      | getResponse }}
    {{ $bookmarks := $respBookmarks.JSON.Array "bookmarks" }}

    {{/* Display bookmarks in a collapsible list */}}
    <ul class="list list-gap-10 collapsible-container" data-collapse-after="{{ $collapseAfter }}" style="max-width: 100%; overflow-x: hidden; font-size: 1em; line-height: 1.3em; padding-left: 0; margin: 0;">
      {{ range $b := $bookmarks }}
        {{ $content := $b.Get "content" }}
        {{ $title := $content.String "title" }}
        {{ $url := $content.String "url" }}

        {{/* Limit displayed title length to avoid UI issues, add ellipsis if truncated */}}
        {{ $maxLength := 60 }}
        {{ $displayTitle := $title }}
        {{ if gt (len $title) $maxLength }}
          {{ $displayTitle = print (slice $title 0 $maxLength) "…" }}
        {{ end }}

        <li style="list-style: none; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
          <a href="{{ $url }}"
             title="{{ $title }}"  {{/* Full title on hover */}}
             {{ if $newTab }} target="_blank" rel="noopener"{{ end }}
             class="color-highlight"  {{/* Highlighted link color */}}
             style="text-decoration: none; cursor: pointer;">
            {{ $displayTitle }}
          </a>
        </li>
      {{ end }}
    </ul>

- type: custom-api
  title: On Deck
  frameless: true
  cache: 5m
  options:
    base-url: ${KAVITA_URL}
    api-key: ${KAVITA_KEY}
    mode: "on-deck"
    small-column: false
    show-thumbnail: false
    thumbnail-aspect-ratio: "portrait"
  template: |
    {{/* Required config options */}}
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $mode := .Options.StringOr "mode" "recently-added" }}

    {{/* Optional config options */}}
    {{ $library := .Options.StringOr "library" "0" }}
    {{ $isSmallColumn:= .Options.BoolOr "small-column" false }}
    {{ $thumbAspectRatio := .Options.StringOr "thumbnail-aspect-ratio" "" }}
    {{ $showThumbnail := .Options.BoolOr "show-thumbnail" false }}
    {{ $showProgressBar := .Options.BoolOr "progress-bar" true }}

    {{/* Error message template */}}
    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{/* Check required fields */}}
    {{ if or (eq $baseURL "") (eq $apiKey "") (eq $mode "")  }}
      {{ template "errorMsg" "Some required options are not set." }}
    {{ else }}

      {{/* Authenticate user */}}
      {{ $authenticateCall := newRequest (print $baseURL "/api/Plugin/authenticate")
          | withParameter "apiKey" $apiKey
          | withParameter "pluginName" "glance"
          | withHeader "Accept" "application/json"
          | withStringBody ""
          | getResponse }}
      {{ $token := concat "Bearer " ($authenticateCall.JSON.String "token") }}

      {{ if eq $token "" }}
        {{ template "errorMsg" (printf "Error authneticating: %s" $authenticateCall) }}
      {{ else }}
        {{ $items := "" }}

        {{ if eq $mode "recently-added" }}
          {{ $recentlyAddedCall := newRequest (print $baseURL "/api/Series/recently-added-v2")
              | withParameter "pageNumber" "1"
              | withParameter "pageSize" "20"
              | withHeader "Authorization" $token
              | withHeader "Accept" "application/json"
              | withHeader "Content-Type" "application/json"
              | withStringBody "{}"
              | getResponse }}
          {{ $items = $recentlyAddedCall.JSON.Array "" }}

        {{ else if eq $mode "recently-updated" }}
          {{ $recentlyUpdatedCall := newRequest (print $baseURL "/api/Series/recently-updated-series")
              | withHeader "Authorization" $token
              | withHeader "Accept" "application/json"
              | withStringBody ""
              | getResponse }}
          {{ $items = $recentlyUpdatedCall.JSON.Array "" }}

        {{ else if eq $mode "on-deck" }}
          {{ $onDeckCall:= newRequest (print $baseURL "/api/Series/on-deck")
              | withParameter "libraryId" $library
              | withHeader "Authorization" $token
              | withHeader "Accept" "application/json"
              | withStringBody ""
              | getResponse }}
          {{ $items = $onDeckCall.JSON.Array "" }}
        {{ else }}
          {{ template "errorMsg" "Unknown mode, expected 'recently-added', 'recently-updated', or 'on-deck'" }}
        {{ end }}

        {{ if eq (len $items) 0 }}
          <p>No items found, start reading something!</p>
        {{ else }}

          {{/* Display the item carousel */}}
          <div class="carousel-container show-right-cutoff">
            <div class="cards-horizontal carousel-items-container">
              {{ range $n, $item := $items }}
                {{/* Common item variables */}}
                {{ $libraryID := $item.String "libraryId" }}
                {{ $seriesID := $item.String "id" }}
                {{ $title := $item.String "name" }}

                {{ $progressPercent := ""}}

                {{ if eq $mode "recently-updated" }}
                  {{ $title = $item.String "seriesName" }}
                  {{ $seriesID = $item.String "seriesId" }}
                {{ else if eq $mode "on-deck" }}
                  {{ $pagesRead := $item.Float "pagesRead" }}
                  {{ $pages := $item.Float "pages" }}
                  {{ $progress := div $pagesRead $pages }}
                  {{ $progressPercent = printf "%f" (mul 100 $progress) }}
                {{ end }}

                {{ $linkURL := concat $baseURL "/library/" $libraryID "/series/" $seriesID }}
                {{ $thumbURL := concat $baseURL "/api/image/series-cover?seriesId=" $seriesID "&apiKey=" $apiKey }}

                <a class="card widget-content-frame" href="{{ $linkURL | safeURL }}">
                  {{ if $showThumbnail }}
                    <div style="position: relative;">
                      <img src="{{ $thumbURL | safeURL }}"
                        alt="{{ $title }} thumbnail"
                        loading="lazy"
                        class="media-server-thumbnail shrink-0"
                        style="
                          object-fit: fill;
                          border-radius: var(--border-radius) var(--border-radius) 0 0;
                          width: 100%;
                          display: block;
                          {{ if eq $thumbAspectRatio "square" }}aspect-ratio: 1;
                          {{ else if eq $thumbAspectRatio "portrait" }}aspect-ratio: 2/3;
                          {{ else if eq $thumbAspectRatio "landscape" }}aspect-ratio: 16/9;
                          {{ else }}aspect-ratio: initial;
                          {{ end }}
                        "
                      />

                      {{ if and ($showProgressBar) (not (eq $progressPercent "")) }}
                        <div style="
                          position: absolute;
                          bottom: 8px;
                          left: 8px;
                          right: 8px;
                          height: 6px;
                          border-radius: var(--border-radius);
                          overflow: hidden;
                          background-color: rgba(255, 255, 255, 0.2);
                        ">
                          <div style="
                            width: {{ print $progressPercent "%" }};
                            height: 100%;
                            border-radius: var(--border-radius) 0 0 var(--border-radius);
                            background-color: var(--color-primary)
                          "></div>
                        </div>
                      {{ end }}
                    </div>
                  {{ end }}

                  <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                    <ul class="flex flex-column justify-evenly margin-bottom-3 {{if $isSmallColumn}}size-h6{{end}}" style="height: 100%;">
                    <li class="text-truncate">{{ $title }}</li>
                    </ul>
                  </div>
                </a>
              {{ end }}
            </div>
          </div>
        {{ end }}
      {{ end }}

    {{ end }}

- type: custom-api
  title: Recent Series                                        
  frameless: true
  cache: 15m
  options:                                                   
    base-url: ${KOMGA_URL}                                   # URL pointing to your Komga
    api-key: ${KOMGA_API_KEY}                                # retrieve from Komga in: My Account -> API Keys -> +
    library-id: ${LIBRARY_ID}                                # id of the Komga library (can be spotted in the url of that library)
    items: 10                                                # max number of cards to show in the widgets
    mode: new                                                # only "new" or "updated" are allowed
  template: |
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $libraryId := .Options.StringOr "library-id" "" }}
    {{ $numberOfItems := .Options.IntOr "items" 10 }}
    {{ $mode := .Options.StringOr "mode" "new" }}

    {{
      $auth := newRequest (concat $baseURL "/api/v1/login")
        | withHeader "X-API-Key" $apiKey
        | getResponse
    }}

    {{
      $content := newRequest (concat $baseURL "/api/v1/series/" $mode "?library_id=" $libraryId)
        | withHeader "X-API-Key" $apiKey
        | getResponse
    }}

    {{ $session := $auth.Response.Header.Get "Set-Cookie" }}

    {{ if or (eq $baseURL "") (eq $apiKey "") }}
        <div class="widget-content-frame" style="flex=0 0 25vh; display:flex">
            <div class="grow padding-inline-widget margin-top-10 margin-bottom-10 color-negative">
                Komga base-url or API token not set.
            </div>
        </div>
    {{ else }}
        {{ if eq $content.Response.StatusCode 200 }}
          <div class="cards-horizontal carousel-items-container">
              {{ $arr := $content.JSON.Array "content" }}
              {{ $len := len $arr }}
              {{ $shown := 0 }}

              {{ range $i, $_ := $arr }}
                {{ if lt $shown $numberOfItems }}
                  {{ $el := index $arr $i }}

                  <a class="card widget-content-frame"
                     href="{{ $baseURL }}/series/{{ $el.String "id" }}"
                     style="flex:0 0 25vh;min-width:170px; min-height: 150px; display:flex;flex-direction:column;box-sizing:border-box;text-decoration:none;color:inherit;">
                    <div style="position: relative;">
                        <img src="{{ $baseURL }}/api/v1/series/{{ $el.String "id" }}/thumbnail"
                             alt="{{ $el.String "metadata.title" }}"
                             loading="lazy"
                             class="media-server-thumbnail shrink-0 loaded finished-transition"
                             style="width:100%; height: 37vh; min-height: 250px; display:block;border-radius:var(--border-radius) var(--border-radius) 0 0;object-fit:cover;" 
                        />
                    </div>
                    <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                      <ul class="flex flex-column justify-evenly margin-bottom-3" style="height:100%; gap:4px;">
                        <li class="text-truncate color-primary" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="{{ $el.String "title" }}">
                          {{ $el.String "metadata.title" }} <!-- ({{ $el.String "metadata.releaseDate" | parseTime "2006-01-02" | formatTime "2006" }}) -->
                        </li>
                        <li style="font-size:0.85em;opacity:0.7;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">
                          Added: {{ $el.String "created" | parseTime "RFC3339" | formatTime "Jan 2, 2006" }}
                        </li>
                      </ul>
                    </div>
                  </a>
                {{ $shown = add $shown 1 }}
                {{ end }}
              {{ end }}
           </div>
          {{ else }}
            <div class="widget-content-frame" style="flex=0 0 25vh; display:flex">
                <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                    Failed to fetch items (status {{ $content.Response.StatusCode }})
                </div>
            </div>
          {{ end }}
    {{ end }}

- type: custom-api
  title: Komodo Servers
  method: POST
  cache: 5m
  allow-insecure: false # Change to true if your Komodo core uses a self-signed certificate
  url: ${KOMODO_URL}/read
  body-type: json
  body:
    type: ListServers
    params: {}
  headers:
    Content-Type: application/json
    X-Api-Key: ${KOMODO_API_KEY}
    X-Api-Secret: ${KOMODO_API_SECRET}
  options:
    base-url: ${KOMODO_URL}
    api-key: ${KOMODO_API_KEY}
    api-secret: ${KOMODO_API_SECRET}
  template: |
    {{ $urlBase := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $apiSecret := .Options.StringOr "api-secret" "" }}
    <style>
      .list-horizontal-text.no-bullets-komodo-servers > *:not(:last-child)::after {
          content: none !important;
      }
      .list-horizontal-text.no-bullets-komodo-servers > *:not(:last-child) {
        margin-right: 1em;
      }
    </style>

    {{ $servers := .JSON.Array "" }}
    {{ $total := len $servers }}
    {{ $Ok := 0 }}
    {{ $NotOk := 0 }}
    {{ $Disabled := 0 }}
    {{ $unknown := 0 }}
    {{ range $servers }}
      {{ $state := .String "info.state" }}
      {{ if eq $state "Ok" }}{{ $Ok = add $Ok 1 }}{{ end }}
      {{ if eq $state "NotOk" }}{{ $NotOk = add $NotOk 1 }}{{ end }}
      {{ if eq $state "Disabled" }}{{ $Disabled = add $Disabled 1 }}{{ end }}
      {{ if or (eq $state "") (eq $state "unknown") }}{{ $unknown = add $unknown 1 }}{{ end }}
    {{ end }}

    <div style="display:flex; align-items:center; gap:12px; margin-bottom: 1rem;">
      <div style="display:flex; align-items:center; gap:12px;">
        <div style="width:30px; height:30px; flex-shrink:0; display:flex; justify-content:center; align-items:center; overflow:hidden;">
          <img src="https://cdn.jsdelivr.net/gh/homarr-labs/dashboard-icons/svg/komodo.svg" height="30" style="object-fit:contain;">
        </div>
        <div style="flex-grow:1; min-width:0;">
          <h4 class="size-h4 block text-truncate color-highlight">Komodo Servers</h4>
          <ul class="list list-horizontal-text no-bullets-komodo-servers items-center">
            <li data-popover-type="text" data-popover-text="{{ $Ok }}/{{ $total }} Ok">
              <p style="display:inline-flex;align-items:center;">
                <svg xmlns="http://www.w3.org/2000/svg" 
                viewBox="0 0 256 256" 
                style="height:2rem; margin-right:0.5rem; stroke:var(--color-positive); fill:var(--color-positive);">
                  <path d="M224,64H32A16,16,0,0,0,16,80v96a16,16,0,0,0,16,16H224a16,16,0,0,0,16-16V80A16,16,0,0,0,224,64Zm0,112H32V80H224v96Zm-24-48a12,12,0,1,1-12-12A12,12,0,0,1,200,128Z" />
                </svg>
                {{ $Ok }}
              </p>
            </li>
            <li data-popover-type="text" data-popover-text="{{ $Disabled }}/{{ $total }} disabled">
              <p style="display:inline-flex;align-items:center;">
                <svg xmlns="http://www.w3.org/2000/svg" 
                viewBox="0 0 256 256" 
                style="height:2rem; margin-right:0.5rem; stroke:var(--color-progress-value); fill:var(--color-progress-value);">
                  <path d="M224,64H32A16,16,0,0,0,16,80v96a16,16,0,0,0,16,16H224a16,16,0,0,0,16-16V80A16,16,0,0,0,224,64Zm0,112H32V80H224v96Zm-24-48a12,12,0,1,1-12-12A12,12,0,0,1,200,128Z" />
                </svg>
                {{ $Disabled }}
              </p>
            </li>
            <li data-popover-type="text" data-popover-text="{{ $NotOk }}/{{ $total }} Not OK; {{ $unknown }}/{{ $total }} unknown" >
              <p style="display:inline-flex;align-items:center;">
                <svg xmlns="http://www.w3.org/2000/svg" 
                viewBox="0 0 256 256" 
                style="height:2rem; margin-right:0.5rem; stroke:var(--color-negative); fill:var(--color-negative);">
                  <path d="M224,64H32A16,16,0,0,0,16,80v96a16,16,0,0,0,16,16H224a16,16,0,0,0,16-16V80A16,16,0,0,0,224,64Zm0,112H32V80H224v96Zm-24-48a12,12,0,1,1-12-12A12,12,0,0,1,200,128Z" />
                </svg>
                {{ add ( $NotOk ) ( $unknown ) }}
              </p>
            </li>
          </ul>
        </div>
      </div>
    </div>
    <ul class="list dynamic-columns list-gap-15 list-with-separator">
      {{ range .JSON.Array "" }}
        {{ $theID := .String "id" }}
        <li style="display:flex; align-items:center; gap:12px; margin-top: .5rem;">
          <div style="flex-grow:1; min-width:0;">
            <a class="size-h4 block text-truncate color-primary flex inline-block items-center" href={{ concat $urlBase "servers/" ( .String "id" ) }} target="_blank">
              {{
                $systemStats := newRequest (concat $urlBase "/read")
                  | withHeader "Content-Type" "application/json"
                  | withHeader "X-Api-Key" $apiKey
                  | withHeader "X-Api-Secret" $apiSecret
                  | withStringBody (printf `{"type":"GetSystemStats","params":{"server":"%s"}}` $theID)
                  | getResponse
              }}

              {{ $state := .String "info.state" }}

              <span
                role="status"
                aria-label="Server Status: {{ $state }}"
                style="
                  width: 8px; 
                  height: 8px; 
                  border-radius: 50%; 
                  background-color: 
                    {{ if eq $state "Ok" }} var(--color-positive); 
                    {{ else if eq $state "Disabled" }} var(--color-text-subdue); 
                    {{ else }} var(--color-negative); 
                    {{ end }} 
                  display: inline-block; 
                  vertical-align: middle;
                  margin-right: 1rem;"
                data-popover-type="text"
                data-popover-text="Server Status: {{ $state }}"
              ></span>
              {{ .String "name"}}
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" style="height:1.25rem;vertical-align:middle;margin-left:0.5rem;stroke: var(--color-primary);fill:var(--color-primary);">
                <path d="M204,64V168a12,12,0,0,1-24,0V93L72.49,200.49a12,12,0,0,1-17-17L163,76H88a12,12,0,0,1,0-24H192A12,12,0,0,1,204,64Z" />
              </svg>
            </a>
            <span class="size-h6 color-subdue">{{ .String "info.address" }}</span>
            {{ if and $systemStats.Response (ge $systemStats.Response.StatusCode 200) (lt $systemStats.Response.StatusCode 300) }}
              {{ $stats := $systemStats.JSON }}
              <ul class="list-horizontal-text no-bullets-komodo-servers">
                <li data-popover-type="text" data-popover-text="CPU Load: {{ printf "%.2f" ( $stats.Float "cpu_perc" ) }}%">
                  <p style="display:inline-flex;align-items:center;">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor" style="height:1.5rem;vertical-align:middle;margin-right:0.5rem;">
                      <path d="M152,96H104a8,8,0,0,0-8,8v48a8,8,0,0,0,8,8h48a8,8,0,0,0,8-8V104A8,8,0,0,0,152,96Zm-8,48H112V112h32Zm88,0H216V112h16a8,8,0,0,0,0-16H216V56a16,16,0,0,0-16-16H160V24a8,8,0,0,0-16,0V40H112V24a8,8,0,0,0-16,0V40H56A16,16,0,0,0,40,56V96H24a8,8,0,0,0,0,16H40v32H24a8,8,0,0,0,0,16H40v40a16,16,0,0,0,16,16H96v16a8,8,0,0,0,16,0V216h32v16a8,8,0,0,0,16,0V216h40a16,16,0,0,0,16-16V160h16a8,8,0,0,0,0-16Zm-32,56H56V56H200v95.87s0,.09,0,.13,0,.09,0,.13V200Z" />
                    </svg>
                    {{ printf "%.2f" ( $stats.Float "cpu_perc" ) }}<span class="color-subdue">&nbsp;%</span>
                  </p>
                </li>
                <li data-popover-type="text" data-popover-text="Memory: {{ printf "%.2f"  ( $stats.Float "mem_used_gb" ) }}/{{ printf "%.2f" ( $stats.Float "mem_total_gb" ) }}GB">
                  <p style="display:inline-flex;align-items:center;">
                    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor" style="height:1.5rem;vertical-align:middle;margin-right:0.5rem;">
                      <path d="M232,56H24A16,16,0,0,0,8,72V200a8,8,0,0,0,16,0V184H40v16a8,8,0,0,0,16,0V184H72v16a8,8,0,0,0,16,0V184h16v16a8,8,0,0,0,16,0V184h16v16a8,8,0,0,0,16,0V184h16v16a8,8,0,0,0,16,0V184h16v16a8,8,0,0,0,16,0V184h16v16a8,8,0,0,0,16,0V72A16,16,0,0,0,232,56ZM24,72H232v96H24Zm88,80a8,8,0,0,0,8-8V96a8,8,0,0,0-8-8H48a8,8,0,0,0-8,8v48a8,8,0,0,0,8,8ZM56,104h48v32H56Zm88,48h64a8,8,0,0,0,8-8V96a8,8,0,0,0-8-8H144a8,8,0,0,0-8,8v48A8,8,0,0,0,144,152Zm8-48h48v32H152Z" />
                    </svg>
                    {{ printf "%.2f" (mul ( div ( $stats.Float "mem_used_gb" ) ( $stats.Float "mem_total_gb" ) ) 100 ) }} <span class="color-subdue">&nbsp;%</span>
                  </p>
                </li>
                {{ range $stats.Array "disks"}}
                  <li data-popover-type="text" data-popover-text="Mount: {{ .String "mount" }}; Format: {{ .String "file_system" }}; Used: {{ printf "%.2f" ( .Float "used_gb" ) }}/{{ printf "%.2f" ( .Float "total_gb" ) }}GB">
                    <p style="display:inline-flex;align-items:center;">
                      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" fill="currentColor" style="height:2rem;vertical-align:middle;margin-right:0.5rem;">
                        <path d="M208,136H48a16,16,0,0,0-16,16v48a16,16,0,0,0,16,16H208a16,16,0,0,0,16-16V152A16,16,0,0,0,208,136Zm0,64H48V152H208v48Zm0-160H48A16,16,0,0,0,32,56v48a16,16,0,0,0,16,16H208a16,16,0,0,0,16-16V56A16,16,0,0,0,208,40Zm0,64H48V56H208v48ZM192,80a12,12,0,1,1-12-12A12,12,0,0,1,192,80Zm0,96a12,12,0,1,1-12-12A12,12,0,0,1,192,176Z" />
                      </svg>
                      {{ printf "%.2f" (mul ( div ( .Float "used_gb" ) ( .Float "total_gb" ) ) 100 ) }} <span class="color-subdue">&nbsp;%</span>
                    </p>
                  </li>
                {{ end }}
              </ul>
            {{ else }}
              <span class="color-negative size-h6">Stats unavailable</span>
            {{ end }}
          </div>
        </li>
      {{ end }}
    </ul>

- type: custom-api
