                      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" style="height:1.5rem;vertical-align:middle;margin-left:0.5rem;stroke: var(--color-primary);fill:var(--color-primary);">
                        <path d="M204,64V168a12,12,0,0,1-24,0V93L72.49,200.49a12,12,0,0,1-17-17L163,76H88a12,12,0,0,1,0-24H192A12,12,0,0,1,204,64Z" />
                      </svg>
                    <span class="
                      {{ if (or ( eq $state "deploying") ( eq $state "running") ( eq $state "created") ) }}
                        status-badge-positive-komodo-stacks
                      {{ else if (or ( eq $state "paused") ( eq $state "down") ( eq $state "stopped") ) }}
                        status-badge-neutral-komodo-stacks
                      {{ else }}
                        status-badge-negative-komodo-stacks
                      {{ end }} 
                      size-h6 ">
                      {{ $state }}
                    </span>
                  </a>
                  <div>
                    <a class="size-h5 color-subdue inline-block flex" href={{ concat $urlBase "servers/" ( $serverID ) }} target="_blank">
                    Server:
                      <span class="color-base inline-block items-center">
                        {{ $serverName }}
                      </span>
                      <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 256 256" style="height:1.1rem;margin-left:0.25rem;stroke: var(--color-primary);fill:var(--color-primary);">
                        <path d="M204,64V168a12,12,0,0,1-24,0V93L72.49,200.49a12,12,0,0,1-17-17L163,76H88a12,12,0,0,1,0-24H192A12,12,0,0,1,204,64Z" />
                      </svg>
                    </a>
                  </div>
                  <div class="flex margin-top-5 size-h6">
                    <div>Last Update: </div>
                    <div class="value-separator"></div>
                    <div class="color-highlight text-very-compact">{{ formatTime "DateTime" ( parseTime "unix" (printf "%d" (div ( $stack.Int "updated_at" ) 1000 ) ) ) }}<span class="color-base size-h5"></span></div>
                  </div>
                </div>
              </div>
            </div>
          </li>
        {{ end }}
      </ul>
    </div>

- type: custom-api
  title: LeetCode Daily Question
  cache: 6h
  url: https://leetcode.com/graphql
  method: POST
  headers:
    Accept: application/json
  body-type: json
  body:
    query: |
      query questionOfToday {
        activeDailyCodingChallengeQuestion {
          link
          question {
            questionId
            title
            difficulty
            topicTags {
              name
              slug
            }
          }
        }
      }
    operationName: questionOfToday
  template: |
    <div class="leetcode-card">
      <style>
        .leetcode-card {
          max-width: 600px;
          margin: 8px auto;
          font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
          transition: transform 0.2s ease, box-shadow 0.2s ease;
        }
        .leetcode-card h1 {
          font-size: 24px;
          margin: 0 0 16px;
          line-height: 1.3;
        }
        .leetcode-card h1 a {
          color: #8CAAEE;
          text-decoration: none;
          transition: color 0.2s ease;
        }
        .leetcode-card h1 a:hover {
          color: #BAC8FF;
          text-decoration: underline;
        }
        .leetcode-card p {
          margin: 8px 0;
          color: #C6D0F5;
          font-size: 16px;
        }
        .leetcode-card .difficulty {
          font-weight: 600;
          color: #A5ADCE;
        }
        .leetcode-card .difficulty.Easy {
          color: #A6D189;
        }
        .leetcode-card .difficulty.Medium {
          color: #E5C890;
        }
        .leetcode-card .difficulty.Hard {
          color: #E78284;
        }
        .leetcode-card .topics {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin: 12px 0;
        }
        .leetcode-card .topic-tag {
          background: #CA9EE6;
          color: #303446;
          padding: 4px 12px;
          border-radius: 16px;
          font-size: 14px;
          font-weight: 500;
          transition: transform 0.2s ease;
        }
        .leetcode-card .topic-tag:hover {
          transform: scale(1.05);
        }
        .leetcode-card .premium {
          color: #E78284;
          font-weight: 600;
          margin-top: 12px;
        }
        @media (max-width: 600px) {
          .leetcode-card {
            padding: 16px;
            margin: 8px;
          }
          .leetcode-card h1 {
            font-size: 20px;
          }
          .leetcode-card p {
            font-size: 14px;
          }
          .leetcode-card .topic-tag {
            font-size: 12px;
            padding: 3px 10px;
          }
        }
      </style>
      <h1>
        <a href="https://leetcode.com{{ .JSON.String "data.activeDailyCodingChallengeQuestion.link" }}" target="_blank">
          {{ .JSON.String "data.activeDailyCodingChallengeQuestion.question.questionId" }} - {{ .JSON.String "data.activeDailyCodingChallengeQuestion.question.title" }}
        </a>
      </h1>
      <p class="difficulty {{ .JSON.String "data.activeDailyCodingChallengeQuestion.question.difficulty" }}"><strong>Difficulty:</strong> {{ .JSON.String "data.activeDailyCodingChallengeQuestion.question.difficulty" }}</p>
      <p><strong>Topics:</strong></p>
      <div class="topics">
        {{ if .JSON.Exists "data.activeDailyCodingChallengeQuestion.question.topicTags" }}
          {{ range .JSON.Array "data.activeDailyCodingChallengeQuestion.question.topicTags" }}
            <span class="topic-tag">{{ .String "name" }}</span>
          {{ end }}
        {{ else }}
          <span class="topic-tag">None</span>
        {{ end }}
      </div>
      {{ if .JSON.Bool "data.activeDailyCodingChallengeQuestion.question.paidOnly" }}
        <p class="premium">This is a Premium question</p>
      {{ end }}
    </div>

- type: custom-api
  cache: 30m
  headers:
    Authorization: Bearer <LINKWARDEN_API_KEY>
  method: GET                                                                                     
  template: |
    <ul class="list list-gap-10 collapsible-container" data-collapse-after="<LINKS_TO_BE_VISIBLE>">
      {{ range .JSON.Array "response" }}
        <li>
          {{ $title := .String "name" }}
          {{ if gt (len $title) 50 }}
            {{ $title = (slice $title 0 50) | printf "%s..." }}
          {{ end }}
          <a class="size-title-dynamic color-primary-if-not-visited"
             href="{{ .String "url" }}"
             target="_self"
             rel="noopener noreferrer">
            {{ $title }}
          </a>
          <ul class="list-horizontal-text">
            <li style="color: {{ .String "collection.color" }};">
              {{ .String "collection.name" }}
            </li>
            {{ $tags := .Array "tags" }}
            {{ range $index, $tag := $tags }}
              <li>{{ .String "name" }}</li>
            {{ end }}
          </ul>
        </li>
      {{ end }}
    </ul>
  title: Bookmarks
  url: http://<LINKWARDEN_HOST>/api/v1/links

- type: custom-api
  title: Listening to
  cache: 5m
  frameless: true
  url: https://api.listenbrainz.org/1/user/${LISTENBRAINZ_USER}/listens?count=1
  template: |
    {{ $listen := .JSON.Get "payload.listens.0" }}
    {{ $mbid := $listen.String "track_metadata.mbid_mapping.release_mbid" }}

    <a href="https://listenbrainz.org/user/${LISTENBRAINZ_USER}" rel="noreferer noopener" class="widget-content-frame container-lb">
      {{ if $mbid }}
        {{ $cover := newRequest (print "https://coverartarchive.org/release/" $mbid) | getResponse }}
        <div class="cover-wrapper-lb">
          <img class="cover-img-lb" src="{{ $cover.JSON.String "images.0.thumbnails.small" }}" />
        </div>
      {{ end }}

      <div class="track-details-lb">
        <p class="color-highlight">{{ $listen.String "track_metadata.track_name" }}</p>
        <p>{{ $listen.String "track_metadata.artist_name" }}</p>
      </div>
    </a>

    <style>
      .container-lb {
         display: grid;
         grid-template-columns: auto 1fr;
         overflow: hidden;
      }
      .cover-wrapper-lb {
         position: relative;
         height: 100%;
         aspect-ratio: 1 / 1;
      }
      .cover-img-lb {
         position: absolute;
         top: 0;
         left: 0;
         width: 100%;
         height: 100%;
      }
      .track-details-lb {
         padding: var(--widget-content-padding);
         overflow: hidden;
      }
      .track-details-lb > p {
         overflow: hidden;
         text-overflow: ellipsis;
         white-space: nowrap;
      }
    </style>

- type: custom-api
  title: Live Tennis
  cache: 2m
  url: https://api.livetennisapi.com/api/public/v1/matches?status=live&limit=10
  headers:
    x-api-key: ${LIVETENNIS_API_KEY}
  template: |
    {{ if ne .Response.StatusCode 200 }}
      <div class="color-negative">Failed to fetch matches (HTTP {{ .Response.StatusCode }}) &mdash; check your LIVETENNIS_API_KEY</div>
    {{ else }}
    {{ $matches := .JSON.Array "data" }}
    {{ if $matches }}
      <div class="flex flex-column gap-10">
        {{ $prevLabel := "" }}
        {{ range $matches }}
          {{ $m := . }}
          {{ $label := $m.String "tournament" }}
          {{ $round := $m.String "round" }}
          {{ $round = trimPrefix $label $round }}
          {{ $round = trimPrefix " - " $round }}
          {{ $round = trimPrefix "- " $round }}
          {{ $round = trimPrefix " " $round }}
          {{ if $round }}{{ $label = concat $label " · " $round }}{{ end }}
          {{ if ne $label $prevLabel }}
            <div class="size-h5 color-highlight text-truncate" style="margin-top: 0.3rem;">{{ $label }}</div>
            {{ $prevLabel = $label }}
          {{ end }}
          {{ $hasScore := $m.Exists "score.sets" }}
          {{ $winner := $m.Int "winner" }}
          {{ $server := $m.Int "score.server" }}
          <div style="padding: 0.4rem 0.6rem; border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; background: rgba(255, 255, 255, 0.03);">
            <div class="flex items-center" style="gap: 0.45rem; padding: 0.15rem 0;">
              <span style="width: 0.8rem; text-align: center; flex-shrink: 0;">{{ if and $hasScore (eq $server 1) (eq $winner 0) }}<span class="color-positive">&#9679;</span>{{ end }}</span>
              <span class="text-truncate{{ if eq $winner 1 }} color-positive{{ end }}" style="flex: 1; min-width: 0;">{{ $m.String "players.p1.name" }}</span>
              {{ if gt ($m.Int "players.p1.ranking") 0 }}<span class="color-subdue size-h6" style="flex-shrink: 0;">#{{ $m.Int "players.p1.ranking" }}</span>{{ end }}
              {{ if $hasScore }}
                <span class="color-subdue" style="font-variant-numeric: tabular-nums; flex-shrink: 0;">{{ range $m.Array "score.games.0" }}<span style="display: inline-block; min-width: 1.1rem; text-align: center;">{{ .Int "" }}</span>{{ end }}</span>
                <span style="font-weight: 700; min-width: 1rem; text-align: center; flex-shrink: 0;">{{ $m.Int "score.sets.0" }}</span>
                <span class="color-highlight" style="font-weight: 600; min-width: 1.7rem; text-align: right; font-variant-numeric: tabular-nums; flex-shrink: 0;">{{ $m.String "score.points.0" }}</span>
              {{ end }}
            </div>
            <div class="flex items-center" style="gap: 0.45rem; padding: 0.15rem 0;">
              <span style="width: 0.8rem; text-align: center; flex-shrink: 0;">{{ if and $hasScore (eq $server 2) (eq $winner 0) }}<span class="color-positive">&#9679;</span>{{ end }}</span>
              <span class="text-truncate{{ if eq $winner 2 }} color-positive{{ end }}" style="flex: 1; min-width: 0;">{{ $m.String "players.p2.name" }}</span>
              {{ if gt ($m.Int "players.p2.ranking") 0 }}<span class="color-subdue size-h6" style="flex-shrink: 0;">#{{ $m.Int "players.p2.ranking" }}</span>{{ end }}
              {{ if $hasScore }}
                <span class="color-subdue" style="font-variant-numeric: tabular-nums; flex-shrink: 0;">{{ range $m.Array "score.games.1" }}<span style="display: inline-block; min-width: 1.1rem; text-align: center;">{{ .Int "" }}</span>{{ end }}</span>
                <span style="font-weight: 700; min-width: 1rem; text-align: center; flex-shrink: 0;">{{ $m.Int "score.sets.1" }}</span>
                <span class="color-highlight" style="font-weight: 600; min-width: 1.7rem; text-align: right; font-variant-numeric: tabular-nums; flex-shrink: 0;">{{ $m.String "score.points.1" }}</span>
              {{ end }}
            </div>
            {{ if and $hasScore ($m.Bool "score.is_tiebreak") }}
              <div class="size-h6 color-highlight" style="text-align: right;">Tiebreak</div>
            {{ end }}
            {{ if not $hasScore }}
              <div class="size-h6 color-subdue" style="text-align: right;">score unavailable</div>
            {{ end }}
          </div>
        {{ end }}
      </div>
    {{ else }}
      <div class="color-subdue">No live matches</div>
    {{ end }}
    {{ end }}

- type: custom-api
  title: London Transport Status
  cache: 15m
  options:
    lines: [] # optional, e.g. ['windrush', 'jubilee', 'elizabeth']. default is all lines.
  template: |
    <div class="flex flex-column gap-5">
      {{ with .Options.lines }}
        {{ range . }}
          {{ with newRequest (printf "https://api.tfl.gov.uk/line/%s/status" .) | withHeader "User-Agent" "Glance-Dashboard/1.0" | getResponse }}
            {{ if eq .Response.StatusCode 200 }}
              {{ range .JSON.Array "" }}{{ template "line" . }}{{ end }}
            {{ end }}
          {{ end }}
        {{ end }}
      {{ else }}
        {{ with newRequest "https://api.tfl.gov.uk/line/mode/tube/status" | withHeader "User-Agent" "Glance-Dashboard/1.0" | getResponse }}
          {{ if eq .Response.StatusCode 200 }}{{ range .JSON.Array "" }}{{ template "line" . }}{{ end }}{{ end }}
        {{ end }}
        {{ with newRequest "https://api.tfl.gov.uk/line/mode/elizabeth-line/status" | withHeader "User-Agent" "Glance-Dashboard/1.0" | getResponse }}
          {{ if eq .Response.StatusCode 200 }}{{ range .JSON.Array "" }}{{ template "line" . }}{{ end }}{{ end }}
        {{ end }}
        {{ with newRequest "https://api.tfl.gov.uk/line/mode/overground/status" | withHeader "User-Agent" "Glance-Dashboard/1.0" | getResponse }}
          {{ if eq .Response.StatusCode 200 }}{{ range .JSON.Array "" }}{{ template "line" . }}{{ end }}{{ end }}
        {{ end }}
      {{ end }}
    </div>

    {{ define "line" }}
    {{ $id := .String "id" }}{{ $status := (index (.Array "lineStatuses") 0).String "statusSeverityDescription" }}
    <div class="flex justify-between items-center" style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.1);">
      <div class="flex items-center gap-10">
        <div style="width: 20px; height: 4px; border-radius: 2px; background-color: {{ if eq $id "bakerloo" }}#B36305{{ else if eq $id "central" }}#E32017{{ else if eq $id "circle" }}#FFD300{{ else if eq $id "district" }}#00782A{{ else if eq $id "hammersmith-city" }}#F3A9BB{{ else if eq $id "jubilee" }}#A0A5A9{{ else if eq $id "metropolitan" }}#9B0056{{ else if eq $id "northern" }}#000000{{ else if eq $id "piccadilly" }}#003688{{ else if eq $id "victoria" }}#0098D4{{ else if eq $id "waterloo-city" }}#95CDBA{{ else if eq $id "elizabeth" }}#7156A5{{ else if eq $id "lioness" }}#E9B908{{ else if eq $id "mildmay" }}#0019A8{{ else if eq $id "windrush" }}#D05F0E{{ else if eq $id "weaver" }}#8F9499{{ else if eq $id "suffragette" }}#64A334{{ else if eq $id "liberty" }}#B05F8C{{ else }}#666{{ end }};"></div>
        <span class="size-h4">{{ .String "name" }}</span>
      </div>
      <div class="text-right">
        <span class="size-h5 {{ if eq $status "Good Service" }}color-positive{{ else if eq $status "Minor Delays" }}color-primary{{ else }}color-negative{{ end }}">{{ $status }}</span>
      </div>
    </div>
    {{ end }}

- type: custom-api
  title: Macro Release Calendar
  cache: 15m
  url: https://api.fxmacrodata.com/v1/calendar/usd
  subrequests:
    inflation:
      url: https://api.fxmacrodata.com/v1/announcements/usd/inflation?limit=1
    policy-rate:
      url: https://api.fxmacrodata.com/v1/announcements/usd/policy_rate?limit=1
    unemployment:
      url: https://api.fxmacrodata.com/v1/announcements/usd/unemployment?limit=1
  options:
    min-importance: medium
    max-items: 10
    collapse-after: 5
  template: |
    {{ define "latest-value" }}
      {{ if and (eq .Response.StatusCode 200) (.JSON.Exists "data.0.val") }}
        {{ $decimals := "%.1f" }}
        {{ if eq (.JSON.String "indicator") "policy_rate" }}{{ $decimals = "%.2f" }}{{ end }}
        {{ $change := .JSON.Float "data.0.change_from_previous" }}
        <div class="size-h3 color-highlight">{{ printf $decimals (.JSON.Float "data.0.val") }}%</div>
        <div class="size-h6" title="{{ .JSON.String "name" }}">{{ .JSON.String "data.0.date" | parseTime "DateOnly" | formatTime "Jan 2006" }}</div>
        <div class="size-h6 color-subdue">
          {{ if gt $change 0.0 }}{{ printf (concat "%+" (trimPrefix "%" $decimals)) $change }}
          {{ else if lt $change 0.0 }}{{ printf $decimals $change }}
          {{ else }}unch{{ end }}
        </div>
      {{ else }}
        <div class="size-h3 color-subdue">n/a</div>
        <div class="size-h6 color-negative">{{ .Response.Status }}</div>
      {{ end }}
    {{ end }}

    <div class="flex justify-between text-center" style="margin-bottom: 1.5rem;">
      <div style="flex: 1;">
        <div class="size-h6 color-subdue">INFLATION</div>
        {{ template "latest-value" (.Subrequest "inflation") }}
      </div>
      <div style="flex: 1;">
        <div class="size-h6 color-subdue">POLICY RATE</div>
        {{ template "latest-value" (.Subrequest "policy-rate") }}
      </div>
      <div style="flex: 1;">
        <div class="size-h6 color-subdue">UNEMPLOYMENT</div>
        {{ template "latest-value" (.Subrequest "unemployment") }}
      </div>
    </div>

    {{ if ne .Response.StatusCode 200 }}
      <p class="color-negative">Failed to load the release calendar ({{ .Response.Status }})</p>
    {{ else }}
      {{ $minImportance := .Options.StringOr "min-importance" "medium" }}
      {{ $maxItems := .Options.IntOr "max-items" 10 }}
      {{ $nowUnix := (now).Unix }}
      {{ $count := 0 }}
      <ul class="list list-gap-10 collapsible-container" data-collapse-after="{{ .Options.IntOr "collapse-after" 5 }}">
        {{ range .JSON.Array "data" }}
          {{ $importance := .String "event_importance" }}
          {{ $show := lt $count $maxItems }}
          {{ if lt (.Int "announcement_datetime") $nowUnix }}{{ $show = false }}{{ end }}
          {{ if and (eq $minImportance "high") (ne $importance "high") }}{{ $show = false }}{{ end }}
          {{ if and (eq $minImportance "medium") (eq $importance "low") }}{{ $show = false }}{{ end }}
          {{ if $show }}
            {{ $count = add $count 1 }}
            {{ $at := .String "announcement_datetime" | parseTime "unix" }}
            {{ $name := .String "name" }}
            {{ if eq (.String "release") "policy_rate" }}{{ $name = "Policy Rate Decision" }}{{ end }}
            <li class="flex items-center gap-10">
              <div style="flex: 1; min-width: 0;">
                <div class="color-highlight text-truncate" title="{{ .String "name" }}">{{ $name }}</div>
                <div class="size-h6">
                  {{ $at | formatTime "Mon 2 Jan, 15:04" }}
                  <span class="color-subdue">&middot; <span {{ $at | toRelativeTime }}></span></span>
                </div>
              </div>
              <div class="size-h6 shrink-0 {{ if eq $importance "high" }}color-negative{{ else if eq $importance "medium" }}color-highlight{{ else }}color-subdue{{ end }}" style="text-transform: uppercase;">
                {{ $importance }}
              </div>
            </li>
          {{ end }}
        {{ end }}
      </ul>
      {{ if eq $count 0 }}
        <p class="color-subdue">No upcoming releases match the current filter.</p>
      {{ end }}
    {{ end }}

- type: custom-api
  title: Media Server History
  frameless: true
  cache: 5m
  options:
    media-server: "plex"
    base-url: ${PLEX_URL}
    api-key: ${PLEX_TOKEN}
    # user-name: "yourUserName" # for Jellyfin/Emby
    history-length: "10"
    small-column: false
    compact: true
    show-thumbnail: false
    thumbnail-aspect-ratio: "default"
    show-user: true
    time-absolute: false
    time-format: "Jan 02 15:04"
  template: |
    {{ $mediaServer := .Options.StringOr "media-server" "" }}
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $userName := .Options.StringOr "user-name" "" }}

    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{ if or
      (eq $mediaServer "")
      (eq $baseURL "")
      (eq $apiKey "")
      (and (eq $mediaServer "jellyfin") (eq $userName ""))
    }}
      {{ template "errorMsg" "Some required options are not set" }}
    {{ else }}

    {{ $historyLength := .Options.StringOr "history-length" "10" }}
    {{ $mediaTypes := .Options.StringOr "media-types" "" }}
    {{ if eq $mediaServer "tautulli" }}
      {{ $mediaTypes = .Options.StringOr "media-types" "movie,episode,track" }}
    {{ else if or (eq $mediaServer "jellyfin") (eq $mediaServer "emby") }}
      {{ $mediaTypes = .Options.StringOr "media-types" "Movie,Episode,Audio" }}
    {{ end }}
    {{ $isSmallColumn := .Options.BoolOr "small-column" false }}
    {{ $isCompact := .Options.BoolOr "compact" true }}
    {{ $showThumbnail := .Options.BoolOr "show-thumbnail" false }}
    {{ $thumbAspectRatio := .Options.StringOr "thumbnail-aspect-ratio" "" }}
    {{ $showUser := .Options.BoolOr "show-user" true }}
    {{ $timeAbsolute := .Options.BoolOr "time-absolute" false }}
    {{ $timeFormat := .Options.StringOr "time-format" "Jan 02 15:04" }}

    {{ $userID := "" }}
    {{ $historyRequestURL := "" }}
    {{ $usersRequestURL := "" }}
    {{ $historyCall := "" }}
    {{ $usersCall := "" }}
    {{ $history := "" }}
    {{ $users := "" }}

    {{ if eq $mediaServer "plex" }}
      {{ $historyRequestURL = concat $baseURL "/status/sessions/history/all" }}
      {{ $historyCall = newRequest $historyRequestURL
        | withParameter "limit" $historyLength
        | withParameter "sort" "viewedAt:desc"
        | withHeader "Accept" "application/json"
        | withHeader "X-Plex-Token" $apiKey
        | getResponse }}

      {{ if $historyCall.JSON.Exists "MediaContainer" }}
        {{ $history = $historyCall.JSON.Array "MediaContainer.Metadata" }}
      {{ else }}
        {{ template "errorMsg" (concat "Could not fetch " $mediaServer " API.") }}
      {{ end }}

      {{ $usersRequestURL = concat $baseURL "/accounts" }}
      {{ $usersCall = newRequest $usersRequestURL
        | withHeader "Accept" "application/json"
        | withHeader "X-Plex-Token" $apiKey
        | getResponse }}
      {{ $users = $usersCall.JSON.Array "MediaContainer.Account" }}

    {{ else if eq $mediaServer "tautulli" }}
      {{ $historyRequestURL = concat $baseURL "/api/v2" }}
      {{ $historyCall = newRequest $historyRequestURL
        | withParameter "apikey" $apiKey
        | withParameter "cmd" "get_history"
        | withParameter "length" $historyLength
        | withParameter "media_type" $mediaTypes
        | withHeader "Accept" "application/json"
        | getResponse }}

      {{ if eq $historyCall.Response.StatusCode 200 }}
        {{ $history = $historyCall.JSON.Array "response.data.data" }}
      {{ else }}
        {{ template "errorMsg" (concat "Could not fetch " $mediaServer " API.") }}
      {{ end }}

    {{ else if or (eq $mediaServer "jellyfin") (eq $mediaServer "emby") }}
      {{ $usersRequestURL = concat $baseURL "/Users" }}
      {{ $usersCall = newRequest $usersRequestURL
        | withParameter "api_key" $apiKey
        | withHeader "Accept" "application/json"
        | getResponse }}

      {{ $usersList := $usersCall.JSON.Array "" }}
      {{ range $i, $user := $usersList }}
        {{ if eq ($user.String "Name") $userName }}
          {{ $userID = $user.String "Id" }}
          {{ break }}
        {{ end }}
      {{ end }}
      {{ if eq $userID "" }}
        {{ template "errorMsg" (concat "User '" $userName "' not found.") }}
      {{ end }}

      {{ $historyRequestURL = concat $baseURL "/Users/" $userID "/Items" }}
      {{ $historyCall = newRequest $historyRequestURL
        | withParameter "api_key" $apiKey
        | withParameter "Limit" $historyLength
        | withParameter "IncludeItemTypes" $mediaTypes
        | withParameter "Recursive" "true"
        | withParameter "isPlayed" "true"
        | withParameter "sortBy" "DatePlayed"
        | withParameter "sortOrder" "Descending"
        | withParameter "Fields" "UserDataLastPlayedDate"
        | withHeader "Accept" "application/json"
        | getResponse }}

      {{ $history = $historyCall.JSON.Array "Items" }}
    {{ end }}

    {{ if and (eq $historyCall.Response.StatusCode 200) (eq (len $history) 0) }}
      <p>Nothing has been played. Start streaming something!</p>
    {{ else }}
      <div class="carousel-container show-right-cutoff">
        <div class="cards-horizontal carousel-items-container">
          {{ range $n, $item := $history }}
            {{ $mediaType := "" }}
            {{ $isMovie := false }}
            {{ $isShows := false }}
            {{ $isMusic := false }}
            {{ $title := "" }}
            {{ $showTitle := "" }}
            {{ $showSeason := "" }}
            {{ $showEpisode := "" }}
            {{ $artist := "" }}
            {{ $albumTitle := "" }}
            {{ $thumbURL := "" }}
            {{ $playedAt := "" }}

            {{ if eq $mediaServer "plex" }}
              {{ $userID = $item.Int "accountID" }}
              {{ range $n, $u := $users }}
                {{ if eq $userID ($u.Int "id") }}
                  {{ $userName = $u.String "name" }}
                  {{ break }}
                {{ end }}
              {{ end }}

              {{ $mediaType = $item.String "type" }}
              {{ $isMovie = eq $mediaType "movie" }}
              {{ $isShows = eq $mediaType "episode" }}
              {{ $isMusic = eq $mediaType "track" }}

              {{ $title = $item.String "title" }}
              {{ if $isShows }}
                {{ $showTitle = $item.String "grandparentTitle" }}
                {{ $showSeason = $item.String "parentIndex" }}
                {{ $showEpisode = $item.String "index" }}
              {{ else if $isMusic }}
                {{ $artist = $item.String "grandparentTitle" }}
                {{ $albumTitle = $item.String "parentTitle" }}
              {{ end }}

              {{ $thumbID := $item.String "thumb" }}
              {{ if or $isShows $isMusic}}
                {{ $thumbID = $item.String "parentThumb" }}
              {{ end }}
              {{ $thumbURL = concat $baseURL $thumbID "?X-Plex-Token=" $apiKey }}

              {{ $time := $item.String "viewedAt" }}
              {{ if $timeAbsolute }}
                {{ $playedAt = $time | parseLocalTime "unix" | formatTime $timeFormat }}
              {{ else }}
                {{ $playedAt = $time | parseRelativeTime "unix" }}
              {{ end }}

            {{ else if eq $mediaServer "tautulli" }}
              {{ $userName = $item.String "user" }}
              {{ $mediaType = $item.String "media_type" }}
              {{ $isMovie = eq $mediaType "movie" }}
              {{ $isShows = eq $mediaType "episode" }}
              {{ $isMusic = eq $mediaType "track" }}

              {{ $title = $item.String "title" }}
              {{ if $isShows }}
                {{ $showTitle = $item.String "grandparent_title" }}
                {{ $showSeason = $item.String "parent_media_index" }}
                {{ $showEpisode = $item.String "media_index" }}
              {{ else if $isMusic }}
                {{ $artist = $item.String "grandparent_title" }}
                {{ $albumTitle = $item.String "parent_title" }}
              {{ end }}

              {{ $thumbID := $item.String "thumb" }}
              {{ $thumbURL = concat $baseURL "/api/v2?apikey=" $apiKey "&cmd=pms_image_proxy&img=" $thumbID }}

              {{ $time := $item.String "date" }}
              {{ if $timeAbsolute }}
                {{ $playedAt = $time | parseLocalTime "unix" | formatTime $timeFormat }}
              {{ else }}
                {{ $playedAt = $time | parseRelativeTime "unix" }}
              {{ end }}

            {{ else if or (eq $mediaServer "jellyfin") (eq $mediaServer "emby") }}
              {{ $mediaType = $item.String "Type" }}
              {{ $isMovie = eq $mediaType "Movie" }}
              {{ $isShows = eq $mediaType "Episode" }}
              {{ $isMusic = eq $mediaType "Audio" }}

              {{ $title = $item.String "Name" }}
              {{ if $isShows }}
                {{ $showTitle = $item.String "SeriesName" }}
                {{ $showSeason = $item.String "ParentIndexNumber" }}
                {{ $showEpisode = $item.String "IndexNumber" }}
              {{ else if $isMusic }}
                {{ $artist = $item.String "AlbumArtist" }}
                {{ $albumTitle = $item.String "Album" }}
              {{ end }}

              {{ $thumbID := $item.String "Id" }}
              {{ if $isShows }}
                {{ $thumbID  = $item.String "SeasonId" }}
              {{ end }}
              {{ $thumbURL = concat $baseURL "/Items/" $thumbID "/Images/Primary?api_key=" $apiKey }}

              {{ $time := $item.String "UserData.LastPlayedDate" }}
              {{ if $timeAbsolute }}
                {{ $playedAt = $time | parseLocalTime "rfc3339" | formatTime $timeFormat }}
              {{ else }}
                {{ $playedAt = $time | parseRelativeTime "rfc3339" }}
              {{ end }}
            {{ end }}

            {{ $showInfoFormat := concat "Season " $showSeason " Episode " $showEpisode}}
            {{ if $isCompact }}
              {{ $showInfoFormat = concat "S" $showSeason "E" $showEpisode}}
            {{ end }}

            <div class="card widget-content-frame">
              {{ if $showThumbnail }}
                <img src="{{ $thumbURL | safeURL }}"
                  alt="{{ $title }} thumbnail"
                  loading="lazy"
                  class="media-server-thumbnail shrink-0"
                  style="
                    object-fit: cover;
                    border-radius: var(--border-radius) var(--border-radius) 0 0;
                    {{ if eq $thumbAspectRatio "square" }}
                      aspect-ratio: 1;
                    {{ else if eq $thumbAspectRatio "portrait" }}
                      aspect-ratio: 3/4;
                    {{ else if eq $thumbAspectRatio "landscape" }}
                      aspect-ratio: 4/3;
                    {{ else }}
                      aspect-ratio: initial;
                    {{ end }}
                  "
                />
              {{ end }}

              <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                <ul class="flex flex-column justify-evenly margin-bottom-3 {{if $isSmallColumn}}size-h6{{end}}" style="height: 100%;">
                  {{ if $isCompact }}
                    <ul class="list-horizontal-text flex-nowrap">
                      {{ if $showUser }}
                        <li class="color-primary text-truncate">{{ $userName }}</li>
                      {{ end }}

                      {{ if $timeAbsolute }}
                        <li class="text-truncate">{{ $playedAt }}</li>
                      {{ else }}
                        <li class="shrink-0">
                          <span {{ $playedAt }}></span>
                          {{ if not $showUser }}
                            <span> ago</span>
                          {{ end }}
                        </li>
                      {{ end }}
                    </ul>

                    {{ if $isShows }}
                      <ul class="list-horizontal-text flex-nowrap">
                        <li class="text-truncate">{{ $showInfoFormat }}</li>
                        <li class="text-truncate">{{ $showTitle }}</li>
                      </ul>
                    {{ else if $isMusic }}
                      <ul class="list-horizontal-text flex-nowrap">
                        <li class="text-truncate">{{ $artist }}</li>
                        <li class="text-truncate">{{ $albumTitle }}</li>
                      </ul>
                    {{ end }}

                    <li class="text-truncate">{{ $title }}</li>
                  {{ else }}
                    {{ if $showUser }}
                      <li class="color-primary text-truncate">{{ $userName }}</li>
                    {{ end }}

                    {{ if $timeAbsolute }}
                      <li class="text-truncate">{{ $playedAt }}</li>
                    {{ else }}
                      <li class="text-truncate">
                        <span {{ $playedAt }}></span>
                        <span> ago</span>
                      </li>
                    {{ end }}

                    {{ if $isShows }}
                      <li class="text-truncate">{{ $showTitle }}</li>
                      <li class="text-truncate">{{ $showInfoFormat }}</li>
                    {{ else if $isMusic }}
                      <li class="text-truncate">{{ $artist }}</li>
                      <li class="text-truncate">{{ $albumTitle }}</li>
                    {{ end }}

                    <li class="text-truncate">{{ $title }}</li>
                  {{ end }}
                </ul>
              </div>
            </div>
          {{ end }}
        </div>
      </div>
    {{ end }}
    {{ end }}

- type: custom-api
  title: Media Server
  cache: 5m
  options:
    media-server: "plex"
    base-url: ${PLEX_URL}
    api-key: ${PLEX_TOKEN}
    small-column: false
    compact: true
    play-state: "indicator"
    show-thumbnail: false
    full-thumbnail: false
    show-paused: false
    show-progress-bar: false
    show-progress-info: true
    time-format: "15:04"
  template: |
    {{ $mediaServer := .Options.StringOr "media-server" "" }}
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}

    {{ define "errorMsg" }}
      <div class="widget-error-header">
        <div class="color-negative size-h3">ERROR</div>
        <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
          <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
        </svg>
      </div>
      <p class="break-all">{{ . }}</p>
    {{ end }}

    {{ if or
      (eq $mediaServer "")
      (eq $baseURL "")
      (eq $apiKey "")
    }}
      {{ template "errorMsg" "Some required options are not set" }}
    {{ else }}

    {{ $isSmallColumn := .Options.BoolOr "small-column" false }}
    {{ $isCompact := .Options.BoolOr "compact" true }}
    {{ $playState := .Options.StringOr "play-state" "indicator" }}
    {{ $showThumbnail := .Options.BoolOr "show-thumbnail" false }}
    {{ $fullThumbnail := .Options.BoolOr "full-thumbnail" false }}
    {{ $showPaused := .Options.BoolOr "show-paused" false }}
    {{ $showProgressBar := .Options.BoolOr "show-progress-bar" false }}
    {{ $showProgressInfo := .Options.BoolOr "show-progress-info" true }}
    {{ $timeFormat := .Options.StringOr "time-format" "15:04" }}

    {{ $userID := "" }}
    {{ $sessionsRequestURL := "" }}
    {{ $sessionsCall := "" }}
    {{ $sessions := "" }}
    {{ $activeSessions := 0 }}

    {{ if eq $mediaServer "plex" }}
      {{ $sessionsRequestURL = concat $baseURL "/status/sessions" }}
      {{ $sessionsCall = newRequest $sessionsRequestURL
        | withHeader "Accept" "application/json"
        | withHeader "X-Plex-Token" $apiKey
        | getResponse }}

      {{ if $sessionsCall.JSON.Exists "MediaContainer" }}
        {{ $sessions = $sessionsCall.JSON.Array "MediaContainer.Metadata" }}
        {{ $activeSessions = len $sessions }}
      {{ else }}
        {{ template "errorMsg" (concat "Could not fetch " $mediaServer " API.") }}
      {{ end }}

    {{ else if eq $mediaServer "tautulli" }}
      {{ $sessionsRequestURL = concat $baseURL "/api/v2" }}
      {{ $sessionsCall = newRequest $sessionsRequestURL
        | withParameter "apikey" $apiKey
        | withParameter "cmd" "get_activity"
        | withHeader "Accept" "application/json"
        | getResponse }}

      {{ if eq $sessionsCall.Response.StatusCode 200 }}
        {{ $sessions = $sessionsCall.JSON.Array "response.data.sessions" }}
        {{ $activeSessions = len $sessions }}
      {{ else }}
        {{ template "errorMsg" (concat "Could not fetch " $mediaServer " API.") }}
      {{ end }}

    {{ else if or (eq $mediaServer "jellyfin") (eq $mediaServer "emby") }}
      {{ $sessionsRequestURL = concat $baseURL "/Sessions" }}
      {{ $sessionsCall = newRequest $sessionsRequestURL
        | withParameter "api_key" $apiKey
        | withParameter "activeWithinSeconds" "30"
        | withHeader "Accept" "application/json"
        | getResponse }}

      {{ if eq $sessionsCall.Response.StatusCode 200 }}
        {{ $sessions = $sessionsCall.JSON.Array "" }}
        {{ if eq $mediaServer "emby" }}
          {{ range $session := $sessions }}
            {{ if $session.Bool "PlayState.CanSeek" }}
              {{ $activeSessions = 1 }}
              {{ break }}
            {{ end }}
          {{ end }}
        {{ else }}
          {{ $activeSessions = len $sessions }}
        {{ end }}
      {{ else }}
        {{ template "errorMsg" (concat "Could not fetch " $mediaServer " API.") }}
      {{ end }}
    {{ end }}

    {{ if and (eq $sessionsCall.Response.StatusCode 200) (eq $activeSessions 0) }}
      <p>Nothing is playing right now.</p>
    {{ else }}

      <style>
        .media-server-session-container--grid {
          display: grid;
          grid-template-columns: repeat(2, 1fr);
        }
        @media (max-width: 768px) {
          .media-server-session-container--grid {
            display: flex;
            flex-direction: column;
          }
        }
        .media-server-progress-container {
          height: 1rem;
          max-width: 32rem;
          border: 1px solid var(--color-text-base);
          border-radius: var(--border-radius);
          overflow: hidden;
        }
        .media-server-progress-bar {
          height: 100%;
          background: var(--color-primary);
          border-radius: 3px;
          transition: width 1s linear;
        }
        @keyframes progress-animation { to { width: 100%; } }
      </style>

      <div class="gap-10 {{ if $isSmallColumn }}flex flex-column{{ else }}media-server-session-container--grid{{ end }}">
      {{ range $i, $session := $sessions }}
        {{ $isClient := true }}
        {{ $isPlaying := false }}
        {{ $state := "playing" }}
        {{ $isMovie := false }}
        {{ $isShows := false }}
        {{ $isMusic := false }}
        {{ $userName := "" }}
        {{ $title := "" }}
        {{ $showTitle := "" }}
        {{ $showSeason := "" }}
        {{ $showEpisode := "" }}
        {{ $artist := "" }}
        {{ $albumTitle := "" }}
        {{ $thumbURL := "" }}
        {{ $now := now | formatTime "15:04:05" | parseLocalTime "15:04:05" }}
        {{ $duration := 0 }}
        {{ $offset := 0 }}
        {{ $remainingSeconds := 0 }}

        {{ if eq $mediaServer "plex" }}
          {{ $isPlaying = eq ($session.String "Player.state") "playing" }}
          {{ if not $isPlaying }}
            {{ $state = "paused"}}
          {{ end }}

          {{ $mediaType := $session.String "type" }}
          {{ $isMovie = eq $mediaType "movie" }}
          {{ $isShows = eq $mediaType "episode" }}
          {{ $isMusic = eq $mediaType "track" }}

          {{ $userName = $session.String "User.title" }}
          {{ $title = $session.String "title" }}
          {{ $showTitle = $session.String "grandparentTitle" }}
          {{ $showSeason = $session.String "parentIndex" }}
          {{ $showEpisode = $session.String "index" }}
          {{ $artist = $session.String "grandparentTitle" }}
          {{ $albumTitle = $session.String "parentTitle" }}

          {{ $thumbID := $session.String "thumb" }}
          {{ if or $isShows $isMusic }}
            {{ $thumbID = $session.String "parentThumb" }}
          {{ end }}
          {{ $thumbURL = concat $baseURL $thumbID "?X-Plex-Token=" $apiKey }}

          {{ $duration = $session.Float "duration" }}
          {{ $offset = $session.Float "viewOffset" }}
          {{ $remainingSeconds = div (sub $duration $offset) 1000 | toInt }}
        {{ else if eq $mediaServer "tautulli" }}
          {{ $isPlaying = eq ($session.String "state") "playing" }}
          {{ if not $isPlaying }}
            {{ $state = "paused"}}
          {{ end }}

          {{ $mediaType := $session.String "media_type" }}
          {{ $isMovie = eq $mediaType "movie" }}
          {{ $isShows = eq $mediaType "episode" }}
          {{ $isMusic = eq $mediaType "track" }}

          {{ $userName = $session.String "user" }}
          {{ $title = $session.String "title" }}
          {{ $showTitle = $session.String "grandparent_title" }}
          {{ $showSeason = $session.String "parent_media_index" }}
          {{ $showEpisode = $session.String "media_index" }}
          {{ $artist = $session.String "grandparent_title" }}
          {{ $albumTitle = $session.String "parent_title" }}

          {{ $thumbID := $session.String "thumb" }}
          {{ if or $isShows $isMusic }}
            {{ $thumbID = $session.String "parent_thumb" }}
          {{ end }}
          {{ $thumbURL = concat $baseURL "/api/v2?apikey=" $apiKey "&cmd=pms_image_proxy&img=" $thumbID }}

          {{ $duration = $session.Float "duration" }}
          {{ $offset = $session.Float "view_offset" }}
          {{ $remainingSeconds = div (sub $duration $offset) 1000 | toInt }}
        {{ else if or (eq $mediaServer "jellyfin") (eq $mediaServer "emby") }}
          {{ if eq $mediaServer "emby" }}
            {{ $isClient = $session.Bool "PlayState.CanSeek" }}
          {{ end }}
          {{ $isPlaying = and ($session.Exists "NowPlayingItem") (not ($session.Bool "PlayState.IsPaused")) }}
          {{ if not $isPlaying }}
            {{ $state = "paused"}}
          {{ end }}

          {{ $mediaType := $session.String "NowPlayingItem.Type" }}
          {{ $isMovie = eq $mediaType "Movie" }}
          {{ $isShows = eq $mediaType "Episode" }}
          {{ $isMusic = eq $mediaType "Audio" }}

          {{ $userName = $session.String "UserName" }}
          {{ $title = $session.String "NowPlayingItem.Name" }}
          {{ $showTitle = $session.String "NowPlayingItem.SeriesName" }}
          {{ $showSeason = $session.String "NowPlayingItem.ParentIndexNumber" }}
          {{ $showEpisode = $session.String "NowPlayingItem.IndexNumber" }}
          {{ $artist = $session.String "NowPlayingItem.AlbumArtist" }}
          {{ $albumTitle = $session.String "NowPlayingItem.Album" }}

          {{ $thumbID := $session.String "NowPlayingItem.Id" }}
          {{ if $isShows }}
            {{ $thumbID = $session.String "NowPlayingItem.ParentId" }}
          {{ end }}
          {{ $thumbURL = concat $baseURL "/Items/" $thumbID "/Images/Primary?api_key=" $apiKey }}

          {{ $duration = $session.Float "NowPlayingItem.RunTimeTicks" }}
          {{ $offset = $session.Float "PlayState.PositionTicks" }}
          {{ $remainingSeconds = div (sub $duration $offset) 10000000 | toInt }}
        {{ end }}

        {{ $progress := mul 100 (div $offset $duration) | toInt }}
        {{ $endTime := $now.Add (duration (printf "%ds" $remainingSeconds)) | formatTime $timeFormat }}

        {{ $showInfoFormat := concat "Season " $showSeason " Episode " $showEpisode}}
        {{ if $isCompact }}
          {{ $showInfoFormat = concat "S" $showSeason "E" $showEpisode}}
        {{ end }}

        {{ if and $isClient (or $isPlaying $showPaused) }}
        <div class="card gap-5">
          <div class="flex items-center gap-10 size-h3">
            <span class="color-primary">{{ $userName }}</span>
            {{ if eq $playState "text" }}
              <span {{ if $isPlaying }}class="color-primary"{{ end }}>
                [{{ $state }}]
              </span>
            {{ else if eq $playState "indicator" }}
              <style>
                .media-server-indicator {
                  height: .7rem;
                  width: .7rem;
                  border-radius: 100%;
                  {{ if $isPlaying }}
                    animation: pulse 5s infinite;
                    background: var(--color-primary);
                  {{ else }}
                    background: var(--color-text-base-muted);
                  {{ end }}
                }
                @keyframes pulse {
                  0% { box-shadow: 0 0 0 0 var(--color-text-base); }
                  40% { box-shadow: 0 0 0 4px transparent; }
                  100% { box-shadow: 0 0 0 4px transparent; }
                }
              </style>
              <div class="media-server-indicator"></div>
            {{ end }}
          </div>

          <hr class="margin-bottom-5" />

          <div class="flex items-center gap-10" style="align-items: stretch;">
            {{ if $showThumbnail }}
              <img src="{{ $thumbURL | safeURL }}"
                alt="{{ $title }} thumbnail"
                class="shrink-0"
                loading="lazy"
                style="
                  max-width: 7.5rem;
                  border: 2px solid var(--color-primary);
                  border-radius: var(--border-radius);
                  object-fit: cover;
                  {{ if and $isCompact (not $fullThumbnail) }} aspect-ratio: 1; {{ end }} "
              />
            {{ end }}
            <ul class="flex flex-column grow justify-evenly" style="width: 0;">
              {{ if $isCompact }}
                {{ if $isShows }}
                  <ul class="list-horizontal-text flex-nowrap">
                    <li class="shrink-0">{{ concat "S" $showSeason "E" $showEpisode }}</li>
                    <li class="text-truncate">{{ $showTitle }}</li>
                  </ul>
                {{ else if $isMusic }}
                  <ul class="list-horizontal-text flex-nowrap">
                    <li class="shrink-0">{{ $artist }}</li>
                    <li class="text-truncate">{{ $albumTitle }}</li>
                  </ul>
                {{ end }}
                <li class="text-truncate">{{ $title }}</li>
              {{ else }}
                {{ if $isShows }}
                  <li>{{ $showTitle }}</li>
                  <li>{{ concat "S" $showSeason "E" $showEpisode }}</li>
                {{ else if $isMusic }}
                  <li>{{ $artist }}</li>
                  <li>{{ $albumTitle }}</li>
                {{ end }}
                <li>{{ $title }}</li>
              {{ end }}

              <li>
                {{ if and $isPlaying $showProgressBar }}
                  <div class="flex gap-10 items-center">
                    <div class="media-server-progress-container grow">
                      <div
                        class ="media-server-progress-bar"
                        data-progress="{{ $progress }}"
                        data-remaining="{{ $remainingSeconds }}"
                        style="
                          width: {{ $progress }}%;
                          animation: progress-animation {{ $remainingSeconds }}s linear forwards;"
                      >
                      </div>
                    </div>
                    {{ if $showProgressInfo }}
                      <p>
                        {{ if and (not $isCompact) (not $isSmallColumn) }}
                          ends at 
                        {{ end }}
                        {{ $endTime }}
                      </p>
                    {{ end }}
                  </div>
                {{ end }}
              </li>
            </ul>
          </div>
        </div>
        {{ end }}
      {{ end }}
    </div>
    {{ end }}
    {{ end }}

- type: custom-api
  title: Upcoming # change to your liking
  frameless: true
  cache: 1h
  options:
    base-url: ${MEDIATRACKER_URL}       # URL pointing to your MediaTracker
    api-key: ${MEDIATRACKER_API_KEY}    # can be retrieved in Account Name -> Application tokens
    media-type: tv                      # tv, movie or video_game
    only-on-watchlist: "false"          # "true" or "false"
    items: 10                           # integer number
  template: |
    {{ $baseURL := .Options.StringOr "base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}
    {{ $mediaType := .Options.StringOr "media-type" "tv" }}
    {{ $onlyOnWatchlist := .Options.StringOr "only-on-watchlist" "false" }}
    {{ $numberOfItems := .Options.IntOr "items" 10 }}
    {{ $orderBy := "releaseDate" }}
    {{ $sortOrder := "asc" }}
    {{ $videoGameReleaseDate := "TBA" }}

    {{ if or (eq $baseURL "") (eq $apiKey "") }}
        <div class="widget-content-frame" style="flex=0 0 25vh; display:flex">
            <div class="grow padding-inline-widget margin-top-10 margin-bottom-10 color-negative">
                MediaTracker base-url or API token not set.
            </div>
        </div>
    {{ else }}
      {{ if eq $mediaType "tv" }}
        {{ $orderBy = "nextAiring" }}
      {{ end }}
      {{ $requestURL := concat $baseURL "/api/items?mediaType=" $mediaType "&orderBy=" $orderBy "&sortOrder=" $sortOrder "&onlyOnWatchlist" $onlyOnWatchlist "&token=" $apiKey}}
      {{ if or (eq $mediaType "video_game") (eq $mediaType "movie") }}
        {{ $requestURL = concat $requestURL "&onlyWithNextAiring=true" }}
      {{ end }}

      {{ $items := newRequest $requestURL | getResponse }}
      {{ if eq $items.Response.StatusCode 200 }}
        {{ $arr := $items.JSON.Array "" }}
        {{ $len := len $arr }}
        {{ $shown := 0 }}

        {{ if gt (len $arr) 0 }}
            <div class="cards-horizontal carousel-items-container">
              {{ range $i, $_ := $arr }}
                {{ if and (.Exists "nextAiring") (ne (.String "nextAiring") "") (lt $shown $numberOfItems) }}
                     {{ $el := index $arr $i }}

                     <a class="card widget-content-frame"
                        href="{{ $baseURL }}/#/details/{{ $el.Int "id" }}"
                        style="
                            flex: 0 0 25vh; 
                            min-width: 170px;
                            min-heght: 150px; 
                            display:flex; 
                            flex-direction:column; 
                            box-sizing:border-box;
                            text-decoration:none; 
                            color:inherit;"
                     >
                     <div style="position: relative;">
                        {{ if and ($el.Exists "posterSmall") (ne ($el.String "posterSmall") "") }}
                            <img src="{{ $baseURL }}{{ $el.String "posterSmall" }}&token={{ $apiKey }}"
                                alt="{{ $el.String "title" }}"
                                loading="lazy"
                                class="media-server-thumbnail shrink-0 loaded finished-transition"
                                style="
                                    width:100%; 
                                    display:block; 
                                    border-radius:var(--border-radius) var(--border-radius) 0 0; 
                                    object-fit:cover;" 
                            />
                         {{ else }}
                            <div style="width:100%; background:#222; display:flex; align-items:center; justify-content:center; color:#ddd; aspect-ratio:2/3;">
                              No image
                            </div>
                         {{ end }}
                     </div>
                     <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                          <ul class="flex flex-column justify-evenly margin-bottom-3" style="height:100%; gap: 4px;">
                            {{ if eq $mediaType "tv" }}
                                <ul class="list-horizontal-text flex-nowrap" style="padding:0; margin:0;">
                                <li class="color-primary shrink-0"> S{{ printf "%02d" ($el.Int "upcomingEpisode.seasonNumber") }}E{{ printf "%02d" ($el.Int "upcomingEpisode.episodeNumber") }}</li>
                                <li class="text-truncate">{{ $el.String "upcomingEpisode.title" }}</li>
                                </ul>
                            {{ end }}
                            <li class="text-truncate color-primary" style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="{{ $el.String "title" }}">
                              {{ $el.String "title" }}
                            </li>
                            {{ if eq $mediaType "video_game" }}
                                <li style="font-size:0.85em; opacity:0.7; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">                                    
                                    {{ $videoGameReleaseDate = $el.String "releaseDate" | parseTime "RFC3339" }}
                                    {{ if eq ($videoGameReleaseDate | formatTime "02-01") "31-12" }}
                                        {{ $videoGameReleaseDate | formatTime "2006" }}
                                    {{ else }}
                                        {{ $videoGameReleaseDate | formatTime "Jan 02, 2006" }}
                                    {{ end }}
                                </li>
                            {{ else}}
                                <li style="font-size:0.85em; opacity:0.7; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                                    {{ $el.String "nextAiring" | parseTime "2006-01-02" | formatTime "Jan 02, 2006" }}
                                </li>
                            {{ end }}
                          </ul>
                       </div>
                     </a>
                {{ $shown = add $shown 1 }}
                {{ end }}
              {{ end }}
            </div>
        {{ else }}
            <div class="widget-content-frame" style="flex=0 0 25vh; display:flex">
              <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                No upcoming entries on the watchlist.
              </div>
            </div>
        {{ end }}
      {{ else }}
         <div class="widget-content-frame" style="flex=0 0 25vh; display:flex">
              <div class="grow padding-inline-widget margin-top-10 margin-bottom-10">
                Failed to fetch items (status {{ $items.Response.StatusCode }})
              </div>
         </div>
      {{ end }}
    {{ end }}

- type: custom-api
  title: MLB Today
  url: "https://statsapi.mlb.com/api/v1/schedule/games/?sportId=1&hydrate=linescore(runners),team"
  cache: 15s
  template: |
    {{ $dates := .JSON.Array "dates" }}
    {{ if eq (len $dates) 0 }}
      <div style="padding:8px;text-align:center;">No games scheduled today.</div>
    {{ else }}
      {{ $games := (index $dates 0).Array "games" }}
      {{ $wid := printf "mlb-%d" now.UnixNano }}
      <div id="{{ $wid }}" style="position:relative;padding-bottom:{{ if gt (len $games) 6 }}25px{{ else }}0px{{ end }};">
        <input type="checkbox" id="{{ $wid }}-cb" style="display:none"/>
        <ul class="visible" style="list-style:none;padding:0;margin:0;">
          {{ $count := 0 }}
          {{ range $i, $g := $games }}
            {{ $abs := $g.String "status.abstractGameState" }}
            {{ if and (lt $count 6) (eq $abs "Live") }}
              {{ template "row" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $games }}
            {{ $abs := $g.String "status.abstractGameState" }}
            {{ if and (lt $count 6) (eq $abs "Preview") }}
              {{ template "row" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $games }}
            {{ $abs := $g.String "status.abstractGameState" }}
            {{ if and (lt $count 6) (ne $abs "Live") (ne $abs "Preview") }}
              {{ template "row" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
        </ul>
        <ul class="all" style="list-style:none;padding:0;margin:0;display:none">
          {{ range $i, $g := $games }}
            {{ if eq ($g.String "status.abstractGameState") "Live" }}
              {{ template "row" $g }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $games }}
            {{ if eq ($g.String "status.abstractGameState") "Preview" }}
              {{ template "row" $g }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $games }}
            {{ $abs := $g.String "status.abstractGameState" }}
            {{ if and (ne $abs "Live") (ne $abs "Preview") }}
              {{ template "row" $g }}
            {{ end }}
          {{ end }}
        </ul>
        {{ if gt (len $games) 6 }}
          <label for="{{ $wid }}-cb" style="position:absolute;bottom:0px;right:0;cursor:pointer;color:var(--glance-accent-color);font-size:16px;padding:5px;">
            <span style="display:inline-block;transition:transform .2s;font-size:20px;">&#9662;</span>
          </label>
        {{ end }}
        <style>
          #{{ $wid }}-cb:not(:checked) ~ .all  { display:none!important }
          #{{ $wid }}-cb:checked   ~ .visible { display:none!important }
          #{{ $wid }}-cb:checked   ~ .all     { display:block!important }
          #{{ $wid }}-cb:checked   ~ label span { transform:rotate(180deg)!important }
        </style>
      </div>
    {{ end }}
    {{ define "row" }}
      {{/* --- AWAY SIDE --- */}}
      {{ $awayAbr  := .String "teams.away.team.abbreviation" }}
      {{ $awayCode := .String "teams.away.team.fileCode" }}
      {{ $awayRecW := .Int    "teams.away.leagueRecord.wins" }}
      {{ $awayRecL := .Int    "teams.away.leagueRecord.losses" }}
      {{ $awaySc   := .Int    "teams.away.score" }}
      {{ $awayId   := .Int    "teams.away.team.id" }}
      {{/* --- HOME SIDE --- */}}
      {{ $homeAbr  := .String "teams.home.team.abbreviation" }}
      {{ $homeCode := .String "teams.home.team.fileCode" }}
      {{ $homeRecW := .Int    "teams.home.leagueRecord.wins" }}
      {{ $homeRecL := .Int    "teams.home.leagueRecord.losses" }}
      {{ $homeSc   := .Int    "teams.home.score" }}
      {{ $homeId   := .Int    "teams.home.team.id" }}
      {{/* status & linescore */}}
      {{ $abs             := .String "status.abstractGameState" }}
      {{ $detailed        := .String "status.detailedState" }}
      {{ $live            := eq $abs "Live" }}
      {{ $inningSt        := .String "linescore.inningState" }}
      {{ $inningN         := .Int    "linescore.currentInning" }}
      {{ $seriesDesc      := .String "seriesDescription" }}
      {{ $seriesLabel     := .String "description" }}
      {{ $seriesGame      := .Int    "seriesGameNumber" }}
      {{ $isRegularSeries := or (eq $seriesDesc "Regular Season") (eq $seriesDesc "Regular Season 1") (eq $seriesDesc "Regular Season 2") (eq $seriesDesc "Regular Season 3") (eq $seriesDesc "Regular Season 4") }}
      {{ $isPlayoffSeries := and (ne $seriesDesc "") (not $isRegularSeries) }}
      {{/* offense & base occupancy */}}
      {{ $r1        := .Exists "linescore.offense.first" }}
      {{ $r2        := .Exists "linescore.offense.second" }}
      {{ $r3        := .Exists "linescore.offense.third" }}
      {{ $offTeamId := .Int    "linescore.offense.team.id" }}
