              {{ if lt $i 9 }}  Inning {{ add $i 1 }}: {{ $inning.Int "away.runs" }}{{ else }}  Inning {{ add $i 1 }}: {{ $inning.Int "away.runs" }}{{ end }}
            {{ end }}&#10;{{ $homeAbr }} Box:{{ range $i, $inning := (.Array "linescore.innings") }}
              {{ if lt $i 9 }}  Inning {{ add $i 1 }}: {{ $inning.Int "home.runs" }}{{ else }}  Inning {{ add $i 1 }}: {{ $inning.Int "home.runs" }}{{ end }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {{ end }}"
          {{ end }}>
        <div style="display:flex;align-items:center;gap:12px;">
          <span style="display:flex;align-items:center;width:80px;white-space:nowrap;">
            <img src='{{ if eq $awayCode "ana" }}https://a.espncdn.com/combiner/i?img=/i/teamlogos/mlb/500/laa.png&h=24&w=24{{ else }}https://a.espncdn.com/combiner/i?img=/i/teamlogos/mlb/500/{{ $awayCode }}.png&h=24&w=24{{ end }}'
                alt='{{ $awayAbr }}'
                style='width:24px;height:24px;margin-right:4px;'/>
            <span style="display:flex;flex-direction:column;margin-right:4px;">
              <span style="font-weight:bold;">{{ $awayAbr }}</span>
              <span style="font-size:0.7em;color:var(--glance-muted-text)">
                ({{ printf "%d-%d" $awayRecW $awayRecL }})
              </span>
            </span>
            {{ if ne $abs "Preview" }}
              <span style="margin-left:auto;font-size:1em;font-weight:700;font-variant-numeric:tabular-nums;color:var(--glance-heading-text);">{{ $awaySc }}</span>
            {{ end }}
            {{ if and $live (eq $offTeamId $awayId) }}
              <svg width="20" height="20" viewBox="0 0 24 24" style="margin-left:4px;flex-shrink:0;">
                <rect x="6" y="6" width="12" height="12" fill="#808080" transform="rotate(45 12 12)"/>
                {{ if $r1 }}<circle cx="17" cy="12" r="2.5" fill="white"/>{{ end }}
                {{ if $r2 }}<circle cx="12" cy="7" r="2.5" fill="white"/>{{ end }}
                {{ if $r3 }}<circle cx="7" cy="12" r="2.5" fill="white"/>{{ end }}
              </svg>
            {{ end }}
          </span>
        <span style="text-align:center;width:90px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:1px;font-size:0.9em;white-space:nowrap;">
          {{ if eq $abs "Preview" }}
            {{ $gameTime := (.String "gameDate" | parseTime "2006-01-02T15:04:05Z").In now.Location }}
            <span style="color:var(--glance-muted-text)">{{ printf "%02d:%02d" $gameTime.Hour $gameTime.Minute }}</span>
          {{ else if $live }}
            <span style="font-weight:500;">{{ printf "%s %d" $inningSt $inningN }}</span>
          {{ else if or (eq $detailed "Game Over") (eq $detailed "Final") }}
            <span style="font-size:1.1em;font-weight:500;">Final</span>
          {{ else }}
            <span>{{ $detailed }}</span>
          {{ end }}
          {{ if $isPlayoffSeries }}
            <span style="font-size:0.9em;color:var(--glance-accent-color);margin-top:0;">
              {{ if $seriesLabel }}
                {{ $seriesLabel }}
              {{ else if gt $seriesGame 0 }}
                {{ printf "%s (Game %d)" $seriesDesc $seriesGame }}
              {{ else }}
                {{ $seriesDesc }}
              {{ end }}
            </span>
          {{ end }}
        </span>
          <span style="display:flex;align-items:center;width:80px;justify-content:flex-end;white-space:nowrap;">
            {{ if and $live (eq $offTeamId $homeId) }}
              <svg width="20" height="20" viewBox="0 0 24 24" style="margin-right:4px;flex-shrink:0;">
                <rect x="6" y="6" width="12" height="12" fill="#808080" transform="rotate(45 12 12)"/>
                {{ if $r1 }}<circle cx="17" cy="12" r="2.5" fill="white"/>{{ end }}
                {{ if $r2 }}<circle cx="12" cy="7" r="2.5" fill="white"/>{{ end }}
                {{ if $r3 }}<circle cx="7" cy="12" r="2.5" fill="white"/>{{ end }}
              </svg>
            {{ end }}
            {{ if ne $abs "Preview" }}
              <span style="margin-left:auto;font-size:1em;font-weight:700;font-variant-numeric:tabular-nums;color:var(--glance-heading-text);">{{ $homeSc }}</span>
            {{ end }}
            <span style="display:flex;flex-direction:column;margin-left:4px;text-align:right;">
              <span style="font-weight:bold;">{{ $homeAbr }}</span>
              <span style="font-size:0.7em;color:var(--glance-muted-text)">
                ({{ printf "%d-%d" $homeRecW $homeRecL }})
              </span>
            </span>
            <img src='{{ if eq $homeCode "ana" }}https://a.espncdn.com/combiner/i?img=/i/teamlogos/mlb/500/laa.png&h=24&w=24{{ else }}https://a.espncdn.com/combiner/i?img=/i/teamlogos/mlb/500/{{ $homeCode }}.png&h=24&w=24{{ end }}'
                alt='{{ $homeAbr }}'
                style='width:24px;height:24px;margin-left:4px;'/>
          </span>
        </div>
      </li>
    {{ end }}

- type: custom-api
  title: NBA Today
  url: "https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard"
  cache: 15s
  template: |
    {{ $events := .JSON.Array "events" }}
    {{ if eq (len $events) 0 }}
      <div>No games scheduled today.</div>
    {{ else }}
      {{ $wid := printf "nba-%d" now.UnixNano }}
      <div id="{{ $wid }}" style="position:relative;padding-bottom:{{ if gt (len $events) 6 }}25px{{ else }}0px{{ end }};">
        <input type="checkbox" id="{{ $wid }}-cb" style="display:none"/>
        <ul class="visible" style="list-style:none;padding:0;margin:0;">
          {{ $count := 0 }}
          {{ range $i, $g := $events }}
            {{ $phase := $g.String "competitions.0.status.type.state" }}
            {{ if and (lt $count 6) (eq $phase "in") }}
              {{ template "nba-game" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $events }}
            {{ $phase := $g.String "competitions.0.status.type.state" }}
            {{ if and (lt $count 6) (eq $phase "pre") }}
              {{ template "nba-game" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $events }}
            {{ $phase := $g.String "competitions.0.status.type.state" }}
            {{ if and (lt $count 6) (and (ne $phase "in") (ne $phase "pre")) }}
              {{ template "nba-game" $g }}
              {{ $count = add $count 1 }}
            {{ end }}
          {{ end }}
        </ul>

        <ul class="all" style="list-style:none;padding:0;margin:0;display:none">
          {{ range $i, $g := $events }}
            {{ if eq ($g.String "competitions.0.status.type.state") "in" }}
              {{ template "nba-game" $g }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $events }}
            {{ if eq ($g.String "competitions.0.status.type.state") "pre" }}
              {{ template "nba-game" $g }}
            {{ end }}
          {{ end }}
          {{ range $i, $g := $events }}
            {{ $phase := $g.String "competitions.0.status.type.state" }}
            {{ if and (ne $phase "in") (ne $phase "pre") }}
              {{ template "nba-game" $g }}
            {{ end }}
          {{ end }}
        </ul>

        {{ if gt (len $events) 6 }}
          <label for="{{ $wid }}-cb" style="position:absolute;bottom:0px;right:0;cursor:pointer;color:var(--glance-accent-color);font-size:16px;padding:5px;">
            <span style="display:inline-block;transition:transform .2s;font-size:20px;">&#9662;</span>
          </label>
        {{ end }}
        <style>
          #{{ $wid }} .nba-row:last-child { margin-bottom:0; }
          #{{ $wid }}-cb:not(:checked) ~ .all { display:none!important }
          #{{ $wid }}-cb:checked ~ .visible { display:none!important }
          #{{ $wid }}-cb:checked ~ .all { display:block!important }
          #{{ $wid }}-cb:checked ~ label span { transform:rotate(180deg)!important }
        </style>
      </div>
    {{ end }}

    {{ define "nba-game" }}
      {{ $state := .String "competitions.0.status.type.name" }}
      {{ $home := index (.Array "competitions.0.competitors") 0 }}
      {{ $away := index (.Array "competitions.0.competitors") 1 }}
      {{ $awayRecords := $away.Array "records" }}
      {{ $homeRecords := $home.Array "records" }}
      {{ $awayRec := "" }}
      {{ if gt (len $awayRecords) 0 }}{{ $awayRec = (index $awayRecords 0).String "summary" }}{{ end }}
      {{ $homeRec := "" }}
      {{ if gt (len $homeRecords) 0 }}{{ $homeRec = (index $homeRecords 0).String "summary" }}{{ end }}
      {{ $awayLogo := $away.String "team.logo" }}
      {{ $homeLogo := $home.String "team.logo" }}
      {{ $fallbackLogo := "https://a.espncdn.com/combiner/i?img=/i/teamlogos/leagues/500/nba.png" }}
      {{ $statusText := .String "competitions.0.status.type.shortDetail" }}
      {{ $statusFont := "0.7em" }}
      {{ if eq $state "STATUS_IN_PROGRESS" }}{{ $statusFont = "0.8em" }}{{ end }}
      {{ if eq $state "STATUS_SCHEDULED" }}{{ $statusFont = "0.8em" }}{{ end }}
      {{ if eq $statusText "Final" }}{{ $statusFont = "0.8em" }}{{ end }}
      {{ $awayAbbr := $away.String "team.abbreviation" }}
      {{ if or (eq (len $awayAbbr) 0) (gt (len $awayAbbr) 3) }}
        {{ $awayAbbr = printf "%.3s" ($away.String "team.displayName") }}
      {{ end }}
      {{ $homeAbbr := $home.String "team.abbreviation" }}
      {{ if or (eq (len $homeAbbr) 0) (gt (len $homeAbbr) 3) }}
        {{ $homeAbbr = printf "%.3s" ($home.String "team.displayName") }}
      {{ end }}
      <li class="nba-row" style="display:flex;flex-direction:column;gap:4px;padding:10px 0;border-bottom:1px solid var(--glance-divider);" {{ if ne $state "STATUS_SCHEDULED" }}title="{{ $awayAbbr }} Box:{{ range $j,$ls := $away.Array "linescores" }}{{ if eq $j 0 }} Q1: {{ else if eq $j 1 }} Q2: {{ else if eq $j 2 }} Q3: {{ else if eq $j 3 }} Q4: {{ else }} OT: {{ end }}{{ $ls.String "value" }}{{ end }}&#10;{{ $homeAbbr }} Box:{{ range $j,$ls := $home.Array "linescores" }}{{ if eq $j 0 }} Q1: {{ else if eq $j 1 }} Q2: {{ else if eq $j 2 }} Q3: {{ else if eq $j 3 }} Q4: {{ else }} OT: {{ end }}{{ $ls.String "value" }}{{ end }}"{{ end }}>
        <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0;">
          <div style="display:flex;align-items:flex-start;gap:6px;min-width:0;">
            {{ if $awayLogo }}
              <img src="{{ $awayLogo }}" alt="{{ $awayAbbr }}" style="width:34px;height:34px;border-radius:50%;flex-shrink:0;"/>
            {{ else }}
              <img src="{{ $fallbackLogo }}" alt="{{ $awayAbbr }}" style="width:34px;height:34px;border-radius:50%;flex-shrink:0;"/>
            {{ end }}
            <div style="display:flex;flex-direction:column;gap:2px;min-width:0;">
              <div style="display:flex;align-items:baseline;gap:6px;min-width:0;">
                <span style="font-weight:700;letter-spacing:0.08em;white-space:nowrap;text-transform:uppercase;">{{ $awayAbbr }}</span>
              </div>
              {{ if $awayRec }}<span style="font-size:0.7em;color:var(--glance-muted-text);white-space:nowrap;">({{ $awayRec }})</span>{{ end }}
            </div>
          </div>
        <div style="flex:1;display:flex;align-items:center;justify-content:center;gap:10px;white-space:nowrap;letter-spacing:0.05em;min-width:0;">
          {{ if ne $state "STATUS_SCHEDULED" }}
            <span style="font-size:1em;font-weight:700;font-variant-numeric:tabular-nums;color:var(--glance-heading-text);">{{ $away.String "score" }}</span>
          {{ end }}
          <span style="font-size:{{ $statusFont }};font-weight:500;">
            {{ if eq $state "STATUS_IN_PROGRESS" }}
              {{ $period := .String "competitions.0.status.period" }}
              {{ if eq $period "1" }}1st{{ else if eq $period "2" }}2nd{{ else if eq $period "3" }}3rd{{ else if eq $period "4" }}4th{{ else }}OT{{ end }} {{ .String "competitions.0.status.displayClock" }}
            {{ else if eq $state "STATUS_SCHEDULED" }}
              {{ $tipStr := .String "competitions.0.date" }}
              {{ if $tipStr }}
                {{ $tip := ($tipStr | parseTime "2006-01-02T15:04Z") }}
                {{ $local := $tip.In now.Location }}
                {{ $hour := $local.Hour }}
                {{ $minute := $local.Minute }}
                {{ $ampm := "AM" }}
                {{ if ge $hour 12 }}{{ $ampm = "PM" }}{{ end }}
                {{ $hour12 := $hour }}
                {{ if eq $hour 0 }}
                  {{ $hour12 = 12 }}
                {{ else if gt $hour 12 }}
                  {{ $hour12 = add $hour -12 }}
                {{ end }}
                {{- printf "%d:%02d %s EDT" $hour12 $minute $ampm -}}
              {{ else }}
                {{ $statusText }}
              {{ end }}
            {{ else }}
              {{ $statusText }}
            {{ end }}
          </span>
          {{ if ne $state "STATUS_SCHEDULED" }}
            <span style="font-size:1em;font-weight:700;font-variant-numeric:tabular-nums;color:var(--glance-heading-text);">{{ $home.String "score" }}</span>
          {{ end }}
          {{ if .Exists "competitions.0.series" }}
            <span style="font-size:0.7em;color:var(--glance-muted-text);">{{ .String "competitions.0.series.summary" }}</span>
          {{ end }}
        </div>
          <div style="display:flex;align-items:flex-start;gap:6px;justify-content:flex-end;min-width:0;">
            <div style="display:flex;flex-direction:column;gap:2px;align-items:flex-end;min-width:0;">
              <div style="display:flex;align-items:baseline;gap:6px;min-width:0;">
                <span style="font-weight:700;letter-spacing:0.08em;white-space:nowrap;text-transform:uppercase;">{{ $homeAbbr }}</span>
              </div>
              {{ if $homeRec }}<span style="font-size:0.7em;color:var(--glance-muted-text);white-space:nowrap;">({{ $homeRec }})</span>{{ end }}
            </div>
            {{ if $homeLogo }}
              <img src="{{ $homeLogo }}" alt="{{ $homeAbbr }}" style="width:34px;height:34px;border-radius:50%;flex-shrink:0;"/>
            {{ else }}
              <img src="{{ $fallbackLogo }}" alt="{{ $homeAbbr }}" style="width:34px;height:34px;border-radius:50%;flex-shrink:0;"/>
            {{ end }}
          </div>
        </div>
      </li>
    {{ end }}

- type: custom-api
  title: NCAA CFB Scoreboard
  url: "https://site.api.espn.com/apis/site/v2/sports/football/college-football/scoreboard"
  cache: 1m
  template: |
    {{/* NCAA CFB Scoreboard */}}
    {{ $events := .JSON.Array "events" }}

    {{ if eq (len $events) 0 }}
    <div>No games scheduled today.</div>
    {{ else }}
    {{ $wid := printf "cfb-%d" now.UnixNano }}
    <div id="{{ $wid }}" style="position:relative;padding-bottom:{{ if gt (len $events) 6 }}25px{{ else }}0px{{ end }};">
        <input type="checkbox" id="{{ $wid }}-cb" style="display:none"/>
        <ul class="visible" style="list-style:none;padding:0;margin:0;">
        {{ $count := 0 }}

        {{ range $i, $ev := $events }}
            {{ if and (lt $count 6) (gt (len ($ev.Array "competitions.0.competitors")) 1) (eq ($ev.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") }}
            {{ template "cfb-game" $ev }}
            {{ $count = add $count 1 }}
            {{ end }}
        {{ end }}

        {{ range $i, $ev := $events }}
            {{ if and (lt $count 6) (gt (len ($ev.Array "competitions.0.competitors")) 1) (eq ($ev.String "competitions.0.status.type.name") "STATUS_SCHEDULED") }}
            {{ template "cfb-game" $ev }}
            {{ $count = add $count 1 }}
            {{ end }}
        {{ end }}

        {{ range $i, $ev := $events }}
            {{ if and (lt $count 6) (gt (len ($ev.Array "competitions.0.competitors")) 1) (and (ne ($ev.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") (ne ($ev.String "competitions.0.status.type.name") "STATUS_SCHEDULED")) }}
            {{ template "cfb-game" $ev }}
            {{ $count = add $count 1 }}
            {{ end }}
        {{ end }}
        </ul>

        <ul class="all" style="list-style:none;padding:0;margin:0;display:none">
        {{ range $i, $ev := $events }}
            {{ if and (gt (len ($ev.Array "competitions.0.competitors")) 1) (eq ($ev.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") }}
            {{ template "cfb-game" $ev }}
            {{ end }}
        {{ end }}

        {{ range $i, $ev := $events }}
            {{ if and (gt (len ($ev.Array "competitions.0.competitors")) 1) (eq ($ev.String "competitions.0.status.type.name") "STATUS_SCHEDULED") }}
            {{ template "cfb-game" $ev }}
            {{ end }}
        {{ end }}

        {{ range $i, $ev := $events }}
            {{ if and (gt (len ($ev.Array "competitions.0.competitors")) 1) (and (ne ($ev.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") (ne ($ev.String "competitions.0.status.type.name") "STATUS_SCHEDULED")) }}
            {{ template "cfb-game" $ev }}
            {{ end }}
        {{ end }}
        </ul>

        {{ if gt (len $events) 6 }}
        <label for="{{ $wid }}-cb" style="position:absolute;bottom:0px;right:0;cursor:pointer;color:var(--glance-accent-color);font-size:16px;padding:5px;">
            <span style="display:inline-block;transition:transform .2s">▼</span>
        </label>
        {{ end }}
        <style>
        #{{ $wid }}-cb:not(:checked) ~ .all { display:none!important }
        #{{ $wid }}-cb:checked ~ .visible { display:none!important }
        #{{ $wid }}-cb:checked ~ .all { display:block!important }
        #{{ $wid }}-cb:checked ~ label span { transform:rotate(180deg)!important }
        </style>
    </div>
    {{ end }}

    {{ define "cfb-game" }}
    {{ $comp := index (.Array "competitions") 0 }}
    {{ $away := index ($comp.Array "competitors") 0 }}
    {{ $home := index ($comp.Array "competitors") 1 }}

    {{ $awayRec := "" }}
    {{ if gt (len ($away.Array "records")) 0 }}{{ $awayRec = (index ($away.Array "records") 0).String "summary" }}{{ end }}
    {{ $homeRec := "" }}
    {{ if gt (len ($home.Array "records")) 0 }}{{ $homeRec = (index ($home.Array "records") 0).String "summary" }}{{ end }}

    {{ $awaySchedule := "" }}
    {{ range $away.Array "team.links" }}
        {{ if eq (.String "text") "Schedule" }}
        {{ $awaySchedule = .String "href" }}
        {{ end }}
    {{ end }}

    {{ $homeSchedule := "" }}
    {{ range $home.Array "team.links" }}
        {{ if eq (.String "text") "Schedule" }}
        {{ $homeSchedule = .String "href" }}
        {{ end }}
    {{ end }}

    {{ $gameLink := "" }}
    {{ range .Array "links" }}
        {{ $isGameLink := false }}
        {{ range .Array "rel" }}
        {{ if eq (printf "%v" .) "summary" }}
            {{ $isGameLink = true }}
        {{ end }}
        {{ end }}
        {{ if $isGameLink }}
        {{ $gameLink = .String "href" }}
        {{ end }}
    {{ end }}

    {{ $leagueLogo := "https://a.espncdn.com/redesign/assets/img/icons/ESPN-icon-football-college.png" }}
    {{ $awayLogo := $away.String "team.logo" }}
    {{ if eq $awayLogo "" }}{{ $awayLogo = $leagueLogo }}{{ end }}
    {{ $homeLogo := $home.String "team.logo" }}
    {{ if eq $homeLogo "" }}{{ $homeLogo = $leagueLogo }}{{ end }}

    {{ $awayBox := "" }}
    {{ $homeBox := "" }}
    {{ if gt (len ($away.Array "linescores")) 0 }}
        {{ range $i2, $ls := $away.Array "linescores" }}
        {{ $qn := add $i2 1 }}
        {{ $val := $ls.String "displayValue" }}
        {{ $awayBox = printf "%sQ%d:%s " $awayBox $qn $val }}
        {{ end }}
    {{ end }}
    {{ if gt (len ($home.Array "linescores")) 0 }}
        {{ range $i2, $ls := $home.Array "linescores" }}
        {{ $qn := add $i2 1 }}
        {{ $val := $ls.String "displayValue" }}
        {{ $homeBox = printf "%sQ%d:%s " $homeBox $qn $val }}
        {{ end }}
    {{ end }}

    {{ $leadersText := "" }}
    {{ range $comp.Array "leaders" }}
        {{ $name := .String "name" }}
        {{ if or (eq $name "passing") (eq $name "rushing") (eq $name "receiving") }}
        {{ range .Array "leaders" }}
            {{ $ath := .String "athlete.shortName" }}
            {{ $disp := .String "displayValue" }}
            {{ if ne $ath "" }}{{ $leadersText = printf "%s%s: %s\n" $leadersText $ath $disp }}{{ end }}
        {{ end }}
        {{ end }}
    {{ end }}

    {{ $state := $comp.String "status.type.name" }}
    {{/* alias schedule link variable names to match nfl template naming */}}
    {{ $awayScheduleLink := $awaySchedule }}
    {{ $homeScheduleLink := $homeSchedule }}

    {{ $tooltip := printf "%s Box: %s\n%s Box: %s\n\nGame Leaders:\n%s" ($away.String "team.abbreviation") $awayBox ($home.String "team.abbreviation") $homeBox $leadersText }}

    <li style="display:flex;align-items:center;white-space:nowrap;gap:12px;padding:6px 0;border-bottom:1px solid var(--glance-divider);cursor:default" {{ if ne $state "STATUS_SCHEDULED" }}title="{{ $tooltip }}"{{ end }}>
        <span style="display:flex;align-items:center;flex:1;justify-content:space-between;">
        {{ if $awayScheduleLink }}
            <a href="{{ $awayScheduleLink }}" target="_blank" style="text-decoration:none;color:inherit;display:flex;align-items:center;">
            <img src="{{ $awayLogo }}" alt="{{ $away.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;cursor:pointer;"/>
            </a>
        {{ else }}
            <img src="{{ $awayLogo }}" alt="{{ $away.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;"/>
        {{ end }}
        <span style="display:flex;flex-direction:column;flex:1;">
            <span style="font-weight:bold;">{{ $away.String "team.abbreviation" }}</span>
            {{ if $awayRec }}<span style="font-size:0.7em;color:var(--glance-muted-text)">({{ $awayRec }})</span>{{ end }}
        </span>
        {{ if ne $state "STATUS_SCHEDULED" }}<span style="font-size:1.1em;font-weight:500;min-width:20px;text-align:right;">{{ $away.String "score" }}</span>{{ end }}
        </span>
        {{ if $gameLink }}
        <a href="{{ $gameLink }}" target="_blank" style="text-decoration:none;color:inherit;">
