        {{ end }}
        <span style="display:flex;flex-direction:column;flex:1;">
            <span style="font-weight:bold;">{{ $home.String "team.abbreviation" }}</span>
            {{ if $homeRec }}<span style="font-size:0.7em;color:var(--glance-muted-text)">({{ $homeRec }})</span>{{ end }}
        </span>
        {{ if ne $state "STATUS_SCHEDULED" }}<span style="font-size:1.1em;font-weight:500;min-width:20px;text-align:right;">{{ $home.String "score" }}</span>{{ end }}
        </span>
    </li>
    {{ end }}

- type: custom-api
  title: NetAlertX Device Status
  method: GET
  cache: 5m
  url: http://${NETALERTX_URL}/php/server/query_json.php?file=table_devices.json
  headers:
    Accept: application/json
    Authorization: Bearer ${NETALERTX_API_TOKEN}
  template: |
    {{ $data := .JSON.Array "data" }}
    {{ $totalDevices := len $data }}
    {{ $connectedDevicesCount := 0 }}
    {{ range $dev := $data }}
      {{ if eq ($dev.Int "devPresentLastScan") 1 }}
        {{ $connectedDevicesCount = add $connectedDevicesCount 1 }}
      {{ end }}
    {{ end }}
    <div style="font-weight: bold; font-size: 1.2em; margin-bottom: 0.5em; display:flex; gap: 1rem;">
      <details style="flex: 1;" open>
        <summary class="color-highlight size-h3" style="cursor: pointer; font-weight: 600;">
          Connected ({{ $connectedDevicesCount }})
        </summary>
        <div style="max-height: 300px; overflow-y: auto; padding-right: 6px;">
          <ul style="padding-left: 0; margin: 0; list-style: none;">
            {{ range $dev := $data }}
              {{ if eq ($dev.Int "devPresentLastScan") 1 }}
                {{ $iconData := $dev.String "devIcon" }}
                {{ $name := $dev.String "devName" }}
                {{ $displayName := $name }}
                {{ if gt (len $name) 26 }}
                  {{ $displayName = printf "%s…" (slice $name 0 26) }}
                {{ end }}
                <li style="margin-bottom: 1em;">
                  <div style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                    {{ if or (eq $iconData "") (lt (len $iconData) 20) (and (ge (len $iconData) 2) (eq (slice $iconData 0 2) "PG")) }}
                      <!-- Fallback emoji when icon invalid or empty -->
                      <span style="font-size: 20px;">​🌐​️</span>
                    {{ else }}
                      <!-- Show SVG base64 icon -->
                      <img src="data:image/svg+xml;base64,{{ $iconData }}" alt="icon" style="width: 20px; height: 20px;" />
                    {{ end }}
                    <span title="{{ $name }}" style="font-weight: 600; font-size: 0.9em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px;">
                      {{ $displayName }}
                    </span>
                    <span style="padding: 2px 6px; font-size: 0.75em; color: var(--color-positive); border: 1px solid var(--color-positive); border-radius: 4px; white-space: normal; max-width: 100px; word-break: break-word;">
                      {{ $dev.String "devStatus" }}
                    </span>
                  </div>
                  <div title="{{ $dev.String "devLastIP" }}" style="font-size: 0.75em; color: var(--color-subtle); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 200px;">
                    {{ $dev.String "devLastIP" }}
                  </div>
                </li>
              {{ end }}
            {{ end }}
          </ul>
        </div>
      </details>
    </div>

- type: custom-api
  title: Netbird Devices
  title-url: https://app.netbird.io/peers
  url: https://api.netbird.io/api/peers
  headers:
    Accept: application/json
    Authorization: Token ${NETBIRD_API_KEY}
  cache: 10m
  template: |
    {{ $enableOnlineIndicator := false }}

    <style>
      .device-info-container {
        position: relative;
        overflow: hidden;
        height: 1.5em;
      }

      .device-info {
        display: flex;
        transition: transform 0.2s ease, opacity 0.2s ease;
      }

      .device-ip {
        position: absolute;
        top: 0;
        left: 0;
        transform: translateY(-100%);
        opacity: 0;
        transition: transform 0.2s ease, opacity 0.2s ease;
      }

      .device-info-container:hover .device-info {
        transform: translateY(100%);
        opacity: 0;
      }

      .device-info-container:hover .device-ip {
        transform: translateY(0);
        opacity: 1;
      }

      .offline-indicator,
      .online-indicator {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        display: inline-block;
        margin-left: 4px;
        vertical-align: middle;
      }

      .online-indicator {
        background-color: var(--color-positive);
      }

      .offline-indicator {
        background-color: var(--color-negative);
      }

      .device-name-container {
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .indicators-container {
        display: flex;
        align-items: center;
        gap: 4px;
      }
    </style>

    <ul class="list list-gap-10 collapsible-container" data-collapse-after="4">
      {{ range .JSON.Array "" }}
      <li>
        <div class="flex items-center gap-10">
          <div class="device-name-container grow">
            <span class="size-h4 block text-truncate color-primary">
              {{ .String "hostname" }}
            </span>
            <div class="indicators-container">
              {{ if .Bool "connected" }}
                {{ if $enableOnlineIndicator }}
                <span class="online-indicator" data-popover-type="text" data-popover-text="Online"></span>
                {{ end }}
              {{ else }}
                {{ $lastSeen := .String "last_seen" | parseTime "rfc3339" }}
                <span class="offline-indicator" data-popover-type="text" data-popover-text="Offline - Last seen {{ $lastSeen.Format "Jan 2 3:04pm" }}"></span>
              {{ end }}
            </div>
          </div>
        </div>
        <div class="device-info-container">
          <ul class="list-horizontal-text device-info">
            <li>{{ .String "os" }}</li>
            <li>{{ .String "city_name" }}, {{ .String "country_code"}}</li>
          </ul>
          <div class="device-ip">
            {{ .String "ip" }}
            {{ .String "dns_label"}}
          </div>
        </div>
      </li>
      {{ end }}
    </ul>

- type: custom-api
  title: Nextcloud Deck
  cache: 30s
  options:
      board-id: 2
      show-labels: true
      collapse-after: 3
  template: |
      {{ $boardId := .Options.IntOr "board-id" 0 }}
      {{ $showLabels := .Options.BoolOr "show-labels" false }}
