      {{
      $deck := newRequest (printf "${NEXTCLOUD_HOST}/index.php/apps/deck/api/v1.1/boards/%d/stacks" $boardId)
          | withHeader "Authorization" "Basic ${NEXTCLOUD_AUTH}"
          | getResponse
