          <ul class="list list-gap-14 collapsible-container list-with-separator" data-collapse-after="{{ $collapseAfter }}">
              {{ range sortByInt "order" "asc" (.Array "cards") }}
              <li>
                  <a 
                  style="{{ if .String "done" }}text-decoration: line-through;{{ end }}"
