          </ul>
          </div>
      {{ end }}
      </div>

- type: custom-api
  title: NextDNS Analytics
  title-url: https://api.nextdns.io/profiles/${NEXTDNS_PROFILE_ID}/analytics/status
  cache: 1h
  url: https://api.nextdns.io/profiles/${NEXTDNS_PROFILE_ID}/analytics/status
  headers:
    X-Api-Key: ${NEXTDNS_API_KEY}
  template: |
    {{ if eq .Response.StatusCode 200 }}
      <div style="display: flex; justify-content: space-between;">
        {{ $total := 0.0 }}
        {{ $blocked := 0.0 }}
        {{ range .JSON.Array "data" }}
          {{ $total = add $total (.Int "queries" | toFloat) }}
          {{ if eq (.String "status") "blocked" }}
            {{ $blocked = add $blocked (.Int "queries" | toFloat) }}
          {{ end }}
        {{ end }}
        <div style="flex: 1; text-align: center;">
          <p>Queries</p>
          <p>{{ printf "%.0f" $total }}</p>
        </div>
        <div style="flex: 1; text-align: center; color: var(--color-negative);">
          <p>Blocked</p>
          <p>{{ printf "%.0f" $blocked }}</p>
        </div>
        <div style="flex: 1; text-align: center;">
          <p>Block Rate</p>
          {{ if gt $total 0.0 }}
            <p>{{ div (mul $blocked 100) $total | printf "%.2f" }}%</p>
          {{ else }}
            <p>0.00%</p>
          {{ end }}
        </div>
      </div>
    {{ else }}
      <div style="text-align: center; color: var(--color-negative);">
        Error: {{ .Response.StatusCode }} - {{ .Response.Status }}
      </div>
    {{ end }}

- type: custom-api
  title: NFL Scoreboard
  url: "https://site.api.espn.com/apis/site/v2/sports/football/nfl/scoreboard"
  cache: 1m
  template: |
    {{ $events := .JSON.Array "events" }}
      {{ if eq (len $events) 0 }}
        <div>No games scheduled today.</div>
      {{ else }}
        {{ $wid := printf "nfl-%d" now.UnixNano }}
        <div id="{{ $wid }}" style="position:relative;padding-bottom:{{ if gt (len $events) 6 }}25px{{ else }}0px{{ end }};">
          <input type="checkbox" id="{{ $wid }}-cb" style="display:none"/>
          <ul class="visible" style="list-style:none;padding:0;margin:0;">
            {{ $count := 0 }}

            {{ range $i, $g := $events }}
              {{ if and (lt $count 6) (eq ($g.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") }}
                {{ template "nfl-game" $g }}
                {{ $count = add $count 1 }}
              {{ end }}
            {{ end }}

            {{ range $i, $g := $events }}
              {{ if and (lt $count 6) (eq ($g.String "competitions.0.status.type.name") "STATUS_SCHEDULED") }}
                {{ template "nfl-game" $g }}
                {{ $count = add $count 1 }}
              {{ end }}
            {{ end }}

            {{ range $i, $g := $events }}
              {{ if and (lt $count 6) (not (or (eq ($g.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") (eq ($g.String "competitions.0.status.type.name") "STATUS_SCHEDULED"))) }}
                {{ template "nfl-game" $g }}
                {{ $count = add $count 1 }}
              {{ end }}
            {{ end }}
          </ul>

          <ul class="all" style="list-style:none;padding:0;margin:0;display:none">
            {{ range $i, $g := $events }}
              {{ if eq ($g.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS" }}
                {{ template "nfl-game" $g }}
              {{ end }}
            {{ end }}

            {{ range $i, $g := $events }}
              {{ if eq ($g.String "competitions.0.status.type.name") "STATUS_SCHEDULED" }}
                {{ template "nfl-game" $g }}
              {{ end }}
            {{ end }}

            {{ range $i, $g := $events }}
              {{ if not (or (eq ($g.String "competitions.0.status.type.name") "STATUS_IN_PROGRESS") (eq ($g.String "competitions.0.status.type.name") "STATUS_SCHEDULED")) }}
                {{ template "nfl-game" $g }}
              {{ end }}
            {{ end }}
          </ul>

          {{ if gt (len $events) 6 }}
            <label for="{{ $wid }}-cb" style="position:absolute;bottom:0px;right:0;cursor:pointer;color:var(--glance-accent-color);font-size:16px;padding:5px;">
              <span style="display:inline-block;transition:transform .2s">▼</span>
            </label>
          {{ end }}
          <style>
            #{{ $wid }}-cb:not(:checked) ~ .all { display:none!important }
            #{{ $wid }}-cb:checked ~ .visible { display:none!important }
            #{{ $wid }}-cb:checked ~ .all { display:block!important }
            #{{ $wid }}-cb:checked ~ label span { transform:rotate(180deg)!important }
          </style>
        </div>
      {{ end }}

      {{ define "nfl-game" }}
        {{ $state := .String "competitions.0.status.type.name" }}
        {{ $away := index (.Array "competitions.0.competitors") 0 }}
        {{ $home := index (.Array "competitions.0.competitors") 1 }}
        {{ $awayRec := "" }}
        {{ if gt (len ($away.Array "records")) 0 }}{{ $awayRec = (index ($away.Array "records") 0).String "summary" }}{{ end }}
        {{ $homeRec := "" }}
        {{ if gt (len ($home.Array "records")) 0 }}{{ $homeRec = (index ($home.Array "records") 0).String "summary" }}{{ end }}

        {{ $awayScheduleLink := "" }}
        {{ range $away.Array "team.links" }}
          {{ if eq (.String "text") "Schedule" }}
            {{ $awayScheduleLink = .String "href" }}
          {{ end }}
        {{ end }}

        {{ $homeScheduleLink := "" }}
        {{ range $home.Array "team.links" }}
          {{ if eq (.String "text") "Schedule" }}
            {{ $homeScheduleLink = .String "href" }}
          {{ end }}
        {{ end }}

        {{ $gameLink := "" }}
        {{ range .Array "links" }}
          {{ $isGameLink := false }}
          {{ range .Array "rel" }}
            {{ if eq (printf "%v" .) "summary" }}
              {{ $isGameLink = true }}
            {{ end }}
          {{ end }}
          {{ if $isGameLink }}
            {{ $gameLink = .String "href" }}
          {{ end }}
        {{ end }}

        {{ $tooltip := "" }}
        {{ if ne $state "STATUS_SCHEDULED" }}
          {{ $awayBoxScore := "" }}
          {{ range $j,$ls := $away.Array "linescores" }}
            {{ if eq $j 0 }}{{ $awayBoxScore = printf "%s Q1: %s" $awayBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 1 }}{{ $awayBoxScore = printf "%s Q2: %s" $awayBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 2 }}{{ $awayBoxScore = printf "%s Q3: %s" $awayBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 3 }}{{ $awayBoxScore = printf "%s Q4: %s" $awayBoxScore ($ls.String "displayValue") }}
            {{ else }}{{ $awayBoxScore = printf "%s OT: %s" $awayBoxScore ($ls.String "displayValue") }}{{ end }}
          {{ end }}

          {{ $homeBoxScore := "" }}
          {{ range $j,$ls := $home.Array "linescores" }}
            {{ if eq $j 0 }}{{ $homeBoxScore = printf "%s Q1: %s" $homeBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 1 }}{{ $homeBoxScore = printf "%s Q2: %s" $homeBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 2 }}{{ $homeBoxScore = printf "%s Q3: %s" $homeBoxScore ($ls.String "displayValue") }}
            {{ else if eq $j 3 }}{{ $homeBoxScore = printf "%s Q4: %s" $homeBoxScore ($ls.String "displayValue") }}
            {{ else }}{{ $homeBoxScore = printf "%s OT: %s" $homeBoxScore ($ls.String "displayValue") }}{{ end }}
          {{ end }}

          {{ $gameLeaders := "" }}
          {{ range .Array "competitions.0.leaders" }}
            {{ if eq (.String "name") "passingYards" }}
              {{ range .Array "leaders" }}
                {{ $gameLeaders = printf "%sPassing: %s (%s)\n" $gameLeaders (.String "athlete.shortName") (.String "displayValue") }}
              {{ end }}
            {{ else if eq (.String "name") "rushingYards" }}
              {{ range .Array "leaders" }}
                {{ $gameLeaders = printf "%sRushing: %s (%s)\n" $gameLeaders (.String "athlete.shortName") (.String "displayValue") }}
              {{ end }}
            {{ else if eq (.String "name") "receivingYards" }}
              {{ range .Array "leaders" }}
                {{ $gameLeaders = printf "%sReceiving: %s (%s)\n" $gameLeaders (.String "athlete.shortName") (.String "displayValue") }}
              {{ end }}
            {{ end }}
          {{ end }}

          {{ $tooltip = printf "%s Box:%s\n%s Box:%s\n\nGame Leaders:\n%s" ($away.String "team.abbreviation") $awayBoxScore ($home.String "team.abbreviation") $homeBoxScore $gameLeaders }}
        {{ end }}

        <li style="display:flex;align-items:center;white-space:nowrap;gap:12px;padding:6px 0;border-bottom:1px solid var(--glance-divider);cursor:default" {{ if ne $state "STATUS_SCHEDULED" }}title="{{ $tooltip }}"{{ end }}>
          <span style="display:flex;align-items:center;flex:1;justify-content:space-between;">
            {{ if $awayScheduleLink }}
              <a href="{{ $awayScheduleLink }}" target="_blank" style="text-decoration:none;color:inherit;display:flex;align-items:center;">
                <img src="{{ if $away.String "team.logo" }}{{ $away.String "team.logo" }}{{ else }}https://a.espncdn.com/i/teamlogos/leagues/500/nfl.png{{ end }}" alt="{{ $away.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;cursor:pointer;"/>
              </a>
            {{ else }}
              <img src="{{ if $away.String "team.logo" }}{{ $away.String "team.logo" }}{{ else }}https://a.espncdn.com/i/teamlogos/leagues/500/nfl.png{{ end }}" alt="{{ $away.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;"/>
            {{ end }}
            <span style="display:flex;flex-direction:column;flex:1;">
              <span style="font-weight:bold;">{{ $away.String "team.abbreviation" }}</span>
              {{ if $awayRec }}<span style="font-size:0.7em;color:var(--glance-muted-text)">({{ $awayRec }})</span>{{ end }}
            </span>
            {{ if ne $state "STATUS_SCHEDULED" }}<span style="font-size:1.1em;font-weight:500;min-width:20px;text-align:right;">{{ $away.String "score" }}</span>{{ end }}
          </span>
          {{ if $gameLink }}
            <a href="{{ $gameLink }}" target="_blank" style="text-decoration:none;color:inherit;">
              <span style="display:flex;flex-direction:column;align-items:center;flex-shrink:0;margin:0 8px;cursor:pointer;">
                <span>
                  {{ if eq $state "STATUS_IN_PROGRESS" }}
                    {{ $period := .String "competitions.0.status.period" }}
                    <span style="font-size:0.85em;font-weight:500;">{{ if eq $period "1" }}1st{{ else if eq $period "2" }}2nd{{ else if eq $period "3" }}3rd{{ else if eq $period "4" }}4th{{ else }}OT{{ end }} {{ .String "competitions.0.status.displayClock" }}</span>
                  {{ else if eq $state "STATUS_SCHEDULED" }}
                    <span style="font-size:0.85em;">{{ .String "competitions.0.status.type.shortDetail" }}</span>
                  {{ else }}
                    <span style="font-size:0.85em;font-weight:500;">{{ .String "competitions.0.status.type.shortDetail" }}</span>
                  {{ end }}
                </span>

                {{ if .Exists "competitions.0.series" }}
                  <span style="font-size:0.7em;color:var(--glance-accent-color);margin-top:5px;">{{ .String "competitions.0.series.summary" }}</span>
                {{ end }}
              </span>
            </a>
          {{ else }}
            <span style="display:flex;flex-direction:column;align-items:center;flex-shrink:0;margin:0 8px;">
              <span>
                {{ if eq $state "STATUS_IN_PROGRESS" }}
                  {{ $period := .String "competitions.0.status.period" }}
                  <span style="font-size:0.85em;font-weight:500;">{{ if eq $period "1" }}1st{{ else if eq $period "2" }}2nd{{ else if eq $period "3" }}3rd{{ else if eq $period "4" }}4th{{ else }}OT{{ end }} {{ .String "competitions.0.status.displayClock" }}</span>
                {{ else if eq $state "STATUS_SCHEDULED" }}
                  <span style="font-size:0.85em;">{{ .String "competitions.0.status.type.shortDetail" }}</span>
                {{ else }}
                  <span style="font-size:0.85em;font-weight:500;">{{ .String "competitions.0.status.type.shortDetail" }}</span>
                {{ end }}
              </span>

              {{ if .Exists "competitions.0.series" }}
                <span style="font-size:0.7em;color:var(--glance-accent-color);margin-top:5px;">{{ .String "competitions.0.series.summary" }}</span>
              {{ end }}
            </span>
          {{ end }}
          <span style="display:flex;align-items:center;flex:1;justify-content:space-between;">
            {{ if $homeScheduleLink }}
              <a href="{{ $homeScheduleLink }}" target="_blank" style="text-decoration:none;color:inherit;display:flex;align-items:center;">
                <img src="{{ if $home.String "team.logo" }}{{ $home.String "team.logo" }}{{ else }}https://a.espncdn.com/i/teamlogos/leagues/500/nfl.png{{ end }}" alt="{{ $home.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;cursor:pointer;"/>
              </a>
            {{ else }}
              <img src="{{ if $home.String "team.logo" }}{{ $home.String "team.logo" }}{{ else }}https://a.espncdn.com/i/teamlogos/leagues/500/nfl.png{{ end }}" alt="{{ $home.String "team.abbreviation" }}" style="width:24px;height:24px;margin-right:6px;"/>
            {{ end }}
            <span style="display:flex;flex-direction:column;flex:1;">
              <span style="font-weight:bold;">{{ $home.String "team.abbreviation" }}</span>
              {{ if $homeRec }}<span style="font-size:0.7em;color:var(--glance-muted-text)">({{ $homeRec }})</span>{{ end }}
            </span>
            {{ if ne $state "STATUS_SCHEDULED" }}<span style="font-size:1.1em;font-weight:500;min-width:20px;text-align:right;">{{ $home.String "score" }}</span>{{ end }}
          </span>
        </li>
      {{ end }}

- type: custom-api
  title: Nginx Proxy Manager
  cache: 12h
  url: ${NGINX_PROXY_URL}/api/tokens
  method: POST
  body-type: json
  body:
    identity: ${NGINX_EMAIL_ID}
    secret: ${NGINX_PASSWORD}
  options:
    collapse-after: 6
    show-icons: true
    domain-name: ".example.com" # this is your top level DNS domain name
    tooltip-enabled: true
    #  if you want custom icons add here [either simple icon id or full url]
    code: coder
    paperless: paperlessngx
    docker: docker
    glance: https://cdn.jsdelivr.net/gh/selfhst/icons/svg/glance-dark.svg
    portainer: portainer

  template: |
    <style>
      .widget-type-nginx li {
        margin-top: var(--list-half-gap); 
        border-top: 1px solid var(--color-separator);
        padding-top: var(--list-half-gap);
      }
      .widget-ngix-proxy-icon, .widget-ngix-proxy-icon-default  {
        display: block;
        filter: grayscale(0.4);
        object-fit: contain;
        aspect-ratio: 1 / 1;
        width: 2.7rem;
        opacity: 0.8;
        transition: filter 0.3s, opacity 0.3s;
      }
      // DISABLE THE BELOW CSS FOR COLOR ICONS 
      :root[data-scheme="dark"] .widget-ngix-proxy-icon {
        filter: invert(100%); // this to invert colors for dark and light theme 
      } 
    </style>

    {{ $defaultIconUrl := "https://cdn.jsdelivr.net/gh/selfhst/icons/svg/nginx-proxy-manager.svg" }}

    {{ if eq .Response.StatusCode 200 }}
      {{ $accessToken := .JSON.String "token" }}
      {{
        $proxyHosts := newRequest (concat "${NGINX_PROXY_URL}" "/api/nginx/proxy-hosts")
          | withHeader "Authorization" (print "Bearer " $accessToken)
          | getResponse
      }}
      <ul  class="dynamic-columns list list-gap-15 list-with-separator  collapsible-container"  data-collapse-after="{{ .Options.IntOr "collapse-after" 6 }}">
        {{ range $proxyHosts.JSON.Array "" }}
          {{ if and (.String "domain_names.0") (.Bool "enabled")  }}

            {{ $proxy_url  := (concat (.String "forward_scheme") "://" (.String "domain_names.0") ) }}
            {{ $host_url   := (concat (.String "forward_scheme") "://" (.String "forward_host") ":" (.String "forward_port") ) }}
            {{ $subDomain  := .String "domain_names.0" | trimSuffix ($.Options.StringOr "domain-name" "") }}

            <li class="flex items-center gap-20" >
              <!-- Icon Section -->
              {{ if $.Options.BoolOr "show-icons" true }}
                <div class="shrink-0">
                    {{ $iconUrl := $.Options.StringOr $subDomain $defaultIconUrl}}
                    {{ if eq $iconUrl $defaultIconUrl }}
                      <img class="widget-ngix-proxy-icon-default" src="{{ $defaultIconUrl }}" loading="lazy">
                    {{ else }}
                      {{ if ne (findMatch "://" $iconUrl)  "://" }} <!-- check if url is NOT provided -->
                        <img class="widget-ngix-proxy-icon" src="https://simpleicons.org/icons/{{$iconUrl}}.svg" loading="lazy">
                      {{ else }}
                        <img class="widget-ngix-proxy-icon" src="{{ $iconUrl }}" loading="lazy">
                      {{ end }}
                    {{ end }}
                </div>
              {{ end }}

              <!-- Proxy URLs Section -->
              <div class="min-width-0 grow">
                <a href='{{ $proxy_url }}' class="color-highlight size-title-dynamic block" style="display: inline;" target="_blank" rel="noreferrer"
                    {{if $.Options.BoolOr "tooltip-enabled" false}}data-popover-type="text" data-popover-text="{{$proxy_url}}"{{end}}
                  >{{ $subDomain }}</a>
                <div class="flex items-center gap-10" style="margin-bottom: 5px">
                  <div class="text-left">
                        ➔
                  </div>
                  <div class="size-h6 flex-1 text-left">
                    <a href='{{ $host_url }}' target="_blank" rel="noreferrer">{{ $host_url }}</a>
                  </div>
                </div>
              </div>
            </li>
          {{ end }}
        {{ end }}
      </ul>

    {{ else }}
      <p class='color-negative'>Failed to get token: {{ .JSON.String "error.message" }} ({{ $.Response.Status }}) </p>
    {{ end }}

- type: custom-api
  title: NHL Today
  cache: 5s
  url: https://api-web.nhle.com/v1/score/now
  template: |
    {{ $myTeam := "ALL" }}
    {{ $games := .JSON.Array "games" }}
    {{ define "gameItem" }}
      {{ $toolTipEnabled := true }}
      {{ $awayTeamColor := "" }}
      {{ $homeTeamColor := "" }}
      {{ $situationDescriptionHome := "" }}
      {{ $situationDescriptionAway := "" }}
      {{ $situationStrength := "" }}
      {{ $homeTeam := .String "homeTeam.abbrev" }}
      {{ $awayTeam := .String "awayTeam.abbrev" }}
      {{ $homeTeamScores := "" }}
      {{ $awayTeamScores := "" }}
      {{ range $index, $desc := .Array "goals" }}
          {{ $teamAbbrev := .String "teamAbbrev" }}
          {{ $playerName := .String "name.default" }}
          {{ $timeScored := .String "timeInPeriod" }}
          {{ $periodScored := .Int "period" }}
          {{ if eq $awayTeam $teamAbbrev }}
              {{ $awayTeamScores = (printf "%s %s %s(%d)" $awayTeamScores $playerName $timeScored $periodScored) }}
          {{ else if eq $homeTeam $teamAbbrev }}
              {{ $homeTeamScores = (printf "%s %s %s(%d)" $homeTeamScores $playerName $timeScored $periodScored) }}
          {{ end }}
      {{ end }}
      {{ $gameState := .String "gameState" }}
      {{ $currentLabel := "" }}
      {{ if or (eq $gameState "OFF") (eq $gameState "FINAL") }}
          {{ $lastPeriodType := .String "gameOutcome.lastPeriodType" }}
          {{ $currentLabel = "Final" }}
          {{ if or (eq $lastPeriodType "OT") (eq $lastPeriodType "SO") }}
              {{ $currentLabel = (printf "%s %s" $currentLabel $lastPeriodType) }}
          {{ end }}
      {{ end }}
      {{ if or (eq $gameState "FUT") (eq $gameState "PRE") }}
          {{ $gameTime := (.String "startTimeUTC" | parseTime "rfc3339").In now.Location }}
          {{ $currentLabel = (printf "%02d:%02d" $gameTime.Hour $gameTime.Minute) }}
      {{ end }}
      {{ if or (eq $gameState "LIVE") (eq $gameState "CRIT") }}
          {{ $period := .Int "period" }}
          {{ $periodString := .String "period" }}
          {{ $timeRemaining := .String "clock.timeRemaining" }}
          {{ $intermission := .Int "clock.inIntermission" }}
          {{ $periodType := .String "periodDescriptor.periodType" }}
          {{ if eq $period 1 }}
          {{ $addonValue := "st" }}
          {{ if eq $intermission 1 }}
              {{ $addonValue = printf "%s Int" $addonValue }}
          {{ end }}
          {{ $currentLabel = (printf "%s%s %s" $periodString $addonValue $timeRemaining) }}
          {{ else if eq $period 2 }}
              {{ $addonValue := "nd" }}
              {{ if eq $intermission 1 }}
                  {{ $addonValue = printf "%s Int" $addonValue }}
              {{ end }}
          {{ $currentLabel = (printf "%s%s %s" $periodString $addonValue $timeRemaining) }}
          {{ else if eq $period 3 }}
              {{ $addonValue := "rd" }}
              {{ if eq $intermission 1 }}
                  {{ $addonValue = printf "%s Int" $addonValue }}
              {{ end }}
          {{ $currentLabel = (printf "%s%s %s" $periodString $addonValue $timeRemaining) }}
          {{ else }}
          {{ $currentLabel = $periodType }} 
              {{ if not (eq $periodType "SO") }}
                  {{ $currentLabel = (printf "%s %s" $periodType $timeRemaining) }}
              {{ end }}
          {{ end }}
      {{ end }}
      {{ if .Exists "situation" }}
          {{ if .Exists "situation.awayTeam.situationDescriptions" }}
              {{ $awayTeamColor = "color-negative" }}
              {{ range $index, $desc := .Array "situation.awayTeam.situationDescriptions" }}
                    {{ $situationDescriptionAway = (printf "%s %s" $situationDescriptionAway $desc.Value) }}
              {{ end }} 
          {{ end }}
          {{ if .Exists "situation.homeTeam.situationDescriptions" }}
              {{ $homeTeamColor = "color-positive" }}
              {{ range $index, $desc := .Array "situation.homeTeam.situationDescriptions" }}
                  {{ $situationDescriptionHome = (printf "%s %s" $situationDescriptionHome $desc.Value) }}
              {{ end }}
          {{ end }}
        {{ $situationStrength = concat "(" (.String "situation.awayTeam.strength") "v" (.String "situation.homeTeam.strength") ")" }}
      {{ end }}
      <table>
          <tr>
              <td>
                  <a target="_blank" class="size-h3 color-highlight block text-truncate" href="https://www.nhl.com{{ .String "gameCenterLink" }}/">
                    <span class= {{ $awayTeamColor }} > {{ .String "awayTeam.name.default" }} </span> vs <span class= {{ $homeTeamColor }} > {{ .String "homeTeam.name.default" }} </span>
                  </a>
              </td>
          </tr>
          <tr>
              <td>
                  <span class= {{ $awayTeamColor }} > {{ $situationDescriptionAway }} </span> <span class= {{ $homeTeamColor }} > {{ $situationDescriptionHome }} </span> <span> {{ .String "situation.timeRemaining" }} {{ $situationStrength }}</span>
              </td>
          </tr>
      </table>
      <table>
          <tr>
              <td data-popover-type="html">
                  {{ if and (not (eq $awayTeamScores "")) (eq $toolTipEnabled true) }}
                      <div data-popover-html>
                        {{ $awayTeamScores }}
                      </div>
                  {{ end }}
                <img style="float: left" width="50" height="auto" src={{ .String "awayTeam.logo" }}>
              </td>
              <td data-popover-type="html">
                  {{ if and (not (eq $awayTeamScores "")) (eq $toolTipEnabled true) }}
                    <div data-popover-html>
                      {{ $awayTeamScores }}
                    </div>
                  {{ end }}
                <p style="font-size:25px"> {{ .String "awayTeam.score" }} </p>
              </td>
              <td>
                  <p style="font-size:25px">-</p>
              </td>
              <td data-popover-type="html">
                {{ if and (not (eq $homeTeamScores "")) (eq $toolTipEnabled true) }}
                  <div data-popover-html>
                    {{ $homeTeamScores }}
                  </div>
                {{ end }}
                <p style="font-size:25px"> {{ .String "homeTeam.score" }} </p>
              </td>
              <td data-popover-type="html">
                {{ if and (not (eq $homeTeamScores "")) (eq $toolTipEnabled true) }}
                  <div data-popover-html>
                    {{ $homeTeamScores }}
                  </div>
                {{ end }}
                <img style="float: left" width="50" height="auto" src={{ .String "homeTeam.logo" }}>
              </td>
              <td>
                  {{ $currentLabel }}
              </td>
          </tr>
      </table>
    {{ end }}

    <ul class="list list-gap-10 collapsible-container" data-collapse-after="10">
    {{ range $game := $games }}
        {{ if and (or (eq ($game.String "homeTeam.abbrev") $myTeam) (eq ($game.String "awayTeam.abbrev") $myTeam) (eq "ALL" $myTeam)) }}
        {{ $state := $game.String "gameState" }}
            {{ if not (or (eq $state "FINAL") (eq $state "OFF")) }}
                {{ template "gameItem" $game }}
            {{ end }}
        {{ end }}
    {{ end }}
    {{ range $game := $games }}
        {{ if and (or (eq ($game.String "homeTeam.abbrev") $myTeam) (eq ($game.String "awayTeam.abbrev") $myTeam) (eq "ALL" $myTeam)) }}
        {{ $state := $game.String "gameState" }}
            {{ if or (eq $state "FINAL") (eq $state "OFF") }}
                {{ template "gameItem" $game }}
            {{ end }}
        {{ end }}
    {{ end }}
    </ul>

- type: custom-api
  title: NZBGet Status
  cache: 5s
  url: ${NZBGET_BASE_URL}/jsonrpc/status
  options:
    api-base-url: ${NZBGET_BASE_URL} # base API URL for NZBGet
    queue-enabled: true              # enable or disable the queue
    queue-items: 3                   # number of queue items to show by default
    slow-speed: 0                    # under this KB/s, speed shows negative color. 0 to disable
  template: |

    {{ $apiBaseUrl := .Options.StringOr "api-base-url" "" }}
    {{ $queueEnabled := .Options.BoolOr "queue-enabled" false }}
    {{ $queueItems := .Options.IntOr "queue-items" 3 }}

    <style>
      .progress-container-nzbget {
        border: 2px solid var(--color-background);
        outline: 1px solid var(--color-text-subdue);
        position: relative;
        border-radius: 1rem;
        height: 1rem;
        width: 100%;
        margin-top: 0.2rem;
      }
      .progress-bar-nzbget {
        background: var(--color-positive);
        border-radius: 1rem;
        position: absolute;
        top: 0;
        bottom: 0;
        left: 0;
      }
      .queue-item-nzbget {
        background: var(--color-widget-background-highlight);
        border-radius: 1rem;
        line-height: 1.8rem;
        margin-bottom: 1rem;
        padding: 0.5rem 1rem;
      }
      .queue-item-title-nzbget {
        overflow-x: hidden;
        white-space: nowrap;
        text-overflow: clip;
      }
    </style>

    {{ $truncateFloat := `\d+\.\d\d` }}
    {{ $standby := .JSON.Bool "result.ServerStandBy" }}
    {{ $paused  := .JSON.Bool "result.DownloadPaused" }}

    {{ $rateB     := .JSON.Float "result.DownloadRate" }}
    {{ $rateKB    := div $rateB 1024 }}
    {{ $rateMB    := div $rateKB 1024 }}
    {{ $rateKBStr := $rateKB | formatNumber | findMatch $truncateFloat }}
    {{ $rateMBStr := $rateMB | formatNumber | findMatch $truncateFloat }}

    {{ $remainingMB := .JSON.Float "result.RemainingSizeMB" }}
    {{ $remainingGB := div $remainingMB 1024 | formatNumber | findMatch $truncateFloat  }}

    {{ $timeLeftTotalSecs := div $remainingMB $rateMB }}
    {{ $timeLeftDays      := div $timeLeftTotalSecs 86400 | toInt }}
    {{ $timeLeftTotalSecs  = mod (toInt $timeLeftTotalSecs) 86400 | toFloat }}
    {{ $timeLeftHours     := div $timeLeftTotalSecs 3600 | toInt }}
    {{ $timeLeftTotalSecs  = mod (toInt $timeLeftTotalSecs) 3600 | toFloat }}
    {{ $timeLeftMins      := div $timeLeftTotalSecs 60 | toInt }}
    {{ $timeLeftSecs      := mod (toInt $timeLeftTotalSecs) 60 }}

    {{ $speedColor        := "color-highlight" }}
    {{ $threshold         := .Options.IntOr "slow-speed" 0 }}
    {{ $thresholdEnabled  := gt $threshold 0}}
    {{ $thresholdExceeded := gt (toInt $rateKB) $threshold }}

    {{ if and $thresholdEnabled (not $thresholdExceeded) }}
      {{ $speedColor = "color-negative" }}
    {{ end }}

    <div>
      {{ if $paused }}
          <p class="size-h5 text-center">Downloads are paused.</p>
      {{ else if $standby }}
          <p class="size-h5 text-center">No downloads queued.</p>
      {{ else }}
          <ul class="flex justify-between mb-2 text-center">
            <li class="flex-1">
              <div class="{{ $speedColor }} size-h3">
                {{ if lt (toInt $rateKB) 1024 }}
                  {{ $rateKBStr }}<span class="size-h6">KB/s</span>
                {{ else }}
                  {{ $rateMBStr }}<span class="size-h6">MB/s</span>
                {{ end }}
              </div>
              <div class="size-h6">SPEED</div>
            </li>
            <li class="flex-1">
              <div class="color-highlight size-h3 flex justify-center"  style="gap: 0.3rem;">
                {{ if gt $timeLeftDays 0 }}
                  <div class="flex items-end">
                    <span class="size-h3">{{ $timeLeftDays }}</span>
                    <span class="size-h6" style="margin-bottom: 1px">d</span>
                  </div>
                {{ end }}
                {{ if gt $timeLeftHours 0 }}
                  <div class="flex items-end">
                    <span class="size-h3">{{ $timeLeftHours }}</span>
                    <span class="size-h6" style="margin-bottom: 1px">h</span>
                  </div>
                {{ end }}
                {{ if and (gt $timeLeftMins 0) (eq $timeLeftDays 0) }}
                  <div class="flex items-end">
                    <span class="size-h3">{{ $timeLeftMins }}</span>
                    <span class="size-h6" style="margin-bottom: 1px">m</span>
                  </div>
                {{ end }}
                {{ if and (eq $timeLeftHours 0) (eq $timeLeftMins 0) }}
                  <div class="flex items-end">
                    <span class="size-h3">{{ $timeLeftSecs }}</span>
                    <span class="size-h6" style="margin-bottom: 1px">s</span>
                  </div>
                {{ end }}
              </div>
              <div class="size-h6">ETA</div>
            </li>
            <li class="flex-1">
              <div class="flex justify-center color-highlight" style="align-items: baseline;">
                {{ if lt (toInt $remainingMB) 1024 }}
                  <span class="size-h3">{{ $remainingMB }}</span>
                  <span class="size-h6">MB</span>
                {{ else }}
                  <span class="size-h3">{{ $remainingGB }}</span>
                  <span class="size-h6">GB</span>
                {{ end }}
              </div>
              <div class="size-h6">REMAINING</div>
            </li>
          </ul>

      {{ end }}

      {{ if $queueEnabled }}
        {{ $groups := newRequest (concat $apiBaseUrl "/jsonrpc/listgroups") | getResponse }}
        {{ $result := $groups.JSON.Array "result" }}
        {{ $collapsible := gt (len $result) $queueItems }}

        {{ if gt (len $result) 0 }}
          {{ if $collapsible }}
            <p class="size-h6 color-base text-center" style="margin: 1rem 0 -1rem;">{{ len $result }} items in queue</p>
          {{ end }}
          <ul class="list collapsible-container" data-collapse-after="{{ $queueItems }}" style="margin: 2rem 0 {{ if $collapsible }}-1rem{{ else }}0{{ end }};">
          {{ range $result }}
            <li class="queue-item-nzbget">
              <p class="queue-item-title-nzbget size-h6">{{ .String "NZBName" }}</p>
              {{ template "status" . }}
            </li>
          {{ end }}
          </ul>
        {{ end }}
      {{ end }}

    </div>

    {{ define "status" }}
      {{ $status := .String "Status" }}
      <p class="size-h6 flex flex-column">
        {{ if eq $status "QUEUED" }}
          <span class="color-subdue" title="Queued for download">Queued ({{ .Int "FileSizeMB" }} MB)</span>
        {{ else if eq $status "PAUSED" }}
          <span>Paused</span>
        {{ else if eq $status "DOWNLOADING" }}
          {{ $downloaded := .Float "DownloadedSizeMB" }}
          {{ $total := .Float "FileSizeMB" }}
          {{ $completed := div $downloaded $total | mul 100 }}
          <span class="color-highlight" title="Item is being downloaded">Downloading ({{ $downloaded }}/{{ $total }} MB)</span>
          <div class="progress-container-nzbget">
            <div class="progress-bar-nzbget" style="width: {{ $completed }}%;"></div>
          </div>
        {{ else if eq $status "FETCHING" }}
          <span title="NZB-file is being fetched from URL (Kind=URL)">Fetching</span>
        {{ else if eq $status "PP_QUEUED" }}
          <span title="queued for post-processing (completely downloaded)">Queued (Post-processing) </span>
        {{ else if eq $status "LOADING_PARS" }}
          <span title="Stage of par-check">Loading pars</span>
        {{ else if eq $status "VERIFYING_SOURCES" }}
          <span title="Stage of par-check">Verifying sources</span>
        {{ else if eq $status "REPAIRING" }}
          <span title="Stage of par-check">Repairing</span>
        {{ else if eq $status "VERIFYING_REPAIRED" }}
          <span title="Stage of par-check">Verifying repaired</span>
        {{ else if eq $status "RENAMING" }}
          <span title="Processed by par-renamer">Renaming</span>
        {{ else if eq $status "UNPACKING" }}
          <span title="Being unpacked">Unpacking</span>
        {{ else if eq $status "MOVING" }}
          <span title="Moving files from intermediate directory into destination directory">Moving </span>
        {{ else if eq $status "EXECUTING_SCRIPT" }}
          <span title="Executing post-processing script">Post-processing</span>
        {{ else if eq $status "PP_FINISHED" }}
          <span title="Post-processing is finished, the item is about to be moved to history.">Post-processing finished</span>
        {{ else }}
          Unknown status
        {{ end }}
      </p>
    {{ end }}

- type: custom-api
  title: Trending Media
  title-url: ${OVERSEERR_URL}/discover/trending    # trending, movies, or tv
  url: ${OVERSEERR_URL}/api/v1/discover/trending   # trending, movies, or tv
  cache: 15m
  headers:
    accept: "application/json"
    x-api-key: ${OVERSEERR_API_KEY}
  parameters:
    language: "en" # this can be changed to other languages if desired
    page: "1"
  options:
    show-media-type: true # set to false to hide the "| TV" or "| Movie" suffix
    show-media-desc: true # set to false to hide the media's summary
  template: |
    {{ $showMediaType := .Options.BoolOr "show-media-type" true }}
    {{ $showMediaDesc := .Options.BoolOr "show-media-desc" true }}

    {{ if eq .Response.StatusCode 200 }}
      {{ $items := .JSON.Array "results" }}
      {{ if gt (len $items) 0 }}
        <ul class="list list-gap-10 collapsible-container" data-collapse-after="5">
        {{ range $items }}
          <li class="flex items-start gap-10 thumbnail-container thumbnail-parent">
            {{ $mediaType := .String "mediaType" }}
            {{ $mediaTitle := "" }}
            {{ $mediaTypeUpper := "" }}
            {{ if eq $mediaType "movie" }} {{ $mediaTitle = .String "title" }} {{ $mediaTypeUpper = "Movie" }}{{ else }}{{ $mediaTitle = .String "name" }} {{ $mediaTypeUpper = "TV" }}{{ end }}
            {{ $overseerrUrl := concat "${OVERSEERR_URL}" "/" $mediaType "/" ( .String "id" ) }}
            {{ $tmdbUrl := concat "https://www.themoviedb.org" "/" $mediaType "/" ( .String "id" ) }}
            <a href={{ $overseerrUrl }} target="_blank">
            <img src={{ concat "https://image.tmdb.org/t/p/w300" (.String "posterPath") }} style="border-radius: 5px; min-width: 5rem; max-width: 5rem;" class="card">
            </a>
            <div class="flex-1" style="padding-right: 5px;">
              <p class="color-positive size-h4 text-truncate-2-lines margin-top-5" title={{ $mediaTitle }}><a href={{ $overseerrUrl }} target="_blank">{{ $mediaTitle }}</p>
              <p class="size-h4" title="TMDB Rating"><a href={{ $tmdbUrl }} target="_blank">TMDB: {{ mul (.Float "voteAverage") 10 | toInt }}% {{ if $showMediaType }}| {{ $mediaTypeUpper }}{{ end }}</a></p>
              {{ if $showMediaDesc }}<p class="color-subdue size-h4 text-truncate-2-lines" title={{ .String "overview" }}>{{ .String "overview" }}</p>{{ end }}
            </div>
          </li>
        {{ end }}
        </ul>
      {{ else }}
        <details style="margin-top:0.5rem">
          <summary> Raw JSON:</summary>
          <pre stye="font-size:10px">
      {{ (printf "%+v" .JSON) }}
          </pre>
        </details>
      {{ end }}
    {{ end }}

- type: custom-api
  title: Overseerr Users Requests
  title-url: ${OVERSEERR_API_URL}/users
  cache: 1h
  options:
    collapse-after: 5
    max-users: 10
    api-base-url: ${OVERSEERR_API_URL}/api/v1
    api-key: ${OVERSEERR_API_KEY}
  template: |
    {{ $collapseAfter := .Options.IntOr "collapse-after" 5 }}
    {{ $maxUsers := .Options.IntOr "max-users" 10 }}
    {{ $apiBaseUrl := .Options.StringOr "api-base-url" "" }}
    {{ $apiKey := .Options.StringOr "api-key" "" }}

    {{ $listUsersUrl := printf "%s/user?sort=requests&take=%d" $apiBaseUrl $maxUsers }}
    {{ $users := newRequest $listUsersUrl 
      | withHeader "Accept" "application/json"
      | withHeader "X-Api-Key" $apiKey
      | getResponse }}

    <ul class="list list-gap-10 collapsible-container" data-collapse-after="{{ $collapseAfter }}">
      {{ range $users.JSON.Array "results" }}
        {{ $userId := .String "id" }}
        {{ $username := .String "displayName" }}
        {{ if eq $username "" }}{{ $username = .String "username" }}{{ end }}
        {{ $avatar := .String "avatar" }}

        {{ $usersRequestsUrl := printf "%s/user/%s/requests?take=1" $apiBaseUrl $userId }}
        {{ $stats := newRequest $usersRequestsUrl
          | withHeader "Accept" "application/json"
          | withHeader "X-Api-Key" $apiKey
          | getResponse }}

        {{ $requestCount := $stats.JSON.Int "pageInfo.results" }}

        <li class="flex items-center gap-10">
          <img src="{{ $avatar }}" alt="{{ $username }}" style="width: 32px; height: 32px; border-radius: 50%; background-color: var(--color-background-soft); object-fit: cover;">
          <div class="shrink min-width-0">
            <strong class="block text-truncate color-primary">{{ $username }}</strong>
            <div class="size-small color-subdue">
              {{ $requestCount }} {{ if eq $requestCount 1 }}request{{ else }}requests{{ end }}
            </div>
          </div>
        </li>
      {{ end }}

      {{ if eq (len ($users.JSON.Array "results")) 0 }}
        <li>No users found. Check your API URL and Key.</li>
      {{ end }}
    </ul>

- type: custom-api
  title: PeaNUT UPS Status
  url: http://${PEANUT_URL}/api/v1/devices/${PEANUT_DEVICE}
  method: GET
  cache: 10m
  headers:
    Accept: application/json
    Authorization: "Basic ${PEANUT_AUTH}"
  template: |
      {{ $j := .JSON }}
      {{ $batteryCharge   := $j.Int  "battery\\.charge" }}
      {{ $batteryRuntime  := $j.Int  "battery\\.runtime" }}
      {{ $batteryVoltage  := $j.Float "battery\\.voltage" }}
      {{ $deviceModel     := $j.Int  "device\\.model" }}
      {{ $upsLoad         := $j.Int  "ups\\.load" }}
      {{ $upsNominalPower  := $j.Int  "ups\\.realpower\\.nominal" }}
      {{ $currentLoad := div (mul $upsLoad $upsNominalPower) 100 }}
      <div style="font-family:Arial,sans-serif;color:#f5f5f5;line-height:1.5;max-width:300px;">
        <p style="margin:4px 0;font-size:1.1em;">🔋 Battery: <strong>{{ printf "%d%%" $batteryCharge}}</strong></p>
        <p style="margin:4px 0;font-size:1.1em;">⏱️ Runtime: <strong>{{ printf "%d min" (div $batteryRuntime 60) }}</strong></p>
        <p style="margin:4px 0;font-size:1.1em;">⚡ Voltage: <strong>{{ printf "%.1f V" $batteryVoltage }}</strong></p>
        <p style="margin:4px 0;font-size:1.1em;">📟 Model: <strong>{{ printf "%d VA" $deviceModel }}</strong></p>
        <p style="margin:4px 0;font-size:1.1em;">🏋️ Load: <strong>{{ printf "%d%%" $upsLoad  }}</strong></p>
        <p style="margin:4px 0;font-size:1.1em;">⚙️ Nominal: <strong>{{ printf "%d W" $upsNominalPower }}</strong></p>
        <hr style="border:none;border-top:1px solid #ddd;margin:8px 0;max-width:150px">
        <p style="margin:4px 0;font-size:1.1em;">🔌 Current: <strong>{{ printf "%d W" $currentLoad }}</strong></p>
      </div>

- type: custom-api
  title: Prowlarr Indexers
  cache: 1m
  options:
    url: "${PROWLARR_URL}"
    base-url: ${PROWLARR_API_URL}
    api-key: ${PROWLARR_KEY}
    collapse-after: ${PROWLARR_COLLAPSE_AFTER}
  template: |
    {{ $apiBaseUrl := .Options.StringOr "base-url" "" }}
    {{ $key := .Options.StringOr "api-key" "" }}
    {{ $url := .Options.StringOr "url" "" }}
    {{ $collapseAfter := .Options.IntOr "collapse-after" 5 }}

    {{ if or (eq $apiBaseUrl "") (eq $key "") (eq $url "") }}
      <div class="widget-error-header">
          <div class="color-negative size-h3">ERROR</div>
          <svg class="widget-error-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
            <path stroke-linecap="round" stroke-linejoin="round" d="M12 9v3.75m-9.303 3.376c-.866 1.5.217 3.374 1.948 3.374h14.71c1.73 0 2.813-1.874 1.948-3.374L13.949 3.378c-.866-1.5-3.032-1.5-3.898 0L2.697 16.126ZM12 15.75h.007v.008H12v-.008Z"></path>
          </svg>
        </div>
        <p class="break-all">
          Some options are not set or malformed
            <table style="border-spacing: 1rem;">
              <tr>
                <td><strong>PROWLARR_URL & PROWLARR_API_URL</strong> <br/> should include http(s):// and port if needed</td>
              </tr>
              <tr>
                <td><strong>PROWLARR_KEY</strong> <br/> must be set (Settings > General > Security)</td>
              </tr>
            </table> 
        </p>
    {{ else }}

      {{ $indexUrl := printf "%s/api/v1/indexer" $apiBaseUrl }}

      {{ $indexData := newRequest $indexUrl
        | withHeader "Accept" "application/json"
        | withHeader "X-Api-Key" $key
        | getResponse }}

      {{ if eq $indexData.Response.StatusCode 200 }}
        <style>
          .prowlarr-indexers .prowlarr-index-item
          {
            align-items: center;        
          }
          .prowlarr-indexers .prowlarr-index-item > span{
            text-transform: capitalize;
            background: var(--color-background);
            padding: 0.2rem 0.75rem;
            border: 1px solid var(--color-widget-content-border);
            border-radius: var(--border-radius);
            font-size: var(--font-size-tiny);
          }
        </style>

        <ul class="prowlarr-indexers list list-gap-10 collapsible-container" data-collapse-after="{{ $collapseAfter }}">

          {{ range $indexData.JSON.Array "" }}
            {{ $isEnabled := .String "enable" }}

            <li class="flex items-center gap-12 prowlarr-index-item">
              <a href="{{ $url }}" target="_blank" class="size-title-dynamic color-highlight text-truncate block grow">{{ .String "name" }}</a>
              <span>{{ .String "privacy" }}</span>
              {{ if eq $isEnabled "true" }}
                <div class="margin-left-auto shrink-0" data-popover-type="text" data-popover-position="above" data-popover-text="Enabled" aria-label="Enabled">
                  <div class="monitor-site-status-icon-compact" title="Enabled">
                    <svg fill="var(--color-positive)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                      <path fill-rule="evenodd" d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5Z" clip-rule="evenodd"></path>
                    </svg>
                  </div>
                </div>
              {{ else }}
                <div class="margin-left-auto shrink-0" data-popover-type="text" data-popover-position="above" data-popover-text="Disabled" aria-label="Disabled">
                  <div class="monitor-site-status-icon-compact" title="Disabled">
                    <svg fill="var(--color-negative)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
                      <path fill-rule="evenodd" d="M8.485 2.495c.673-1.167 2.357-1.167 3.03 0l6.28 10.875c.673 1.167-.17 2.625-1.516 2.625H3.72c-1.347 0-2.189-1.458-1.515-2.625L8.485 2.495ZM10 5a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 10 5Zm0 9a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z" clip-rule="evenodd"></path>
                    </svg>
                  </div>
                </div>
              {{ end }}

            </li>
          {{ end }}

        </ul>
      {{ else }}
        <p>Failed to fetch data (Status: {{ $indexData.Response.StatusCode }})</p>
      {{ end }}

    {{ end }}

- type: custom-api
  title: Proxmox Backup Server
  cache: 5m
  allow-insecure: true
  options:
    uptime-mode: duration  # relative | duration
    collapse-after: 5
  template: |
    {{ $statusRes := newRequest "https://${PBS_HOST}/api2/json/nodes/localhost/status" | withHeader "Authorization" "${PBS_TOKEN}" | getResponse }}
    {{ $datastoresRes := newRequest "https://${PBS_HOST}/api2/json/status/datastore-usage" | withHeader "Authorization" "${PBS_TOKEN}" | getResponse }}
    {{ $tasksRes := newRequest "https://${PBS_HOST}/api2/json/nodes/localhost/tasks" | withHeader "Authorization" "${PBS_TOKEN}" | getResponse }}
    {{ $pveVMs := newRequest "https://${PROXMOXVE_URL}/api2/json/cluster/resources?type=vm" | withHeader "Authorization" "PVEAPIToken=${PROXMOXVE_KEY}" | getResponse }}

    {{ if eq $statusRes.Response.StatusCode 200 }}
      {{ $data := $statusRes.JSON.Get "data" }}
      {{ $cpuUsage := mul ($data.Float "cpu") 100.0 }}
      {{ $memPercent := mul (div ($data.Float "memory.used") ($data.Float "memory.total")) 100.0 }}
      {{ $rootPercent := mul (div ($data.Float "root.used") ($data.Float "root.total")) 100.0 }}
      {{ $uptimeSec := $data.Float "uptime" }}
      {{ $uptimeDays := div $uptimeSec 86400.0 }}

      <div class="pbs-container">
        <style>
          .pbs-container { display: flex; flex-direction: column; gap: 0.75rem; }
          .pbs-server { display: flex; flex-direction: column; gap: 0.5rem; padding: 0.75rem; background: var(--color-widget-background); border-radius: 0.5rem; border: 1px solid var(--color-separator); }
          .pbs-server-info { display: flex; justify-content: space-between; align-items: center; }
          .pbs-server-details { display: flex; flex-direction: column; gap: 0.25rem; }
          .pbs-server-name { font-weight: 700; font-size: 1.1em; color: var(--color-highlight); }
          .pbs-server-uptime { font-size: 0.85em; color: var(--color-text-subdue); }
          .pbs-server-icon { width: 2rem; height: 2rem; }
          .pbs-server-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.75rem; margin-top: 0.5rem; }
          .pbs-stat-box { display: flex; flex-direction: column; gap: 0.25rem; }
          .pbs-stat-header { display: flex; justify-content: space-between; align-items: center; font-size: 0.9em; }
          .pbs-stat-label { font-weight: 600; }
          .pbs-stat-value { color: var(--color-highlight); font-size: 0.85em; }
          .pbs-progress-bar { width: 100%; height: 4px; background: var(--color-separator); border-radius: 2px; overflow: hidden; }
          .pbs-progress-fill { height: 100%; transition: width 0.3s ease; }
          .usage-normal { background: var(--color-primary); }
          .usage-warning { background: #f59e0b; }
          .usage-critical { background: var(--color-negative); }
          .pbs-section { margin-top: 0.5rem; }
          .pbs-section-title { font-weight: 600; font-size: 0.95em; margin-bottom: 0.5rem; color: var(--color-text-subdue); }
          .pbs-datastores { display: flex; flex-direction: column; gap: 0.5rem; }
          .pbs-datastore { display: flex; justify-content: space-between; padding: 0.5rem; background: var(--color-widget-background); border-radius: 0.375rem; border: 1px solid var(--color-separator); font-size: 0.9em; }
          .pbs-ds-name { font-weight: 500; }
          .pbs-ds-usage { color: var(--color-text-subdue); font-size: 0.85em; }
          .pbs-backup-jobs { display: flex; flex-direction: column; gap: 0.5rem; }
          .pbs-backup-job { display: flex; align-items: center; justify-content: space-between; padding: 0.5rem; background: var(--color-widget-background); border-radius: 0.375rem; border: 1px solid var(--color-separator); }
          .pbs-job-name { font-weight: 500; font-size: 0.9em; flex: 1; }
          .pbs-job-status { display: flex; gap: 0.4rem; }
          .pbs-status-icon { font-size: 1.4em; font-weight: bold; line-height: 1; }
          .status-ok { color: var(--color-positive); }
          .status-error { color: var(--color-negative); }
        </style>
        <div class="pbs-server">
          <div class="pbs-server-info">
            <div class="pbs-server-details">
              <div class="pbs-server-name">Proxmox Backup Server</div>
              <div class="pbs-server-uptime">Uptime: {{ printf "%.0f" $uptimeDays }} days</div>
            </div>
            <svg class="pbs-server-icon" stroke="var(--color-positive)" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5">
              <path stroke-linecap="round" stroke-linejoin="round" d="M21.75 17.25v-.228a4.5 4.5 0 0 0-.12-1.03l-2.268-9.64a3.375 3.375 0 0 0-3.285-2.602H7.923a3.375 3.375 0 0 0-3.285 2.602l-2.268 9.64a4.5 4.5 0 0 0-.12 1.03v.228m19.5 0a3 3 0 0 1-3 3H5.25a3 3 0 0 1-3-3m19.5 0a3 3 0 0 0-3-3H5.25a3 3 0 0 0-3 3m16.5 0h.008v.008h-.008v-.008Zm-3 0h.008v.008h-.008v-.008Z" />
            </svg>
          </div>

          <div class="pbs-server-stats">
            <div class="pbs-stat-box">
              <div class="pbs-stat-header">
                <span class="pbs-stat-label">CPU</span>
                <span class="pbs-stat-value">{{ printf "%.0f" $cpuUsage }}%</span>
              </div>
              <div class="pbs-progress-bar">
                <div class="pbs-progress-fill {{ if lt $cpuUsage 70.0 }}usage-normal{{ else if lt $cpuUsage 90.0 }}usage-warning{{ else }}usage-critical{{ end }}" style="width: {{ printf "%.0f" $cpuUsage }}%"></div>
              </div>
            </div>

            <div class="pbs-stat-box">
              <div class="pbs-stat-header">
                <span class="pbs-stat-label">RAM</span>
                <span class="pbs-stat-value">{{ printf "%.0f" $memPercent }}%</span>
              </div>
              <div class="pbs-progress-bar">
                <div class="pbs-progress-fill {{ if lt $memPercent 70.0 }}usage-normal{{ else if lt $memPercent 90.0 }}usage-warning{{ else }}usage-critical{{ end }}" style="width: {{ printf "%.0f" $memPercent }}%"></div>
              </div>
            </div>

            <div class="pbs-stat-box">
              <div class="pbs-stat-header">
                <span class="pbs-stat-label">DISK</span>
                <span class="pbs-stat-value">{{ printf "%.0f" $rootPercent }}%</span>
              </div>
              <div class="pbs-progress-bar">
                <div class="pbs-progress-fill {{ if lt $rootPercent 70.0 }}usage-normal{{ else if lt $rootPercent 90.0 }}usage-warning{{ else }}usage-critical{{ end }}" style="width: {{ printf "%.0f" $rootPercent }}%"></div>
              </div>
            </div>
          </div>
        </div>

        {{ if eq $datastoresRes.Response.StatusCode 200 }}
          <div class="pbs-section">
            <div class="pbs-section-title">Datastores</div>
            <div class="pbs-datastores">
              {{ range $datastoresRes.JSON.Array "data" }}
                {{ $dsName := .String "store" }}
                {{ $dsTotal := div (.Float "total") 1073741824.0 }}
                {{ $dsUsed := div (.Float "used") 1073741824.0 }}
                {{ $dsPercent := mul (div (.Float "used") (.Float "total")) 100.0 }}

                <div class="pbs-datastore">
                  <div>
                    <div class="pbs-ds-name">{{ $dsName }}</div>
                    <div class="pbs-ds-usage">{{ printf "%.0f" $dsUsed }} / {{ printf "%.0f" $dsTotal }} GB ({{ printf "%.1f" $dsPercent }}%)</div>
                  </div>
                </div>
              {{ end }}
            </div>
          </div>
        {{ end }}
        {{ if eq $tasksRes.Response.StatusCode 200 }}
          <div class="pbs-section">
            <div class="pbs-section-title">Backup Jobs (Last 3 Runs)</div>
            {{ $tasks := $tasksRes.JSON.Array "data" }}

            <div class="pbs-backup-jobs">
              {{/* Iterate through all backup tasks */}}
              {{ range $outerIdx, $outerTask := $tasks }}
                {{ if eq ($outerTask.String "worker_type") "backup" }}
                  {{ $workerId := $outerTask.String "worker_id" }}

                  {{/* Check if this worker_id was already processed */}}
                  {{ $isFirstOccurrence := true }}
                  {{ range $innerIdx, $innerTask := $tasks }}
                    {{ if lt $innerIdx $outerIdx }}
                      {{ if and (eq ($innerTask.String "worker_type") "backup") (eq ($innerTask.String "worker_id") $workerId) }}
                        {{ $isFirstOccurrence = false }}
                      {{ end }}
                    {{ end }}
                  {{ end }}

                  {{/* Only render if this is the first occurrence */}}
                  {{ if $isFirstOccurrence }}
                    {{/* Display the worker_id as name (or try to match with VM name) */}}
                    {{ $displayName := $workerId }}

                    {{/* Try to extract VM ID from worker_id and find name */}}
                    {{ if eq $pveVMs.Response.StatusCode 200 }}
                      {{ range $pveVMs.JSON.Array "data" }}
                        {{ $vmid := printf "%.0f" (.Float "vmid") }}
                        {{/* Check if worker_id ends with this vmid */}}
                        {{ if ge (len $workerId) (len $vmid) }}
                          {{ $endPart := slice $workerId (sub (len $workerId) (len $vmid)) }}
                          {{ if eq $endPart $vmid }}
                            {{ $displayName = .String "name" }}
                          {{ end }}
                        {{ end }}
                      {{ end }}
                    {{ end }}

                    {{/* Collect up to 3 backup statuses for this worker_id */}}
                    {{ $count := 0 }}
                    <div class="pbs-backup-job">
                      <div class="pbs-job-name">{{ $displayName }}</div>
                      <div class="pbs-job-status">
                        {{ range $tasks }}
                          {{ if and (eq (.String "worker_type") "backup") (eq (.String "worker_id") $workerId) }}
                            {{ if lt $count 3 }}
                              {{ if eq (.String "status") "OK" }}
                                <span class="pbs-status-icon status-ok">✓</span>
                              {{ else }}
                                <span class="pbs-status-icon status-error">✗</span>
                              {{ end }}
                              {{ $count = add $count 1 }}
                            {{ end }}
                          {{ end }}
                        {{ end }}
                      </div>
                    </div>
                  {{ end }}
                {{ end }}
              {{ end }}
            </div>
          </div>
        {{ end }}


      </div>
    {{ else }}
      <div style="color: var(--color-negative); padding: 1rem;">
        Failed to connect to PBS<br>
        Status: {{ $statusRes.Response.StatusCode }}
      </div>
    {{ end }}

- type: custom-api
  title: Proxmox-VE Resources
  cache: 1m
  url: ${PROXMOX_URL}/api2/json/cluster/resources
  allow-insecure: true
  headers:
    Accept: application/json
    Authorization: ${PROXMOX_TOKEN}
  options:
    # Enable or disable charts for RAM, CPU, and Disk usage
    cpu_graph: true 
    disk_graph: true
    ram_graph: true
  template: |
    <style>
      .proxmox-container { font-size: 0.9em; }
      .resource-header, .resource-row { display: flex; border-collapse: collapse; align-items: center; gap: 10px; padding: 4px 0;}
      .resource-row { text-transform: lowercase;}
      .resource-header { text-transform: uppercase; font-size: 1em; font-weight: bold; color: var(--color-primary); border-bottom: 1px solid var(--color-primary); margin-bottom: 1px;}
      .col { min-width: 0; margin-right: 15px; }
      .col-item { flex: 1.5; color: var(--color-primary);}
      .col-type { flex: 1; }
      .col-ram { flex: 2; }
      .col-cpu { flex: 2; }
      .col-disk { flex: 2; }
      .col-status { flex: 0.5; text-align: center; }
      .server-type { padding: 2px 6px; border-radius: 4px; text-transform: lowercase; }
      .stat-header { display: flex; justify-content: space-between; align-items: flex-end; font-size: 0.85em;}
      .stat-percent { font-weight: 500;}
      .status-indicator { width: 8px; height: 8px; border-radius: 50%; display: inline-block; margin-left: 4px;}
      .indicator-positive { background-color: var(--color-positive); }
      .indicator-negative { background-color: var(--color-negative); }
    </style>

    {{ if eq .Response.StatusCode 200 }}
      <div class="proxmox-container">
        {{- $filteredResources := .JSON.Array "data.#(type!=\"node\" and type!=\"sdn\")#" -}}
        {{- $sortedResources := sortByString "type" "asc" $filteredResources -}}
        {{- $bytesInGB := toFloat 1073741824 -}}

        <div class="resource-header">
          <div class="col col-item">ITEM</div>
          <div class="col col-type">TYPE</div>
          {{ if .Options.BoolOr "ram_graph" true }}<div class="col col-ram">RAM</div>{{ end }}
          {{ if .Options.BoolOr "cpu_graph" true }}<div class="col col-cpu">CPU</div>{{ end }}
          {{ if .Options.BoolOr "disk_graph" true }}<div class="col col-disk">DISK</div>{{ end }}
          <div class="col col-status">STATUS</div>
        </div>

        {{- range $sortedResources -}}
          {{- $type := .String "type" -}}
            {{ if and (ne $type "node") (ne $type "sdn") }}
              <div class="resource-row">

                <div class="col col-item" title="{{ if .Exists "name" }}{{ .String "name" }}{{ else }}{{ .String "storage" }}{{ end }}">
                  {{ if .Exists "name" }}{{ .String "name" }}{{ else }}{{ .String "storage" }}{{ end }}
                </div>

                <div class="col col-type">
                  <span class="server-type">{{ $type }}</span>
                </div>

                {{ if $.Options.BoolOr "ram_graph" true }}
                  <div class="col col-ram">
                    {{- if and (or (eq $type "qemu") (eq $type "lxc")) (gt (.Float "maxmem") 0.0) -}}
                      <div data-popover-type="html">
                        <div data-popover-html>Usage: {{ printf "%.1f" (div (.Float "mem") $bytesInGB) }}GB<br>Total: {{ printf "%.1f" (div (.Float "maxmem") $bytesInGB) }}GB</div>
                        <div class="stat-header"><span class="stat-percent">{{ mul (div (.Float "mem") (.Float "maxmem")) 100 | toInt }}%</span></div>
                        <div class="progress-bar"><div class="progress-value{{ if ge (mul (div (.Float "mem") (.Float "maxmem")) 100 | toInt) 80 }} progress-value-notice{{ end }}" style="--percent: {{ mul (div (.Float "mem") (.Float "maxmem")) 100 | toInt }}"></div></div>
                      </div>
                    {{- end -}}
                  </div>
                {{ end }}

                {{ if $.Options.BoolOr "cpu_graph" true }}
                  <div class="col col-cpu">
                    {{- if and (or (eq $type "qemu") (eq $type "lxc")) -}}
                      {{- $percentCPU := mul (.Float "cpu") 100 | toInt -}}
                      <div data-popover-type="html">
                        <div data-popover-html>Load: {{ $percentCPU }}%<br>Cores: {{ .Int "maxcpu" }}</div>
                        <div class="stat-header"><span class="stat-percent">{{ $percentCPU }}%</span></div>
                        <div class="progress-bar"><div class="progress-value{{ if ge $percentCPU 80 }} progress-value-notice{{ end }}" style="--percent: {{ $percentCPU }}"></div></div>
                      </div>
                    {{- end -}}
                  </div>
                {{ end }}

                {{ if $.Options.BoolOr "disk_graph" true }}
                  <div class="col col-disk">
                    {{- if and (or (eq $type "lxc") (eq $type "storage")) (gt (.Float "maxdisk") 0.0) -}}
                      <div data-popover-type="html">
                        <div data-popover-html>Usage: {{ printf "%.1f" (div (.Float "disk") $bytesInGB) }}GB<br>Total: {{ printf "%.1f" (div (.Float "maxdisk") $bytesInGB) }}GB</div>
                        <div class="stat-header"><span class="stat-percent">{{ mul (div (.Float "disk") (.Float "maxdisk")) 100 | toInt }}%</span></div>
                        <div class="progress-bar"><div class="progress-value{{ if ge (mul (div (.Float "disk") (.Float "maxdisk")) 100 | toInt) 80 }} progress-value-notice{{ end }}" style="--percent: {{ mul (div (.Float "disk") (.Float "maxdisk")) 100 | toInt }}"></div></div>
                      </div>
                    {{- end -}}
                  </div>
                {{ end }}

                <div class="col col-status">
                  {{- $status := .String "status" -}}
                  <span class="status-indicator {{ if or (eq $status "running") (eq $status "available") (eq $status "ok") (eq $status "online")}}indicator-positive{{ else }}indicator-negative{{ end }}"
                        data-popover-type="text" data-popover-text="{{ $status }}">
                  </span>
                </div>
              </div>
            {{ end }}
        {{- end -}}
      </div>
    {{ else }}
      <p>Failed: {{ .Response.Status }}</p>
    {{ end }}

- type: custom-api
  title: qBittorrent
  cache: 10s
  options:
    view: "detailed"   # "basic" or "detailed"
    mode: "upload"    # "default" or "upload"
  subrequests:
    transfer:
      url: http://${QBITTORRENT_IP}/api/v2/transfer/info
    seeding:
      url: http://${QBITTORRENT_IP}/api/v2/torrents/info
      parameters:
        filter: seeding
    leeching:
      url: http://${QBITTORRENT_IP}/api/v2/torrents/info
      parameters:
        filter: downloading
  template: |
    {{ $transfer := .Subrequest "transfer" }}
    {{ $seeding := .Subrequest "seeding" }}
    {{ $leeching := .Subrequest "leeching" }}

    {{ if and (eq $transfer.Response.StatusCode 200) (eq $seeding.Response.StatusCode 200) (eq $leeching.Response.StatusCode 200) }}

      {{ $isDetailed := eq (.Options.StringOr "view" "detailed") "detailed" }}
      {{ $mode := .Options.StringOr "mode" "default" }}

      {{ if $isDetailed }}
      <!-- Detailed View -->
      <div class="list" style="--list-gap: 15px;">
        <div class="flex justify-between text-center">
          <div>
            {{ $dlSpeed := $transfer.JSON.Float "dl_info_speed" }}
            {{ if eq $mode "upload" }}
              <div class="color-highlight size-h3">{{ printf "%.1f MB/s" (div $dlSpeed 1000000.0) }}</div>
            {{ else }}
              {{ if lt $dlSpeed 1048576.0 }}
                <div class="color-highlight size-h3">{{ printf "%.0f KiB/s" (div $dlSpeed 1024.0) }}</div>
              {{ else }}
                <div class="color-highlight size-h3">{{ printf "%.1f MiB/s" (div $dlSpeed 1048576.0) }}</div>
              {{ end }}
            {{ end }}
            <div class="size-h6">DOWNLOADING</div>
          </div>

          {{ if eq $mode "upload" }}
          <div>
            {{ $ulSpeed := $transfer.JSON.Float "up_info_speed" }}
            <div class="color-highlight size-h3">{{ printf "%.1f MB/s" (div $ulSpeed 1000000.0) }}</div>
            <div class="size-h6">UPLOADING</div>
          </div>
          {{ end }}

          <div>
            <div class="color-highlight size-h3">{{ len ($seeding.JSON.Array "") }}</div>
            <div class="size-h6">SEEDING</div>
          </div>

          {{ if eq $mode "default" }}
          <div>
            <div class="color-highlight size-h3">{{ len ($leeching.JSON.Array "") }}</div>
            <div class="size-h6">LEECHING</div>
          </div>
          {{ end }}
        </div>

        <!-- Downloading list -->
        {{ $downloadingTorrents := $leeching.JSON.Array "" }}
        {{ if gt (len $downloadingTorrents) 0 }}
          <div style="margin-top: 15px;">
            <ul class="list collapsible-container" data-collapse-after="0" style="--list-gap: 15px;">
              {{ range $t := $downloadingTorrents }}
                {{ $state := $t.String "state" }}
                {{ $icon := "?" }}
                {{ if ge ($t.Int "completed") ($t.Int "size") }}{{ $icon = "✔" }}
                {{ else if eq $state "downloading" "forcedDL" }}{{ $icon = "↓" }}
                {{ else if eq $state "pausedDL" "stoppedDL" "pausedUP" "stalledDL" "stalledUP" "queuedDL" "queuedUP" }}{{ $icon = "❚❚" }}
                {{ else if eq $state "error" "missingFiles" }}{{ $icon = "!" }}
                {{ else if eq $state "checkingDL" "checkingUP" "allocating" }}{{ $icon = "…" }}
                {{ else if eq $state "checkingResumeData" }}{{ $icon = "⟳" }}
                {{ end }}

                <li class="flex items-center" style="gap: 10px;">
                  <div class="size-h4" style="flex-shrink: 0;">{{ $icon }}</div>
                  <div style="flex-grow: 1; min-width: 0;">
                    <div class="text-truncate color-highlight">{{ $t.String "name" }}</div>
                    <div title="{{ $t.Float "progress" | mul 100 | printf "%.1f" }}%" style="background: rgba(128, 128, 128, 0.2); border-radius: 5px; height: 6px; margin-top: 5px; overflow: hidden;">
                      <div style="width: {{ $t.Float "progress" | mul 100 }}%; background-color: var(--color-positive); height: 100%; border-radius: 5px;"></div>
                    </div>
                  </div>
                  <div style="flex-shrink: 0; text-align: right; width: 80px;">
                    {{ $dlSpeed := $t.Float "dlspeed" }}
                    <div class="size-sm color-paragraph">
                      {{ if eq $mode "upload" }}
                        {{ if lt $dlSpeed 1000.0 }}--{{ else }}{{ printf "%.1f MB/s" (div $dlSpeed 1000000.0) }}{{ end }}
                      {{ else }}
                        {{ if lt $dlSpeed 1024.0 }}--{{ else if lt $dlSpeed 1048576.0 }}{{ printf "%.0f KiB/s" (div $dlSpeed 1024.0) }}{{ else }}{{ printf "%.1f MiB/s" (div $dlSpeed 1048576.0) }}{{ end }}
                      {{ end }}
                    </div>
                    {{ $eta := $t.Int "eta" }}
                    <div class="size-sm color-paragraph">
                      {{ if eq $eta 8640000 }}∞
                      {{ else if gt $eta 3600 }}{{ printf "%dh %dm" (div $eta 3600) (mod (div $eta 60) 60) }}
                      {{ else if gt $eta 0 }}{{ printf "%dm" (div $eta 60) }}
                      {{ else }}--{{ end }}
                    </div>
                  </div>
                </li>
              {{ end }}
            </ul>
          </div>
        {{ end }}

        <!-- Seeding list -->
        {{ if eq $mode "upload" }}
          {{ $seedingTorrents := $seeding.JSON.Array "" }}
          {{ if gt (len $seedingTorrents) 0 }}
            <div style="margin-top: 20px;">
              <ul class="list collapsible-container" data-collapse-after="0" style="--list-gap: 15px;">
                {{ range $t := $seedingTorrents }}
                  {{ $state := $t.String "state" }}
                  {{ $icon := "↑" }}
                  {{ if eq $state "pausedUP" "stoppedUP" "stalledUP" "queuedUP" }}{{ $icon = "❚❚" }}
                  {{ else if eq $state "error" "missingFiles" }}{{ $icon = "!" }}
                  {{ else if eq $state "checkingUP" }}{{ $icon = "…" }}
                  {{ else if eq $state "checkingResumeData" }}{{ $icon = "⟳" }}
                  {{ end }}

                  <li class="flex items-center" style="gap: 10px;">
                    <div class="size-h4" style="flex-shrink: 0;">{{ $icon }}</div>
                    <div style="flex-grow: 1; min-width: 0;">
                      <div class="text-truncate color-highlight">{{ $t.String "name" }}</div>
                      <div class="size-sm color-paragraph">
                        Ratio: {{ printf "%.2f" ($t.Float "ratio") }} | 
                        Size: {{ printf "%.1f GB" (div ($t.Float "size") 1073741824.0) }}
                      </div>
                    </div>
                    <div style="flex-shrink: 0; text-align: right; width: 80px;">
                      {{ $ulSpeed := $t.Float "upspeed" }}
                      <div class="size-sm color-paragraph">
                        {{ if lt $ulSpeed 1000.0 }}--{{ else }}{{ printf "%.1f MB/s" (div $ulSpeed 1000000.0) }}{{ end }}
                      </div>
                      <div class="size-sm color-paragraph">Upload</div>
                    </div>
                  </li>
                {{ end }}
              </ul>
            </div>
          {{ end }}
        {{ end }}

      </div>

      {{ else }}
      <!-- Basic View -->
      <div class="flex justify-between text-center">
        <div>
          {{ $dlSpeed := $transfer.JSON.Float "dl_info_speed" }}
          <div class="color-highlight size-h3">{{ printf "%.1f MB/s" (div $dlSpeed 1000000.0) }}</div>
          <div class="size-h6">DOWNLOADING</div>
        </div>
        {{ if eq $mode "upload" }}
        <div>
          {{ $ulSpeed := $transfer.JSON.Float "up_info_speed" }}
          <div class="color-highlight size-h3">{{ printf "%.1f MB/s" (div $ulSpeed 1000000.0) }}</div>
          <div class="size-h6">UPLOADING</div>
        </div>
        {{ end }}
        <div>
          <div class="color-highlight size-h3">{{ len ($seeding.JSON.Array "") }}</div>
          <div class="size-h6">SEEDING</div>
        </div>
        {{ if eq $mode "default" }}
        <div>
          <div class="color-highlight size-h3">{{ len ($leeching.JSON.Array "") }}</div>
          <div class="size-h6">LEECHING</div>
        </div>
        {{ end }}
      </div>
      {{ end }}

    {{ else }}
      <div class="color-negative text-center">
        <p>Error fetching qBittorrent data.</p>
        <p class="size-sm">Check URL and authentication bypass settings.</p>
      </div>
    {{ end }}

- type: custom-api
