          {{ if eq $status 1 }}
            {{ $colorClass = "color-positive" }}
            {{ $statusText = "Online" }}
          {{ else if eq $status 2 }}
            {{ $colorClass = "color-highlight" }}
            {{ $statusText = "Busy" }}
          {{ else if eq $status 3 }}
            {{ $colorClass = "color-primary" }}
            {{ $statusText = "Away" }}
          {{ else if eq $status 4 }}
            {{ $colorClass = "color-primary" }}
            {{ $statusText = "Snooze" }}
          {{ else if eq $status 5 }}
            {{ $colorClass = "color-primary" }}
            {{ $statusText = "Looking to Trade" }}
          {{ else if eq $status 6 }}
            {{ $colorClass = "color-primary" }}
            {{ $statusText = "Looking to Play" }}
          {{ end }}
          <li class="flex gap-10 items-start thumbnail-parent">
            <a href="{{ .String "profileurl" }}" style="width: 4.4rem;height: 4.4rem;border: 2px solid var(--color-text-subdue);padding: 2px;border-radius: 50%;position: relative;flex-shrink: 0;">
              <img class="thumbnail" style="aspect-ratio: 1; border-radius: 50%;" src="{{ .String "avatarmedium" }}" alt="Avatar" loading="lazy">
            </a>
            <div class="items-start">
              <a href="{{.String "profileurl"}}" title="{{.String "personname"}}" class="size-h3 block">{{ .String "personaname" }}</a>
              <span class="{{ $colorClass }}">
                {{ if .Exists "gameextrainfo" }}
                  {{ .String "gameextrainfo" }}
                {{ else }}
                  {{ $statusText }}
                  {{ if eq $status 0 }}
                    {{ if .Exists "lastlogoff" }}
                      for <span data-dynamic-relative-time="{{ .Int "lastlogoff" }}"></span>
                    {{ end }}
                  {{ end }}
                {{ end }}
              </span>
            </div>
          </li>
        {{ end }}
      {{ else }}
        <p class="color-negative">No player data found.</p>
      {{ end }}
    </ul>

- type: custom-api
  title: Sunrise & Sunset
  body-type: string
  cache: 12h
  options:
    location: ${WEATHER_LOCATION}
  template: |
    {{ $timeLayout := "3:04 PM" }}

    {{/* Step 1: geocode the location */}}
    {{ $loc := replaceAll " " "%20" (.Options.StringOr "location" "") }}
    {{ $geoUrl := printf "https://geocoding-api.open-meteo.com/v1/search?name=%s&count=1&language=en&format=json" $loc }}
    {{ $geo := newRequest $geoUrl | getResponse }}
    {{ $results := $geo.JSON.Array "results" }}

    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.0.0-beta3/css/all.min.css">

    {{ if eq (len $results) 0 }}
      <p class="color-paragraph">Location "{{ .Options.StringOr "location" "" }}" not found.</p>
    {{ else }}
      {{ $lat := $geo.JSON.String "results.0.latitude" }}
      {{ $lon := $geo.JSON.String "results.0.longitude" }}

      {{/* Step 2: today's sunrise/sunset/daylight from Open-Meteo */}}
      {{ $fcUrl := printf "https://api.open-meteo.com/v1/forecast?latitude=%s&longitude=%s&daily=sunrise,sunset,daylight_duration&forecast_days=1&timezone=auto" $lat $lon }}
      {{ $fc := newRequest $fcUrl | getResponse }}

      {{ $sunriseRaw := $fc.JSON.String "daily.sunrise.0" }}
      {{ $sunsetRaw  := $fc.JSON.String "daily.sunset.0" }}
      {{ $daylight   := $fc.JSON.Int    "daily.daylight_duration.0" }}

      {{ if or (eq $sunriseRaw "") (eq $sunsetRaw "") }}
        <p class="color-paragraph"><i class="fas fa-circle-exclamation"></i> No sunrise/sunset today (polar region).</p>
      {{ else }}
        {{ $sunrise := $sunriseRaw | parseTime "2006-01-02T15:04" }}
        {{ $sunset  := $sunsetRaw  | parseTime "2006-01-02T15:04" }}
        {{ $hours   := div $daylight 3600 }}
        {{ $mins    := div (mod $daylight 3600) 60 }}

        <div style="display:flex; justify-content:space-around; align-items:center; padding:0.5rem 0;">
          <div style="text-align:center;">
            <i class="fas fa-arrow-up" style="color: var(--color-positive); font-size: 14px; margin-right: 0.25rem;"></i>
            <i class="fas fa-sun" style="color: var(--color-text-highlight); font-size: 28px;"></i>
            <p class="size-h3 color-text-highlight">{{ $sunrise.Format $timeLayout }}</p>
            <p class="size-h6 color-paragraph">Sunrise</p>
          </div>
          <div style="text-align:center;">
            <i class="fas fa-clock" style="color: var(--color-paragraph); font-size: 22px;"></i>
            <p class="size-h3 color-text-highlight">{{ $hours }}h {{ $mins }}m</p>
            <p class="size-h6 color-paragraph">Daylight</p>
          </div>
          <div style="text-align:center;">
            <i class="fas fa-arrow-down" style="color: var(--color-negative); font-size: 14px; margin-right: 0.25rem;"></i>
            <i class="fas fa-moon" style="color: var(--color-text-highlight); font-size: 28px;"></i>
            <p class="size-h3 color-text-highlight">{{ $sunset.Format $timeLayout }}</p>
            <p class="size-h6 color-paragraph">Sunset</p>
          </div>
        </div>
      {{ end }}
    {{ end }}

- type: custom-api
  title: "Sync Status"
  cache: 300s                 # refresh interval
  headers:                   # auth for *every* request
    X-API-Key: ${SYNCTHING_API_KEY}
  # ---------------- Main request: discover folders ----------------
  url: "${SYNCTHING_URL}/rest/system/config"
  # ---------------- Sub-requests: one per folder ------------------
  subrequests:
    <FOLDER_1_ID>:
      url: "${SYNCTHING_URL}/rest/db/completion"
      parameters: { folder: "<FOLDER_1_ID>" }
      headers:    { X-API-Key: ${SYNCTHING_API_KEY} }
    <FOLDER_2_ID>:
      url: "${SYNCTHING_URL}/rest/db/completion"
      parameters: { folder: "<FOLDER_2_ID>" }
      headers:    { X-API-Key: ${SYNCTHING_API_KEY} }
  # ---------------- Options visible to the template ---------------
  options:
    debug: false             # switch to true to show JSON <details>
    folders:
      - id: <FOLDER_1_ID>
        name: "Backup Folder 1"
        enabled: true
      - id: <FOLDER_2_ID>
        name: "Backup Folder 2"
        enabled: true
  # ---------------- Template defined earlier ----------------------
  template: |-
    <!-- Syncthing folder-by-folder progress --------------------------------- -->
    {{ $debug   := or (.Options.debug) false }}
    {{ $folders := .Options.folders }}

    {{ if ne .Response.StatusCode 200 }}
      <!-- The *main* request failed (e.g. /rest/system/config).               -->
      <p class="text-danger">⚠️ Syncthing API unreachable ({{ .Response.Status }})</p>
    {{ else }}
      <ul class="list">
        {{ range $folders }}
          {{ $id   := .id }}
          {{ $name := .name }}
          {{ if .enabled }}
            {{ $r := $.Subrequest $id }}
            {{ if eq $r.Response.StatusCode 200 }}
              {{ $comp := $r.JSON.Float "completion" }}
              <li>
                <span class="{{ if eq $comp 100.0 }}text-success{{ else if gt $comp 0.0 }}text-info{{ else }}text-danger{{ end }}">
                  {{ if eq $comp 100.0 }}✔️
                  {{ else if gt $comp 0.0 }}🔄
                  {{ else }}⚠️
                  {{ end }}
                  {{ $name }} – 
                  {{ if eq $comp 100.0 }}
                    In Sync (100 %)
                  {{ else if gt $comp 0.0 }}
                    Syncing ({{ printf "%.1f" $comp }} %)
                  {{ else }}
                    Unreachable
                  {{ end }}
                </span>
              </li>
            {{ else }}
              <!-- Sub-request didn’t return 200 -->
              <li><span class="text-danger">⚠️ {{ $name }} – Unreachable</span></li>
            {{ end }}
          {{ end }}
        {{ end }}
      </ul>
    {{ end }}

    {{/* ---------- OPTIONAL DEBUG BLOCK ---------- */}}
    {{ if $debug }}
      <details style="margin-top:0.5rem">
        <summary>Debug – raw Syncthing JSON</summary>
        <pre style="font-size:10px">
    {{ (printf "%+v" .JSON) }}
        </pre>
      </details>
    {{ end }}

- type: custom-api
  cache: 5m
  title: Synology Disk Station
  options:
    nas-ip: "[IP]"
    nas-port: "[Port]"
    username: "[username]"
    password: "[password]"
  template: |
    {{ $baseUrl := concat "http://" (.Options.StringOr "nas-ip" "127.0.0.1") ":" (.Options.StringOr "nas-port" "5000") "/webapi/entry.cgi" }}
    {{ $auth := newRequest $baseUrl
        | withParameter "api" "SYNO.API.Auth"
        | withParameter "version" "6"
        | withParameter "method" "login" 
        | withParameter "account" (.Options.StringOr "username" "admin")
        | withParameter "passwd" (.Options.StringOr "password" "admin")
        | withParameter "session" "FileStation" 
        | withParameter "format" "sid" 
        | getResponse
    }}

    {{ $sid := $auth.JSON.String "data.sid" }}


    {{
      $storage := newRequest $baseUrl
        | withParameter "api" "SYNO.Core.System"
        | withParameter "method" "info"
        | withParameter "type" "storage"
        | withParameter "version" "1"
        | withParameter "_sid" $sid
        | getResponse
    }}

    {{
      $cpu := newRequest $baseUrl
        | withParameter "api" "SYNO.Core.System.Utilization"
        | withParameter "method" "get"
        | withParameter "version" "1"
        | withParameter "_sid" $sid
        | getResponse
    }}

    {{ if and (eq $storage.Response.StatusCode 200) (eq $cpu.Response.StatusCode 200) }}
      {{ $volInfo := index ($storage.JSON.Array "data.vol_info") 0 }}
      {{ $total := $volInfo.Float "total_size" }}
      {{ $used := $volInfo.Float "used_size" }}
      {{ $storagePercent := mul (div $used $total) 100 | toInt }}

      {{ $cpuPercent := $cpu.JSON.Int "data.cpu.user_load" }}
      {{ $ramPercent := $cpu.JSON.Int "data.memory.real_usage" }}
      {{ $ramTotalKB := $cpu.JSON.Float "data.memory.total_real" }}
      {{ $ramUsedKB := mul (div $ramTotalKB 100.0) ($ramPercent | toFloat) }}
      {{ $ramUsedMB := div $ramUsedKB 1000 }}
      {{ $ramUsedGB := div $ramUsedKB 1000000 }}
      {{ $ramTotalGB := div $ramTotalKB 1000000 }}

      <div class="flex justify-between text-center">
        <div>
          <div class="size-h3 color-highlight">{{ $cpuPercent }}%</div>
          <div class="size-h6">CPU</div>
        </div>
        <div>
          <div class="size-h3 color-highlight">{{ $ramPercent }}%</div>
          <div class="size-h6">RAM</div>
          <div class="size-h6 margin-top-5">
            {{ if ge $ramUsedGB 1.0 }}
              {{ $ramUsedGB | printf "%.1f" }}GB/{{ $ramTotalGB | printf "%.0f" }}GB
            {{ else }}
              {{ $ramUsedMB | printf "%.0f" }}MB/{{ $ramTotalGB | printf "%.0f" }}GB
            {{ end }}
          </div>
        </div>
        <div>
          <div class="size-h3 color-highlight">{{ $storagePercent }}%</div>
          <div class="size-h6">STORAGE</div>
          <div class="size-h6 margin-top-5">
            {{ div $used 1099511627776 | printf "%.2f" }}TB/{{ div $total 1099511627776 | printf "%.2f" }}TB
          </div>
        </div>
      </div>
    {{ else }}
      <p class="color-negative">Failed to fetch system data</p>
    {{ end }}

- type: custom-api
  title: Tailscale Device Status
  refresh-interval: 5s
  cache: 2s
  url: https://api.tailscale.com/api/v2/tailnet/${TAILSCALE_TAILNET}/devices
  headers:
    Authorization: "Bearer ${TAILSCALE_API_KEY}"
    Content-Type: application/json
  template: |
    {{ $found := false }}
    {{ range .JSON.Array "devices" }}
      {{ $ip0 := .String "addresses.0" }}
      {{ $ip1 := .String "addresses.1" }}
      {{ if or (eq $ip0 "${TAILSCALE_DEVICE_IP}") (eq $ip1 "${TAILSCALE_DEVICE_IP}") }}
        {{ $found = true }}
        <ul class="list list-gap-10">
          <li class="flex justify-between align-center">
            <span class="size-h6 color-paragraph">ADDRESS</span>
            <span class="size-h5 color-highlight">${TAILSCALE_DEVICE_IP}</span>
          </li>
          <li class="flex justify-between align-center">
            <span class="size-h6 color-paragraph">LAST SEEN</span>
            <span class="size-h5 color-highlight">
              {{ $lastSeen := .String "lastSeen" }}
              {{ if ne $lastSeen "" }}
                <span {{ parseRelativeTime "RFC3339" $lastSeen }}></span>
              {{ else }}
                Now
              {{ end }}
            </span>
          </li>
          <li class="flex justify-between align-center">
            <span class="size-h6 color-paragraph">EXPIRES</span>
            <span class="size-h5 color-highlight">
              {{ $expiry := .String "keyExpiry" }}
              {{ $disabled := .Bool "keyExpiryDisabled" }}
              {{ if or $disabled (eq $expiry "") (findMatch "^0001" $expiry) }}
                Never
              {{ else }}
                <span {{ parseRelativeTime "RFC3339" $expiry }}></span>
              {{ end }}
            </span>
          </li>
        </ul>
      {{ end }}
    {{ end }}
    {{ if not $found }}
      <div class="size-p color-subdue text-center">Device ${TAILSCALE_DEVICE_IP} not found in Tailnet</div>
    {{ end }}

- type: custom-api
  title: Tailscale Devices
  title-url: https://login.tailscale.com/admin/machines
  url: https://api.tailscale.com/api/v2/tailnet/-/devices
  headers:
    Authorization: Bearer ${TAILSCALE_API_KEY}
  cache: 10m
  options:
    # collapseAfter: 4
    # disableOfflineIndicator: true
    # disableUpdateIndicator: true
    # prioritiseTags: true
  template: |
    <style>
      .device-info-container-tailscale {
        position: relative;
        overflow: hidden;
        height: 1.5em;
      }

      .device-info-tailscale {
        display: flex;
        transition: transform 0.2s ease, opacity 0.2s ease;
      }

      .device-ip-tailscale {
        position: absolute;
        top: 0;
        left: 0;
        transform: translateY(-100%);
        opacity: 0;
        transition: transform 0.2s ease, opacity 0.2s ease;
      }

      .device-info-container-tailscale:hover .device-info-tailscale {
        transform: translateY(100%);
        opacity: 0;
      }

      .device-info-container-tailscale:hover .device-ip-tailscale {
        transform: translateY(0);
        opacity: 1;
      }

      .update-indicator-tailscale {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background-color: var(--color-primary);
        display: inline-block;
        margin-left: 4px;
        vertical-align: middle;
      }

      .offline-indicator-tailscale {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background-color: var(--color-negative);
        display: inline-block;
        margin-left: 4px;
        vertical-align: middle;
      }

      .device-name-container-tailscale {
        display: flex;
        align-items: center;
        gap: 8px;
      }

      .indicators-container-tailscale {
        display: flex;
        align-items: center;
        gap: 4px;
      }
    </style>
    <ul class="list list-gap-10 collapsible-container" data-collapse-after="{{ .Options.IntOr "collapseAfter" 3 }}">
      {{ range .JSON.Array "devices" }}
      <li>
        <div class="flex items-center gap-10">
          <div class="device-name-container-tailscale grow">
            <span class="size-h4 block text-truncate color-primary">
              {{ findMatch "^([^.]+)" (.String "name") }}
            </span>
            <div class="indicators-container-tailscale">
              {{ if and (not ($.Options.BoolOr "disableUpdateIndicator" false)) (.Bool "updateAvailable") }}
              <span class="update-indicator-tailscale" data-popover-type="text" data-popover-text="Update Available"></span>
              {{ end }}

              {{ if not ($.Options.BoolOr "disableOfflineIndicator" false) }}
              {{ $lastSeen := .String "lastSeen" | parseTime "rfc3339" }}
              {{ if not ($lastSeen.After (offsetNow "-10s")) }}
              {{ $lastSeenTimezoned := $lastSeen.In now.Location }}
              <span class="offline-indicator-tailscale" data-popover-type="text"
                data-popover-text="Offline - Last seen {{ $lastSeenTimezoned.Format " Jan 2 3:04pm" }}"></span>
              {{ end }}
              {{ end }}

            </div>
          </div>
        </div>
        <div class="device-info-container-tailscale">
          <ul class="list-horizontal-text device-info-tailscale">
            <li>{{ .String "os" }}</li>
            <li>
              {{ if and ($.Options.BoolOr "prioritiseTags" false) (.Exists "tags.0") }}
                {{ trimPrefix "tag:" (.String "tags.0") }}
              {{ else }}
                {{ .String "user" }}
              {{ end }}
            </li>
          </ul>
          <div class="device-ip-tailscale">
            {{ .String "addresses.0"}}
          </div>
        </div>
      </li>
      {{ end }}
    </ul>

