- type: group
  widgets:
    - type: custom-api
      title: Day
      body-type: string
      skip-json-validation: true
      cache: 1s
      template: |
        {{ $localTime := now }}
        {{ $secondsPerDay := 86400 }}
        {{ $elapsedSeconds := add (mul $localTime.Hour 3600) (mul $localTime.Minute 60) | add $localTime.Second }}
        {{ $dayProgress := div (mul $elapsedSeconds 100.0) $secondsPerDay }}

        {{ $gradient := "" }}
        {{ if lt $dayProgress 10.0 }}
          {{ $gradient = "#70a1ff" }}
        {{ else if lt $dayProgress 25.0 }}
          {{ $gradient = "#ff6b6b, #70a1ff" }}
        {{ else if lt $dayProgress 50.0 }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df" }}
        {{ else }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df, #70a1ff" }}
        {{ end }}

        <div style="font-family: sans-serif; text-align: center;">
          <div style="width: 100%; height: 12px; background: #23262F; border:1px solid gray; border-radius: 10px; overflow: hidden;">
            <div style="
              height: 100%;
              width: {{ $dayProgress }}%;
              background: linear-gradient(90deg, {{ $gradient }});
            "></div>
          </div>
          <div class="size-h1" style="margin-top: 6px;">{{ printf "%.2f" $dayProgress }}% of the day has passed</div>
        </div>

    - type: custom-api
      title: Month
      body-type: string
      skip-json-validation: true
      cache: 1s
      template: |
        {{ $localTime := now }}

        {{ $month := $localTime.Month }}
        {{ $dayOfMonth := $localTime.Day }}

        {{ $secondsToday := add (mul $localTime.Hour 3600) (mul $localTime.Minute 60) | add $localTime.Second }}
        {{ $fractionOfDay := div $secondsToday 86400.0 }}

        {{ $daysInMonth := 31 }}
        {{ if eq $month 2 }} {{ $daysInMonth = 28 }} {{ end }}
        {{ if or (eq $month 4) (eq $month 6) (eq $month 9) (eq $month 11) }} {{ $daysInMonth = 30 }} {{ end }}

        {{ $daysElapsed := add (sub $dayOfMonth 1) $fractionOfDay }}
        {{ $monthProgress := mul (div $daysElapsed $daysInMonth) 100.0 }}

        {{ $gradient := "" }}
        {{ if lt $monthProgress 10.0 }}
          {{ $gradient = "#70a1ff" }}
        {{ else if lt $monthProgress 25.0 }}
          {{ $gradient = "#ff6b6b, #70a1ff" }}
        {{ else if lt $monthProgress 50.0 }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df" }}
        {{ else }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df, #70a1ff" }}
        {{ end }}

        <div style="font-family: sans-serif; text-align: center;">
          <div style="width: 100%; height: 12px; background: #23262F; border:1px solid gray; border-radius: 10px; overflow: hidden;">
            <div style="
              height: 100%;
              width: {{ $monthProgress }}%;
              background: linear-gradient(90deg, {{ $gradient }});
            "></div>
          </div>
          <div class="size-h1" style="margin-top: 6px;">{{ printf "%.2f" $monthProgress }}% of the month has passed</div>
        </div>

    - type: custom-api
      title: Year
      body-type: string
      skip-json-validation: true
      cache: 1s
      template: |
        {{ $localTime := now }}

        {{ $secondsToday := add (mul $localTime.Hour 3600) (mul $localTime.Minute 60) | add $localTime.Second }}
        {{ $dayOfYear := $localTime.YearDay }}
        {{ $secondsElapsed := add (mul (sub $dayOfYear 1) 86400) $secondsToday }}

        {{ $totalSecondsInYear := mul 365 86400 }}
        {{ $yearProgress := div (mul $secondsElapsed 100.0) $totalSecondsInYear }}

        {{ $gradient := "" }}
        {{ if lt $yearProgress 10.0 }}
          {{ $gradient = "#70a1ff" }}
        {{ else if lt $yearProgress 25.0 }}
          {{ $gradient = "#ff6b6b, #70a1ff" }}
        {{ else if lt $yearProgress 50.0 }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df" }}
        {{ else }}
          {{ $gradient = "#ff6b6b, #f8e71c, #7ed6df, #70a1ff" }}
        {{ end }}

        <div style="font-family: sans-serif; text-align: center;">
          <div style="width: 100%; height: 12px; background: #23262F; border:1px solid gray; border-radius: 10px; overflow: hidden;">
            <div style="
              height: 100%;
              width: {{ $yearProgress }}%;
              background: linear-gradient(90deg, {{ $gradient }});
            "></div>
          </div>
          <div class="size-h1" style="margin-top: 6px;">{{ printf "%.2f" $yearProgress }}% of the year has passed</div>
        </div>

- type: custom-api
  title: "Today's Tasks"
  cache: 5m
  url: https://api.todoist.com/rest/v2/tasks?filter=today
  method: GET
  headers:
    Authorization: Bearer ${TODOIST_API_TOKEN}
  template: |
    <style>
      .task-row-todoist {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      .task-checkbox-todoist {
        width: 18px;
        height: 18px;
        border: 2px solid currentColor;
        border-radius: 50%;
        flex-shrink: 0;
        cursor: pointer;
        opacity: 0.6;
        background: transparent;
        padding: 0;
        transition: opacity 0.2s;
      }
      .task-checkbox-todoist:hover {
        opacity: 1;
      }
      .task-content-wrapper-todoist {
        flex: 1;
        min-width: 0;
      }
      .task-row-todoist.completing {
        opacity: 0.5;
        pointer-events: none;
      }
    </style>
    {{ $tasks := .JSON.Array "" }}
    {{ if $tasks }}
      <ul class="list list-gap-14 collapsible-container" data-collapse-after="5">
        {{ range $tasks }}
          <li>
            <div class="task-row-todoist">
              <button class="task-checkbox-todoist"
                      onclick="(function(btn) {
                        const taskRow = btn.closest('.task-row-todoist');
                        taskRow.classList.add('completing');
                        fetch('https://api.todoist.com/rest/v2/tasks/{{ .String "id" }}/close', {
                          method: 'POST',
                          headers: { 'Authorization': 'Bearer ${TODOIST_API_TOKEN}' }
                        })
                        .then(r => {
                          if (r.ok) {
                            const li = btn.closest('li');
                            li.style.transition = 'opacity 0.3s';
                            li.style.opacity = '0';
                            setTimeout(() => li.remove(), 300);
                          } else {
                            taskRow.classList.remove('completing');
                            r.text().then(t => console.error('Failed:', t));
                          }
                        })
                        .catch(e => {
                          taskRow.classList.remove('completing');
                          console.error('Error:', e);
                        });
                      })(this); return false;"
                      title="Complete task"></button>
              <div class="task-content-wrapper-todoist">
                <a class="size-h3 color-primary" href="https://app.todoist.com/app/task/{{ .String "id" }}" target="_blank">
                  {{ .String "content" }}
                </a>
                <ul class="list-horizontal-text">
                  {{ $priority := .Int "priority" }}
                  {{ if eq $priority 4 }}
                    <li>P1</li>
                  {{ else if eq $priority 3 }}
                    <li>P2</li>
                  {{ else if eq $priority 2 }}
                    <li>P3</li>
                  {{ else }}
                    <li>P4</li>
                  {{ end }}
                  {{ if .String "project_id" }}
                    <li data-project-id="{{ .String "project_id" }}">{{ .String "project_id" }}</li>
                  {{ end }}
                </ul>
              </div>
            </div>
          </li>
        {{ end }}
      </ul>
      <img src="x" onerror="(function() {
        fetch('https://api.todoist.com/rest/v2/projects', {
          headers: { 'Authorization': 'Bearer ${TODOIST_API_TOKEN}' }
        })
        .then(r => r.json())
        .then(projects => {
          const projectMap = {};
          projects.forEach(p => projectMap[String(p.id)] = p.name);
          document.querySelectorAll('[data-project-id]').forEach(el => {
            const projectName = projectMap[String(el.getAttribute('data-project-id'))];
            if (projectName) el.textContent = projectName;
          });
        });
      })(); this.parentNode.removeChild(this);" style="display:none;">
    {{ else }}
      <p class="color-subdue">No tasks due today</p>
    {{ end }}

