      </li>
    {{ end }}
    {{ $routeFilter := "${TRANSITLAND_ROUTE_ONESTOP_ID}" }}
    {{ $any := false }}
    {{ range .JSON.Array "stops" }}
      {{ $stop := . }}
      {{ $stopName := .String "stop_name" }}
      {{ $agency := "" }}
      {{ $filteredRouteName := "" }}
      {{ $alertTooltip := "" }}
      {{ $alertColor := "var(--color-primary)" }}
      {{ $dir0Headsign := "" }}
      {{ $dir1Headsign := "" }}
      {{ $dir0NextIso := "" }}
      {{ $dir1NextIso := "" }}
      {{/* metadata pre-walk: parent + children */}}
