        {{ if eq $alertTooltip "" }}{{ range $j, $alert := $dep.Array "trip.route.alerts" }}{{ if eq $j 0 }}{{ $effect := $alert.String "effect" }}{{ if or (eq $effect "NO_SERVICE") (eq $effect "SIGNIFICANT_DELAYS") }}{{ $alertColor = "var(--color-negative)" }}{{ end }}{{ $h := "" }}{{ $d := "" }}{{ range $alert.Array "header_text" }}{{ if and (eq $h "") (eq (.String "language") "en") }}{{ $h = .String "text" }}{{ end }}{{ end }}{{ range $alert.Array "description_text" }}{{ if and (eq $d "") (eq (.String "language") "en") }}{{ $d = .String "text" }}{{ end }}{{ end }}{{ $alertTooltip = print $h "\n\n" $d }}{{ end }}{{ end }}{{ end }}
      {{ end }}
      {{ range $stop.Array "children" }}
        {{ range $dep := .Array "departures" }}
          {{ $matchesFilter := or (eq $routeFilter "") (eq ($dep.String "trip.route.onestop_id") $routeFilter) }}
          {{ if and (eq $agency "") $matchesFilter }}{{ $agency = $dep.String "trip.route.agency.agency_name" }}{{ end }}
          {{ if and (ne $routeFilter "") (eq $filteredRouteName "") (eq ($dep.String "trip.route.onestop_id") $routeFilter) }}{{ $filteredRouteName = $dep.String "trip.route.route_long_name" }}{{ end }}
          {{ if and (ne $routeFilter "") (eq ($dep.String "trip.route.onestop_id") $routeFilter) }}{{ $hs := $dep.String "trip.trip_headsign" }}{{ if eq $hs "" }}{{ $hs = $dep.String "stop_headsign" }}{{ end }}{{ $dir := $dep.Int "trip.direction_id" }}{{ $depEst := $dep.String "departure.estimated_utc" }}{{ $depSched := $dep.String "departure.scheduled_utc" }}{{ $depIso := $depSched }}{{ if ne $depEst "" }}{{ $depIso = $depEst }}{{ end }}{{ if eq $dir 0 }}{{ if eq $dir0Headsign "" }}{{ $dir0Headsign = $hs }}{{ end }}{{ if and (ne $depIso "") (or (eq $dir0NextIso "") (lt $depIso $dir0NextIso)) }}{{ $dir0NextIso = $depIso }}{{ end }}{{ end }}{{ if eq $dir 1 }}{{ if eq $dir1Headsign "" }}{{ $dir1Headsign = $hs }}{{ end }}{{ if and (ne $depIso "") (or (eq $dir1NextIso "") (lt $depIso $dir1NextIso)) }}{{ $dir1NextIso = $depIso }}{{ end }}{{ end }}{{ end }}
          {{ if eq $alertTooltip "" }}{{ range $j, $alert := $dep.Array "trip.route.alerts" }}{{ if eq $j 0 }}{{ $effect := $alert.String "effect" }}{{ if or (eq $effect "NO_SERVICE") (eq $effect "SIGNIFICANT_DELAYS") }}{{ $alertColor = "var(--color-negative)" }}{{ end }}{{ $h := "" }}{{ $d := "" }}{{ range $alert.Array "header_text" }}{{ if and (eq $h "") (eq (.String "language") "en") }}{{ $h = .String "text" }}{{ end }}{{ end }}{{ range $alert.Array "description_text" }}{{ if and (eq $d "") (eq (.String "language") "en") }}{{ $d = .String "text" }}{{ end }}{{ end }}{{ $alertTooltip = print $h "\n\n" $d }}{{ end }}{{ end }}{{ end }}
        {{ end }}
      {{ end }}
      <div class="margin-bottom-10" style="min-width: 0;">
        <div class="flex items-center gap-10" style="min-width: 0;">
          {{ if ne $alertTooltip "" }}
            <span style="background: {{ safeCSS $alertColor }}; color: var(--color-widget-background); border-radius: 50%; width: 1.15rem; height: 1.15rem; font-weight: bold; display: inline-flex; align-items: center; justify-content: center; font-size: 0.8rem; flex-shrink: 0; cursor: help;" title="{{ $alertTooltip }}">!</span>
          {{ end }}
          <div class="size-h3 text-truncate">{{ $stopName }}</div>
        </div>
        {{ if ne $agency "" }}
          <div class="size-h6 color-subdue text-truncate">{{ $agency }}</div>
        {{ end }}
        {{ if ne $filteredRouteName "" }}
          <div class="size-h4 text-truncate">{{ $filteredRouteName }}</div>
        {{ end }}
      </div>
      {{ if eq $routeFilter "" }}
        {{/* No filter: show up to $perRouteCap rows per (route, direction) at their soonest. Glance templates don't expose dict/contains, so we count earlier same-key deps via an O(N^2) inner range. Bump $perRouteCap if you want more rows per line. */}}
        {{ $perRouteCap := 2 }}
        <ul class="list list-gap-10 collapsible-container" data-collapse-after="3">
          {{/* Parent's deps */}}
          {{ $parentDepsRT := $stop.Array "departures" | sortByString "departure.estimated_utc" "asc" }}
          {{ range $i, $dep := $parentDepsRT }}{{ if ne ($dep.String "departure.estimated_utc") "" }}{{ $key := print ($dep.String "trip.route.onestop_id") "|" ($dep.Int "trip.direction_id") }}{{ $count := 0 }}{{ range $j, $other := $parentDepsRT }}{{ if and (lt $j $i) (ne ($other.String "departure.estimated_utc") "") }}{{ if eq $key (print ($other.String "trip.route.onestop_id") "|" ($other.Int "trip.direction_id")) }}{{ $count = add $count 1 }}{{ end }}{{ end }}{{ end }}{{ if lt $count $perRouteCap }}{{ $any = true }}{{ template "depRow" $dep }}{{ end }}{{ end }}{{ end }}
          {{ $parentDepsSched := $stop.Array "departures" | sortByString "departure.scheduled_utc" "asc" }}
          {{ range $i, $dep := $parentDepsSched }}{{ if eq ($dep.String "departure.estimated_utc") "" }}{{ $key := print ($dep.String "trip.route.onestop_id") "|" ($dep.Int "trip.direction_id") }}{{ $count := 0 }}{{ range $j, $other := $parentDepsSched }}{{ if and (lt $j $i) (eq ($other.String "departure.estimated_utc") "") }}{{ if eq $key (print ($other.String "trip.route.onestop_id") "|" ($other.Int "trip.direction_id")) }}{{ $count = add $count 1 }}{{ end }}{{ end }}{{ end }}{{ if lt $count $perRouteCap }}{{ $any = true }}{{ template "depRow" $dep }}{{ end }}{{ end }}{{ end }}
          {{/* Each child's deps */}}
          {{/* Sort children by their soonest dep so cross-child order approximates global time order. */}}
          {{ range $stop.Array "children" | sortByString "departures.0.departure.estimated_utc" "asc" }}
            {{ $childDepsRT := .Array "departures" | sortByString "departure.estimated_utc" "asc" }}
            {{ range $i, $dep := $childDepsRT }}{{ if ne ($dep.String "departure.estimated_utc") "" }}{{ $key := print ($dep.String "trip.route.onestop_id") "|" ($dep.Int "trip.direction_id") }}{{ $count := 0 }}{{ range $j, $other := $childDepsRT }}{{ if and (lt $j $i) (ne ($other.String "departure.estimated_utc") "") }}{{ if eq $key (print ($other.String "trip.route.onestop_id") "|" ($other.Int "trip.direction_id")) }}{{ $count = add $count 1 }}{{ end }}{{ end }}{{ end }}{{ if lt $count $perRouteCap }}{{ $any = true }}{{ template "depRow" $dep }}{{ end }}{{ end }}{{ end }}
            {{ $childDepsSched := .Array "departures" | sortByString "departure.scheduled_utc" "asc" }}
            {{ range $i, $dep := $childDepsSched }}{{ if eq ($dep.String "departure.estimated_utc") "" }}{{ $key := print ($dep.String "trip.route.onestop_id") "|" ($dep.Int "trip.direction_id") }}{{ $count := 0 }}{{ range $j, $other := $childDepsSched }}{{ if and (lt $j $i) (eq ($other.String "departure.estimated_utc") "") }}{{ if eq $key (print ($other.String "trip.route.onestop_id") "|" ($other.Int "trip.direction_id")) }}{{ $count = add $count 1 }}{{ end }}{{ end }}{{ end }}{{ if lt $count $perRouteCap }}{{ $any = true }}{{ template "depRow" $dep }}{{ end }}{{ end }}{{ end }}
          {{ end }}
        </ul>
      {{ else }}
        {{/* Filter active: split by direction so both directions are visible without expanding. Use CSS order so the direction with the sooner next departure appears first. */}}
        {{ $dir0Order := 1 }}{{ $dir1Order := 2 }}
        {{ if and (ne $dir1NextIso "") (or (eq $dir0NextIso "") (gt $dir0NextIso $dir1NextIso)) }}{{ $dir0Order = 2 }}{{ $dir1Order = 1 }}{{ end }}
        <div style="display: flex; flex-direction: column; padding-bottom: 0.5rem;">
          {{ if ne $dir0Headsign "" }}
            <div style="order: {{ $dir0Order }};">
              <div class="size-h5 text-truncate" style="margin-top: {{ if eq $dir0Order 1 }}0.5rem{{ else }}0.4rem{{ end }}; margin-bottom: 0.35rem;"><span class="color-primary">→</span> {{ $dir0Headsign }}</div>
              <ul class="list list-gap-10 collapsible-container" data-collapse-after="2">
                {{ range $stop.Array "departures" | sortByString "departure.estimated_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 0)) (ne (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir0Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "children" }}{{ range .Array "departures" | sortByString "departure.estimated_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 0)) (ne (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir0Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "departures" | sortByString "departure.scheduled_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 0)) (eq (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir0Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "children" }}{{ range .Array "departures" | sortByString "departure.scheduled_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 0)) (eq (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir0Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}{{ end }}
              </ul>
            </div>
          {{ end }}
          {{ if ne $dir1Headsign "" }}
            <div style="order: {{ $dir1Order }};">
              <div class="size-h5 text-truncate" style="margin-top: {{ if eq $dir1Order 1 }}0.5rem{{ else }}0.4rem{{ end }}; margin-bottom: 0.35rem;"><span class="color-primary">→</span> {{ $dir1Headsign }}</div>
              <ul class="list list-gap-10 collapsible-container" data-collapse-after="2">
                {{ range $stop.Array "departures" | sortByString "departure.estimated_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 1)) (ne (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir1Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "children" }}{{ range .Array "departures" | sortByString "departure.estimated_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 1)) (ne (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir1Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "departures" | sortByString "departure.scheduled_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 1)) (eq (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir1Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}
                {{ range $stop.Array "children" }}{{ range .Array "departures" | sortByString "departure.scheduled_utc" "asc" }}{{ if and (and (eq (.String "trip.route.onestop_id") $routeFilter) (eq (.Int "trip.direction_id") 1)) (eq (.String "departure.estimated_utc") "") }}{{ $any = true }}{{ $depHs := .String "trip.trip_headsign" }}{{ if eq $depHs "" }}{{ $depHs = .String "stop_headsign" }}{{ end }}{{ if eq $depHs $dir1Headsign }}{{ template "depRowJustTime" . }}{{ else }}{{ template "depRow" . }}{{ end }}{{ end }}{{ end }}{{ end }}
              </ul>
            </div>
          {{ end }}
        </div>
      {{ end }}
    {{ end }}
    {{ if not $any }}<p class="color-subdue">No upcoming departures</p>{{ end }}

- type: custom-api
  title: TrueNAS Pools
  cache: 1m
  template: |             
    {{
      $dataset := newRequest "${TRUENAS_HOST}/api/v2.0/pool/dataset"
        | withHeader "Authorization" "Bearer ${TRUENAS_API_KEY}"
        | getResponse
    }}
    {{
      $pool := newRequest "${TRUENAS_HOST}/api/v2.0/pool"
        | withHeader "Authorization" "Bearer ${TRUENAS_API_KEY}"
        | getResponse
    }}

    {{ range $dataset.JSON.Array "" }}
      {{ if not (findMatch "/" (.String "name")) }}

        {{ $used := .Float "used.parsed" }}
        {{ $available := .Float "available.parsed" }}
        {{ $total := add $used $available }}

        {{ $totalTb := div (div (div (div $total 1024) 1024) 1024) 1024 | printf "%.1f" }}

        {{ $percent := mul (div $used $total) 100 | printf "%.1f" }}

        {{ $searchString := printf "..#.#(name==\"%s\").healthy|0" (.String "name") }}
        {{ $healthy := $pool.JSON.Bool $searchString }}

        <div style="margin-bottom: 1rem;">
          <div class="color-highlight size-h3">
            {{ if $healthy }}
              <span style="display: inline-block; background-color: var(--color-positive); width: 12px; height: 12px; border-radius: 50%;"></span>
            {{ else }}
              <span style="display: inline-block; background-color: var(--color-negative); width: 12px; height: 12px; border-radius: 50%;"></span>
            {{ end }}
            <span>{{ .String "name" }}</span>
          </div>

          <div class="progress-bar progress-bar-combined" style="position: relative;">
            <div class="flex justify" style="position: absolute; width: 100%; justify-content: center;">
              <span>{{ .String "used.value" }} / {{ $totalTb }}T ({{ $percent }}%)</span>
            </div>
            <div class="progress-value" style="--percent: {{ $percent }}"></div>
          </div>
        </div>

      {{ end }}
    {{ end }}

- type: custom-api
  title: UFC Fight Tracker
  cache: 10m
  url: https://site.api.espn.com/apis/site/v2/sports/mma/ufc/scoreboard
  template: |
    <ul class="list collapsible-container flex flex-column gap-10" data-collapse-after="3" style="list-style: none; padding: 0; margin: 0;">

      {{ $events := .JSON.Array "events" }}

      {{ if $events }}
        {{ range $events }}
          {{ $status := .String "status.type.state" }}
          {{ $dateStr := .String "date" }}
          {{ $eventName := .String "name" }}

          {{ range .Array "competitions" }}

            {{/* VENUE LOGIC: Combine Name + City/State/Country */}}
            {{ $vName := .String "venue.fullName" }}
            {{ $vCity := .String "venue.address.city" }}
            {{ $vCountry := .String "venue.address.country" }}

            {{/* Build location string based on what is available */}}
            {{ $location := $vName }}
            {{ if $vCity }}
              {{ $location = print $location " • " $vCity }}
              {{ if $vCountry }}
                  {{ $location = print $location ", " $vCountry }}
              {{ end }}
            {{ end }}

            <li>
              <div style="background: rgba(255,255,255,0.03); border-radius: 8px; padding: 12px; border: 1px solid rgba(255,255,255,0.05);">

                <div class="flex justify-between items-center" style="margin-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.1); padding-bottom: 8px;">
                  <div class="text-truncate" style="font-weight: 700; color: var(--color-highlight); font-size: 0.9em; max-width: 60%;">
                    {{ $eventName }}
                  </div>
                  <div style="font-size: 0.75em; font-family: monospace; text-align: right;">
                    {{ if eq $status "in" }}
                      <span style="color: #ef4444; font-weight: bold; animation: pulse 2s infinite;">🔴 LIVE R{{ .String "status.period" }}</span>
                    {{ else if eq $status "post" }}
                      <span style="color: var(--color-subdue);">FINAL</span>
                    {{ else }}
                      {{ if $dateStr }}
                        {{ $t := parseTime "2006-01-02T15:04Z" $dateStr }}
                        📅 {{ $t.Local.Format "02. Jan • 15:04" }}
                      {{ end }}
                    {{ end }}
                  </div>
                </div>

                <div style="display: grid; grid-template-columns: 1fr 40px 1fr; align-items: center;">
                  {{ range $index, $competitor := .Array "competitors" }}

                    {{ if eq $index 1 }}
                      <div style="text-align: center; font-size: 0.75em; color: var(--color-subdue); font-weight: bold; grid-column: 2;">VS</div>
                    {{ end }}

                    <div style="grid-column: {{ if eq $index 0 }}1{{ else }}3{{ end }}; display: flex; align-items: center; {{ if eq $index 0 }}justify-content: flex-end; text-align: right;{{ else }}justify-content: flex-start; text-align: left;{{ end }}">

                      <div style="display: flex; align-items: center; gap: 12px; {{ if eq $index 1 }}flex-direction: row-reverse;{{ end }}">
                        <div style="min-width: 0;">
                          <div style="display: flex; align-items: center; gap: 6px; {{ if eq $index 0 }}justify-content: flex-end;{{ else }}justify-content: flex-start;{{ end }}">
                            {{ if and (eq $index 0) (.String "athlete.flag.href") }}
                                <img src="{{ .String "athlete.flag.href" }}" style="width: 14px; height: 10px; opacity: 0.8; border-radius: 2px;">
                            {{ end }}

                            <span class="text-truncate" style="font-weight: bold; font-size: 0.9em; {{ if .Bool "winner" }}color: #22c55e;{{ end }}">
                              {{ .String "athlete.displayName" }}
                            </span>

                            {{ if and (eq $index 1) (.String "athlete.flag.href") }}
                                <img src="{{ .String "athlete.flag.href" }}" style="width: 14px; height: 10px; opacity: 0.8; border-radius: 2px;">
                            {{ end }}
                          </div>

                          <div style="font-size: 0.75em; opacity: 0.6; margin-top: 2px;">
                            {{ if .String "curatedRank.current" }}<span style="color:var(--color-highlight)">#{{ .String "curatedRank.current" }}</span> • {{ end }}
                            {{ .String "records.0.summary" }}
                          </div>
                        </div>

                        <div style="position: relative; width: 42px; height: 42px; shrink: 0;">
                          <img src="{{ .String "athlete.headshot.href" }}" 
                                style="width: 100%; height: 100%; object-fit: cover; border-radius: 50%; background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.1);"
                                onerror="this.style.opacity='0'">
                        </div>
                      </div>
                    </div>
                  {{ end }}
                </div>

                <div style="margin-top: 10px; font-size: 0.7em; text-align: center; opacity: 0.4;">
                  📍 {{ $location }}
                </div>

              </div>
            </li>
          {{ end }}
        {{ end }}
      {{ else }}
        <div class="color-subdue">No scheduled fights found.</div>
      {{ end }}
    </ul>

- type: custom-api
  title: Unraid
  url: ${UNRAID_API_URL}
  method: POST
  body-type: json
  body:
    query: |
      query GetDashboardData {
        info {
          os {
            uptime
          }
        }
        metrics {
          cpu {
            percentTotal
          }
          memory {
            total
            used
            free
            percentTotal
          }
        }
        array {
          state
          parityCheckStatus {
            status
          }
          parities {
            name
            temp
          }
          disks {
            name
            temp
            size
            status
          }
        }
        parityHistory {
          date
          status
          duration
          errors
        }
        shares {
          name
          used
          free
          size
        }
      }
  headers:
    "x-api-key": ${UNRAID_API_KEY}
    Accept: application/json
  skip-json-validation: true
  allow-insecure: true
  template: |
    <div style="display:flex; flex-direction:column; gap:16px;">

      <div>
        <div class="size-h6 color-paragraph" style="text-transform:uppercase; font-weight:bold; letter-spacing:1px; border-bottom:1px solid rgba(128,128,128,0.2); padding-bottom:4px; margin-bottom:10px;">
          Server Health
        </div>

        <div style="display:flex; flex-direction:row-reverse; flex-wrap:wrap-reverse; justify-content:space-between; align-items:flex-start; background:rgba(128,128,128,0.1); padding:12px; border-radius:6px; gap:24px;">

          <div style="display:flex; flex-direction:column; align-items:flex-end; text-align:right; gap:6px; justify-content:flex-start; flex:1 1 calc(50% - 12px); min-width:200px; box-sizing:border-box;">

            {{ $bootRaw := .JSON.String "data.info.os.uptime" }}
            <div class="color-paragraph" style="opacity:0.7; font-size:11px; font-weight:normal; width:100%;">
              Boot: <span style="font-weight:normal; opacity:0.9;">{{ printf "%.10s %.5s" $bootRaw (slice $bootRaw 11 16) }}</span>
            </div>

            {{ $arrayState := .JSON.String "data.array.state" }}
            <div class="color-paragraph" style="font-size:11px; font-weight:normal; width:100%;">
              Array: <span style="font-weight:bold; color:{{ if eq $arrayState "STARTED" }}var(--color-positive){{ else }}var(--color-warning){{ end }};">{{ $arrayState }}</span>
            </div>

            {{ $currentParity := .JSON.String "data.array.parityCheckStatus.status" }}
            {{ $lastCheckDate := .JSON.String "data.parityHistory.0.date" }}

            <div data-popover-type="text" data-popover-text="Checked: {{ if $lastCheckDate }}{{ printf "%.10s" $lastCheckDate }}{{ else }}Unknown{{ end }}" style="cursor: pointer; width:100%; font-size:11px; font-weight:normal;" class="color-paragraph">
              Parity: <span style="font-weight:bold; color:{{ if eq $currentParity "VALID" "OK" "COMPLETED" }}var(--color-positive){{ else }}var(--color-warning){{ end }};">{{ if $currentParity }}{{ $currentParity }}{{ else }}OK{{ end }}</span>
            </div>

          </div>

          <div style="display:flex; flex-direction:column; gap:10px; flex:1 1 calc(50% - 12px); min-width:200px; box-sizing:border-box;">
            {{ $cpuPct := .JSON.Float "data.metrics.cpu.percentTotal" }}
            {{ $ramPct := .JSON.Float "data.metrics.memory.percentTotal" }}

            <div style="display:flex; flex-direction:column; gap:8px; width:100%;">
              <div style="display:flex; flex-direction:column; gap:4px;">
                <div style="display:flex; align-items:center; gap:4px; justify-content:space-between;" class="size-sm">
                  <div style="display:flex; align-items:center; gap:4px;" class="color-paragraph">
                    <span>CPU</span>
                    {{ if ge $cpuPct 80.0 }}
                    <svg style="width:12px; height:12px;" fill="var(--color-negative, #f44336)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
                      <path fill-rule="evenodd" d="M8.074.945A4.993 4.993 0 0 0 6 5v.032c.004.6.114 1.176.311 1.709.16.428-.204.91-.61.7a5.023 5.023 0 0 1-1.868-1.677c-.202-.304-.648-.363-.848-.058a6 6 0 1 0 8.017-1.901l-.004-.007a4.98 4.98 0 0 1-2.18-2.574c-.116-.31-.477-.472-.744-.28Zm.78 6.178a3.001 3.001 0 1 1-3.473 4.341c-.205-.365.215-.694.62-.59a4.008 4.008 0 0 0 1.873.03c.288-.065.413-.386.321-.666A3.997 3.997 0 0 1 8 8.999c0-.585.126-1.14.351-1.641a.42.42 0 0 1 .503-.235Z" clip-rule="evenodd" />
                    </svg>
                    {{ end }}
                  </div>
                  <div class="color-highlight" style="font-weight:bold; font-size:11px;">{{ printf "%.0f" $cpuPct }}%</div>
                </div>
                <div style="width:100%; height:4px; background:rgba(128,128,128,0.15); border-radius:2px; overflow:hidden;">
                  <div style="width: {{ $cpuPct }}%; height:100%; background:{{ if ge $cpuPct 80.0 }}var(--color-negative, #f44336){{ else }}var(--color-primary, #4caf50){{ end }};"></div>
                </div>
              </div>

              <div data-popover-type="text" data-popover-text="Usage: {{ printf "%.0f" $ramPct }}%" style="cursor: pointer; display:flex; flex-direction:column; gap:4px;">
                <div style="width:100%; display:flex; align-items:center; justify-content:space-between;" class="size-sm">
                  <span class="color-paragraph">RAM</span>
                  <div class="color-highlight" style="font-weight:bold; font-size:11px;">{{ printf "%.0f" $ramPct }}%</div>
                </div>
                <div style="width:100%; height:4px; background:rgba(128,128,128,0.15); border-radius:2px; overflow:hidden;">
                  <div style="width: {{ $ramPct }}%; height:100%; background:{{ if ge $ramPct 85.0 }}var(--color-warning, #ff9800){{ else }}var(--color-primary, #4caf50){{ end }};"></div>
                </div>
              </div>
            </div>
          </div>

        </div>
      </div>

      <div>
        <div class="size-h6 color-paragraph" style="text-transform:uppercase; font-weight:bold; letter-spacing:1px; border-bottom:1px solid rgba(128,128,128,0.2); padding-bottom:4px; margin-bottom:10px;">
          Storage Array Devices
        </div>
        <div style="display:grid; grid-template-columns: repeat(3, 1fr); gap:8px;">
          {{ range .JSON.Array "data.array.disks" }}
            {{ $diskName := .String "name" }}
            {{ $diskStatus := .String "status" }}
            {{ $diskTemp := .Float "temp" }}

            {{ if not (eq $diskName "flash") }}
              <div style="background:rgba(0,0,0,0.15); padding:8px; border-radius:6px; display:flex; flex-direction:column; align-items:center; justify-content:center; border: 1px solid rgba(128,128,128,0.05); position:relative;">

                {{ $isOnline := eq $diskStatus "DISK_OK" "active" "normal" }}
                <div style="position:absolute; top:8px; right:8px; width:8px; height:8px; border-radius:50%; background-color:var(--color-{{ if $isOnline }}positive{{ else }}negative{{ end }}); box-shadow:0 0 6px var(--color-{{ if $isOnline }}positive{{ else }}negative{{ end }});"></div>

                <div class="size-sm color-highlight" style="font-weight:bold; margin-bottom:2px; margin-top:4px;">{{ $diskName }}</div>

                {{ if $isOnline }}
                  <div class="size-sm color-paragraph" style="font-size:11px; font-weight:bold; margin-top:2px;">{{ printf "%.0f" $diskTemp }}°C</div>
                {{ else }}
                  <div class="size-sm color-error" style="font-size:10px; font-weight:bold; margin-top:2px;">OFFLINE</div>
                {{ end }}
              </div>
            {{ end }}
          {{ end }}
        </div>
      </div>

      <div>
        <div class="size-h6 color-paragraph" style="text-transform:uppercase; font-weight:bold; letter-spacing:1px; border-bottom:1px solid rgba(128,128,128,0.2); padding-bottom:4px; margin-bottom:12px;">
          User Share Capacity
        </div>

        <div style="display:flex; flex-direction:column; gap:12px;">
        {{ range .JSON.Array "data.shares" }}
          {{ $shareName := .String "name" }}
          {{ $usedRaw := .Float "used" }}
          {{ $freeRaw := .Float "free" }}

          {{ $totalRaw := add $usedRaw $freeRaw }}

          {{ $pctUsed := 0.0 }}
          {{ if lt 0.0 $totalRaw }}
            {{ $pctUsed = mul (div $usedRaw $totalRaw) 100.0 }}
          {{ end }}

          {{ $usedText := "" }}
          {{ if ge $usedRaw 1000000000.0 }}
            {{ $usedText = printf "%.1f TB" (div $usedRaw 1000000000.0) }}
          {{ else }}
            {{ $usedText = printf "%.1f GB" (div $usedRaw 1000000.0) }}
          {{ end }}

          {{ $totalText := "" }}
          {{ if ge $totalRaw 1000000000.0 }}
            {{ $totalText = printf "%.1f TB" (div $totalRaw 1000000000.0) }}
          {{ else }}
            {{ $totalText = printf "%.1f GB" (div $totalRaw 1000000.0) }}
          {{ end }}

          {{ $freeText := "" }}
          {{ if ge $freeRaw 1000000000.0 }}
            {{ $freeText = printf "%.1f TB" (div $freeRaw 1000000000.0) }}
          {{ else }}
            {{ $freeText = printf "%.1f GB" (div $freeRaw 1000000.0) }}
          {{ end }}

          <div style="display:flex; flex-direction:column; gap:4px;">
            <div style="display:flex; justify-content:space-between; align-items: baseline;">
              <span class="size-sm color-highlight" style="font-weight: bold;">📂 {{ $shareName }}</span>
              <span class="size-sm color-paragraph" style="font-size:11px; font-weight:bold;">{{ printf "%.0f%%" $pctUsed }}</span>
            </div>

            <div data-popover-type="text" data-popover-text="Used: {{ $usedText }} / Total: {{ $totalText }}" style="cursor: pointer;">
              <div style="width:100%; height:6px; background:rgba(128, 128, 128, 0.15); border-radius:3px; overflow:hidden;">
                <div style="width: {{ $pctUsed }}%; height:100%; background:{{ if ge $pctUsed 85.0 }}var(--color-warning, #ff9800){{ else }}var(--color-primary, #4caf50){{ end }};"></div>
              </div>
            </div>

            <div style="display:flex; justify-content:space-between; font-size:10px;" class="color-paragraph">
              <span>Used: {{ $usedText }}</span>
              <span>Free: {{ $freeText }}</span>
            </div>
          </div>
        {{ end }}
        </div>
      </div>

    </div>

- type: custom-api
  title: Uptime Kumas
  title-url: ${UPTIME_KUMA_URL}
  url: ${UPTIME_KUMA_URL}/api/status-page/${UPTIME_KUMA_STATUS_SLUG}
  subrequests:
    heartbeats:
      url: ${UPTIME_KUMA_URL}/api/status-page/heartbeat/${UPTIME_KUMA_STATUS_SLUG}
  cache: 10m
  template: |
    {{ $hb := .Subrequest "heartbeats" }}

    {{ if not (.JSON.Exists "publicGroupList") }}
    <p class="color-negative">Error reading response</p>
    {{ else if eq (len (.JSON.Array "publicGroupList")) 0 }}
    <p>No monitors found</p>
    {{ else }}

    <ul class="dynamic-columns list-gap-8">
      {{ range .JSON.Array "publicGroupList" }}
      {{ range .Array "monitorList" }}
      {{ $id := .String "id" }}
      {{ $hbArray := $hb.JSON.Array (print "heartbeatList." $id) }}
      <div class="flex items-center gap-12">
        <a class="size-title-dynamic color-highlight text-truncate block grow" href="${UPTIME_KUMA_URL}/dashboard/{{ $id }}"
          target="_blank" rel="noreferrer">
          {{ .String "name" }} </a>

        {{ if gt (len $hbArray) 0 }}
          {{ $latest := index $hbArray (sub (len $hbArray) 1) }}
          {{ if eq ($latest.Int "status") 1 }}
          <div>{{ $latest.Int "ping" }}ms</div>
          <div class="monitor-site-status-icon-compact" title="OK">
            <svg fill="var(--color-positive)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
              <path fill-rule="evenodd"
                d="M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16Zm3.857-9.809a.75.75 0 0 0-1.214-.882l-3.483 4.79-1.88-1.88a.75.75 0 1 0-1.06 1.061l2.5 2.5a.75.75 0 0 0 1.137-.089l4-5.5Z"
                clip-rule="evenodd"></path>
            </svg>
          </div>
          {{ else }}
          <div><span class="color-negative">DOWN</span></div>
          <div class="monitor-site-status-icon-compact" title="{{ if $latest.Exists "msg" }}{{ $latest.String "msg" }}{{ else
            }}Error{{ end }}">
            <svg fill="var(--color-negative)" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20">
              <path fill-rule="evenodd"
                d="M8.485 2.495c.673-1.167 2.357-1.167 3.03 0l6.28 10.875c.673 1.167-.17 2.625-1.516 2.625H3.72c-1.347 0-2.189-1.458-1.515-2.625L8.485 2.495ZM10 5a.75.75 0 0 1 .75.75v3.5a.75.75 0 0 1-1.5 0v-3.5A.75.75 0 0 1 10 5Zm0 9a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z"
                clip-rule="evenodd"></path>
            </svg>
